fn upstream_client_for_profile(profile: &ProxyProfile) -> Result<Client, ()> {
    upstream_client_for_profile_with_timeout(profile, Duration::from_secs(120))
}

fn upstream_client_for_profile_with_timeout(
    profile: &ProxyProfile,
    timeout: Duration,
) -> Result<Client, ()> {
    upstream_client_for_profile_with_timeout_and_emulation(
        profile,
        timeout,
        wreq_util::Emulation::Chrome110,
    )
}

fn upstream_client_for_profile_with_timeout_and_emulation(
    profile: &ProxyProfile,
    timeout: Duration,
    emulation: wreq_util::Profile,
) -> Result<Client, ()> {
    let mut builder = Client::builder()
        .no_proxy()
        .emulation(emulation)
        .cookie_store(true)
        .connect_timeout(Duration::from_secs(10))
        .timeout(timeout);
    if !profile.proxy_url.is_empty() {
        let Ok(proxy) = reqwest::Proxy::all(&profile.proxy_url) else {
            return Ok(fail_closed_proxy_client());
        };
        builder = builder.proxy(proxy);
    }
    if profile.skip_ssl_verify {
        builder = builder
            .tls_cert_verification(false)
            .tls_verify_hostname(false);
    }
    match builder.build() {
        Ok(client) => Ok(client),
        Err(_) => Ok(fail_closed_proxy_client()),
    }
}

fn fail_closed_proxy_client() -> Client {
    static CLIENT: LazyLock<Client> = LazyLock::new(|| {
        let proxy = reqwest::Proxy::all("http://127.0.0.1:0")
            .expect("fixed fail-closed proxy URL must parse");
        Client::builder()
            .no_proxy()
            .connect_timeout(Duration::from_millis(250))
            .timeout(Duration::from_secs(1))
            .proxy(proxy)
            .build()
            .expect("fixed fail-closed proxy client must build")
    });
    CLIENT.clone()
}

fn legacy_global_proxy_url(state: &AppState) -> String {
    fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .and_then(|config| {
            config
                .get("proxy")
                .and_then(Value::as_str)
                .map(ToOwned::to_owned)
        })
        .unwrap_or_default()
}

fn native_chat_proxy_profile(
    runtime: &Value,
    account_proxy: Option<&str>,
    legacy_proxy: Option<&str>,
) -> ProxyProfile {
    proxy_service::profile_from_runtime(runtime, account_proxy, None, legacy_proxy, false, false)
}

fn native_chat_upstream_client(state: &AppState, lease: Option<&AccountLease>) -> Client {
    let legacy_proxy = legacy_global_proxy_url(state);
    let profile = native_chat_proxy_profile(
        &proxy_runtime_value(state),
        lease.and_then(AccountLease::proxy_url),
        Some(&legacy_proxy),
    );
    upstream_client_for_profile_with_timeout_and_emulation(
        &profile,
        Duration::from_secs(120),
        lease
            .map(AccountLease::tls_emulation)
            .unwrap_or(wreq_util::Emulation::Chrome110),
    )
    .unwrap_or_else(|_| state.client.clone())
}

fn upstream_client_for_lease(state: &AppState, lease: &AccountLease, resource: bool) -> Client {
    upstream_client_for_lease_with_timeout(state, lease, resource, Duration::from_secs(120))
}

fn upstream_client_for_lease_with_timeout(
    state: &AppState,
    lease: &AccountLease,
    resource: bool,
    timeout: Duration,
) -> Client {
    let runtime = proxy_runtime_value(state);
    let legacy_proxy = legacy_global_proxy_url(state);
    let profile = proxy_service::profile_from_runtime(
        &runtime,
        lease.proxy_url(),
        None,
        Some(&legacy_proxy),
        resource,
        false,
    );
    upstream_client_for_profile_with_timeout_and_emulation(&profile, timeout, lease.tls_emulation())
        .unwrap_or_else(|_| state.client.clone())
}

fn upstream_client_for_account_proxy(
    state: &AppState,
    lease: &AccountLease,
    resource: bool,
) -> Client {
    let legacy_proxy = legacy_global_proxy_url(state);
    let profile = proxy_service::profile_from_runtime(
        &proxy_runtime_value(state),
        lease.proxy_url(),
        None,
        Some(&legacy_proxy),
        resource,
        false,
    );
    upstream_client_for_profile_with_timeout_and_emulation(
        &profile,
        Duration::from_secs(120),
        lease.tls_emulation(),
    )
    .unwrap_or_else(|_| state.client.clone())
}

fn legacy_global_proxy_profile(state: &AppState) -> ProxyProfile {
    let legacy_proxy = legacy_global_proxy_url(state);
    proxy_service::profile_from_runtime(
        &proxy_runtime_value(state),
        None,
        None,
        Some(&legacy_proxy),
        false,
        false,
    )
}

fn legacy_global_proxy_client(state: &AppState) -> Client {
    let profile = legacy_global_proxy_profile(state);
    if profile.proxy_url.is_empty() && !profile.skip_ssl_verify {
        return state.client.clone();
    }
    upstream_client_for_profile(&profile).unwrap_or_else(|_| state.client.clone())
}
