#[derive(Default)]
struct ChatCacheState {
    entries: HashMap<String, ChatCacheEntry>,
    inflight: HashMap<String, Arc<ChatCacheInflight>>,
    response_inflight: HashMap<String, Arc<ChatCacheResponseInflight>>,
}

struct ChatCacheEntry {
    expires_at: SystemTime,
    value: Value,
}

struct ChatCacheInflight {
    notify: tokio::sync::Notify,
    result: StdMutex<Option<Result<Vec<Vec<u8>>, String>>>,
    ttl_seconds: u64,
    max_entries: usize,
}

struct ChatCacheResponseInflight {
    notify: tokio::sync::Notify,
    result: StdMutex<Option<Result<Value, String>>>,
    ttl_seconds: u64,
    max_entries: usize,
}

impl ChatCacheInflight {
    fn new(ttl_seconds: u64, max_entries: usize) -> Self {
        Self {
            notify: tokio::sync::Notify::new(),
            result: StdMutex::new(None),
            ttl_seconds,
            max_entries,
        }
    }
}

impl ChatCacheResponseInflight {
    fn new(ttl_seconds: u64, max_entries: usize) -> Self {
        Self {
            notify: tokio::sync::Notify::new(),
            result: StdMutex::new(None),
            ttl_seconds,
            max_entries,
        }
    }
}

fn chat_cache_config(state: &AppState) -> Value {
    fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .and_then(|value| value.get("chat_completion_cache").cloned())
        .unwrap_or_else(|| json!({}))
}

fn normalize_cache_message(value: &Value) -> Value {
    let Some(message) = value.as_object() else {
        return value.clone();
    };
    let role = message
        .get("role")
        .cloned()
        .unwrap_or_else(|| Value::String("user".to_owned()));
    let content = match message.get("content") {
        Some(Value::String(text)) => Value::String(text.clone()),
        Some(Value::Array(parts)) => {
            let mut text = String::new();
            let mut has_image = false;
            for part in parts {
                match part {
                    Value::String(value) => text.push_str(value),
                    Value::Object(part)
                        if matches!(
                            part.get("type").and_then(Value::as_str),
                            Some("text" | "input_text" | "output_text")
                        ) =>
                    {
                        text.push_str(&protocol_anthropic::python_text(part.get("text")));
                    }
                    Value::Object(part)
                        if part
                            .get("type")
                            .and_then(Value::as_str)
                            .map(str::trim)
                            .is_some_and(|kind| {
                                role.as_str() == Some("user")
                                    && matches!(kind, "image" | "image_url" | "input_image")
                            }) =>
                    {
                        has_image = true;
                    }
                    _ => {}
                }
            }
            if has_image {
                Value::Array(parts.clone())
            } else {
                Value::String(text)
            }
        }
        _ => Value::String(String::new()),
    };
    json!({"role": role, "content": content})
}

fn normalize_cached_messages_with_config(value: &Value, config: &Value) -> Value {
    let Some(messages) = value.as_array() else {
        return value.clone();
    };
    let canonical_messages = messages
        .iter()
        .map(normalize_cache_message)
        .collect::<Vec<_>>();
    if !settings_bool(config.get("normalize_messages"), true) {
        return Value::Array(canonical_messages);
    }
    let drop_assistant = settings_bool(config.get("drop_assistant_history"), false);
    let drop_duplicates = settings_bool(config.get("drop_adjacent_duplicates"), true);
    let mut normalized = Vec::new();
    let mut previous = None;
    for message in canonical_messages {
        if drop_assistant && message.get("role").and_then(Value::as_str) == Some("assistant") {
            continue;
        }
        let signature =
            serde_json::to_string(&canonicalize_cache_value(&message)).unwrap_or_default();
        if drop_duplicates && previous.as_deref() == Some(signature.as_str()) {
            continue;
        }
        previous = Some(signature);
        normalized.push(message);
    }
    Value::Array(normalized)
}

fn normalize_chat_text_messages_with_config(object: &mut Map<String, Value>, config: &Value) {
    let messages = object
        .get("messages")
        .and_then(Value::as_array)
        .filter(|messages| !messages.is_empty())
        .cloned()
        .or_else(|| {
            object
                .get("prompt")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|prompt| !prompt.is_empty())
                .map(|prompt| vec![json!({"role":"user","content":prompt})])
        });
    if let Some(messages) = messages {
        let normalized = normalize_cached_messages_with_config(&Value::Array(messages), config);
        object.insert("messages".to_owned(), normalized);
    }
}

fn normalize_chat_text_messages(state: &AppState, object: &mut Map<String, Value>) {
    normalize_chat_text_messages_with_config(object, &chat_cache_config(state));
}

fn canonicalize_cache_value(value: &Value) -> Value {
    match value {
        Value::Object(object) => {
            let mut entries = object.iter().collect::<Vec<_>>();
            entries.sort_by_key(|(left, _)| *left);
            let mut sorted = Map::new();
            for (key, value) in entries {
                sorted.insert(key.clone(), canonicalize_cache_value(value));
            }
            Value::Object(sorted)
        }
        Value::Array(values) => Value::Array(values.iter().map(canonicalize_cache_value).collect()),
        _ => value.clone(),
    }
}

fn chat_cache_key(body: &Map<String, Value>, messages: &Value, stream: bool) -> Option<String> {
    let mut canonical = Map::new();
    for key in [
        "frequency_penalty",
        "max_completion_tokens",
        "max_tokens",
        "metadata",
        "model",
        "presence_penalty",
        "reasoning_effort",
        "response_format",
        "seed",
        "stop",
        "temperature",
        "thinking_effort",
        "tool_choice",
        "tools",
        "top_p",
        "user",
        "reasoning",
    ] {
        if let Some(value) = body.get(key) {
            canonical.insert(key.to_owned(), value.clone());
        }
    }
    canonical.insert("messages".to_owned(), messages.clone());
    canonical.insert("stream".to_owned(), Value::Bool(stream));
    let bytes = serde_json::to_vec(&canonicalize_cache_value(&Value::Object(canonical))).ok()?;
    Some(format!("{:x}", Sha256::digest(bytes)))
}

fn chat_cache_enabled(state: &AppState, stream: bool) -> Option<(u64, usize, bool)> {
    let config = chat_cache_config(state);
    if !settings_bool(config.get("enabled"), true)
        || (stream && !settings_bool(config.get("stream_cache"), true))
    {
        return None;
    }
    let ttl = settings_u64(config.get("ttl_seconds"), 60, 0);
    (ttl > 0).then(|| {
        (
            ttl,
            settings_u64(config.get("max_entries"), 256, 1) as usize,
            settings_bool(config.get("dedupe_inflight"), true),
        )
    })
}

fn prune_chat_cache_entries(cache: &mut ChatCacheState, now: SystemTime, max_entries: usize) {
    cache.entries.retain(|_, item| now < item.expires_at);
    while cache.entries.len() > max_entries {
        let Some(oldest) = cache
            .entries
            .iter()
            .min_by_key(|(_, item)| item.expires_at)
            .map(|(key, _)| key.clone())
        else {
            break;
        };
        cache.entries.remove(&oldest);
    }
}

fn chat_cache_read(state: &AppState, key: &str) -> Option<Value> {
    let (_, max_entries, _) = chat_cache_enabled(state, false)?;
    let mut cache = state.chat_cache.lock().ok()?;
    prune_chat_cache_entries(&mut cache, SystemTime::now(), max_entries);
    cache.entries.get(key).map(|entry| entry.value.clone())
}

fn chat_cache_write_with_settings(
    state: &AppState,
    key: String,
    value: Value,
    ttl: u64,
    max_entries: usize,
) {
    if let Ok(mut cache) = state.chat_cache.lock() {
        let now = SystemTime::now();
        let Some(expires_at) = now.checked_add(Duration::from_secs(ttl)) else {
            return;
        };
        cache
            .entries
            .insert(key, ChatCacheEntry { expires_at, value });
        prune_chat_cache_entries(&mut cache, now, max_entries);
    }
}

fn chat_cache_write(state: &AppState, key: String, value: Value) {
    let Some((ttl, max_entries, _)) = chat_cache_enabled(state, false) else {
        return;
    };
    chat_cache_write_with_settings(state, key, value, ttl, max_entries);
}
fn chat_cache_write_stream_with_settings(
    state: &AppState,
    key: String,
    value: Value,
    ttl: u64,
    max_entries: usize,
) {
    if let Ok(mut cache) = state.chat_cache.lock() {
        let now = SystemTime::now();
        let Some(expires_at) = now.checked_add(Duration::from_secs(ttl)) else {
            return;
        };
        cache
            .entries
            .insert(key, ChatCacheEntry { expires_at, value });
        prune_chat_cache_entries(&mut cache, now, max_entries);
    }
}

fn chat_cache_write_stream(state: &AppState, key: String, value: Value) {
    let Some((ttl, max_entries, _)) = chat_cache_enabled(state, true) else {
        return;
    };
    chat_cache_write_stream_with_settings(state, key, value, ttl, max_entries);
}

fn chat_cache_read_stream(state: &AppState, key: &str) -> Option<Value> {
    let (_, max_entries, _) = chat_cache_enabled(state, true)?;
    let mut cache = state.chat_cache.lock().ok()?;
    prune_chat_cache_entries(&mut cache, SystemTime::now(), max_entries);
    cache.entries.get(key).map(|entry| entry.value.clone())
}

fn chat_cache_begin_stream(state: &AppState, key: &str) -> Option<(Arc<ChatCacheInflight>, bool)> {
    let (ttl_seconds, max_entries, dedupe_inflight) = chat_cache_enabled(state, true)?;
    let mut cache = state.chat_cache.lock().ok()?;
    let now = SystemTime::now();
    prune_chat_cache_entries(&mut cache, now, max_entries);
    if cache.entries.contains_key(key) {
        return None;
    }
    if dedupe_inflight && let Some(entry) = cache.inflight.get(key) {
        return Some((entry.clone(), false));
    }
    let entry = Arc::new(ChatCacheInflight::new(ttl_seconds, max_entries));
    if dedupe_inflight {
        cache.inflight.insert(key.to_owned(), entry.clone());
    }
    Some((entry, true))
}

enum ChatCacheResponseStart {
    Cached(Value),
    Owner(Arc<ChatCacheResponseInflight>),
    Waiter(Arc<ChatCacheResponseInflight>),
}

fn chat_cache_begin_response(state: &AppState, key: &str) -> Option<ChatCacheResponseStart> {
    let (ttl_seconds, max_entries, dedupe_inflight) = chat_cache_enabled(state, false)?;
    let mut cache = state.chat_cache.lock().ok()?;
    prune_chat_cache_entries(&mut cache, SystemTime::now(), max_entries);
    if let Some(entry) = cache.entries.get(key) {
        return Some(ChatCacheResponseStart::Cached(entry.value.clone()));
    }
    if dedupe_inflight && let Some(entry) = cache.response_inflight.get(key) {
        return Some(ChatCacheResponseStart::Waiter(entry.clone()));
    }
    let entry = Arc::new(ChatCacheResponseInflight::new(ttl_seconds, max_entries));
    if dedupe_inflight {
        cache
            .response_inflight
            .insert(key.to_owned(), entry.clone());
    }
    Some(ChatCacheResponseStart::Owner(entry))
}

async fn chat_cache_wait_response(
    inflight: &Arc<ChatCacheResponseInflight>,
) -> Result<Value, ApiError> {
    loop {
        let notified = inflight.notify.notified();
        tokio::pin!(notified);
        notified.as_mut().enable();
        if let Some(result) = inflight
            .result
            .lock()
            .ok()
            .and_then(|result| result.clone())
        {
            return result.map_err(|_| ApiError::upstream());
        }
        notified.await;
    }
}

fn chat_cache_finish_response(
    state: &AppState,
    key: &str,
    inflight: &Arc<ChatCacheResponseInflight>,
    result: Result<Value, String>,
) {
    if let Ok(value) = &result {
        chat_cache_write_with_settings(
            state,
            key.to_owned(),
            value.clone(),
            inflight.ttl_seconds,
            inflight.max_entries,
        );
    }
    if let Ok(mut slot) = inflight.result.lock() {
        *slot = Some(result);
    }
    if let Ok(mut cache) = state.chat_cache.lock() {
        cache.response_inflight.remove(key);
    }
    inflight.notify.notify_waiters();
}

struct ChatCacheResponseOwner {
    state: AppState,
    key: String,
    inflight: Arc<ChatCacheResponseInflight>,
    finished: bool,
}

impl ChatCacheResponseOwner {
    fn new(state: AppState, key: String, inflight: Arc<ChatCacheResponseInflight>) -> Self {
        Self {
            state,
            key,
            inflight,
            finished: false,
        }
    }

    fn finish(&mut self, result: Result<Value, String>) {
        if self.finished {
            return;
        }
        self.finished = true;
        chat_cache_finish_response(&self.state, &self.key, &self.inflight, result);
    }

    fn complete(mut self, value: Value) {
        self.finish(Ok(value));
    }
}

impl Drop for ChatCacheResponseOwner {
    fn drop(&mut self) {
        self.finish(Err("upstream request failed".to_owned()));
    }
}

struct ChatCacheStreamOwner {
    state: AppState,
    key: String,
    inflight: Arc<ChatCacheInflight>,
    transferred: bool,
}

impl ChatCacheStreamOwner {
    fn new(state: AppState, key: String, inflight: Arc<ChatCacheInflight>) -> Self {
        Self {
            state,
            key,
            inflight,
            transferred: false,
        }
    }

    fn into_parts(mut self) -> (String, Arc<ChatCacheInflight>) {
        self.transferred = true;
        (self.key.clone(), self.inflight.clone())
    }
}

impl Drop for ChatCacheStreamOwner {
    fn drop(&mut self) {
        if !self.transferred {
            chat_cache_finish_stream(
                &self.state,
                &self.key,
                &self.inflight,
                Err("upstream request failed".to_owned()),
            );
        }
    }
}

async fn chat_cache_wait_stream(
    inflight: &Arc<ChatCacheInflight>,
) -> Result<Vec<Vec<u8>>, ApiError> {
    loop {
        let notified = inflight.notify.notified();
        tokio::pin!(notified);
        notified.as_mut().enable();
        if let Some(result) = inflight
            .result
            .lock()
            .ok()
            .and_then(|result| result.clone())
        {
            return result.map_err(|_| ApiError::upstream());
        }
        notified.await;
    }
}

fn chat_cache_stream_frames(value: Value) -> Option<Vec<Vec<u8>>> {
    value.as_array().map(|frames| {
        frames
            .iter()
            .filter_map(|frame| frame.as_str().map(|value| value.as_bytes().to_vec()))
            .collect()
    })
}

fn chat_cache_read_stream_frames(state: &AppState, key: &str) -> Option<Vec<Vec<u8>>> {
    chat_cache_read_stream(state, key).and_then(chat_cache_stream_frames)
}

fn chat_cache_finish_stream(
    state: &AppState,
    key: &str,
    inflight: &Arc<ChatCacheInflight>,
    result: Result<Vec<Vec<u8>>, String>,
) {
    if let Ok(frames) = &result {
        chat_cache_write_stream_with_settings(
            state,
            key.to_owned(),
            Value::Array(
                frames
                    .iter()
                    .filter_map(|frame| String::from_utf8(frame.clone()).ok())
                    .map(Value::String)
                    .collect(),
            ),
            inflight.ttl_seconds,
            inflight.max_entries,
        );
    }
    if let Ok(mut slot) = inflight.result.lock() {
        *slot = Some(result);
    }
    if let Ok(mut cache) = state.chat_cache.lock() {
        cache.inflight.remove(key);
    }
    inflight.notify.notify_waiters();
}

fn response_from_cached_stream_frames(frames: Vec<Vec<u8>>) -> Response {
    let stream = stream::iter(
        frames
            .into_iter()
            .map(|frame| Ok::<Bytes, io::Error>(Bytes::from(frame))),
    );
    let mut output = Response::new(Body::from_stream(stream));
    output.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    output
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    output
}

struct StreamCacheOutput {
    state: AppState,
    key: String,
    inflight: Arc<ChatCacheInflight>,
    frames: Vec<Vec<u8>>,
    finished: bool,
}

impl StreamCacheOutput {
    fn finish(&mut self, result: Result<Vec<Vec<u8>>, String>) {
        if !self.finished {
            self.finished = true;
            chat_cache_finish_stream(&self.state, &self.key, &self.inflight, result);
        }
    }
}

impl Drop for StreamCacheOutput {
    fn drop(&mut self) {
        if !self.finished {
            self.finish(Err("stream consumer dropped".to_owned()));
        }
    }
}

