fn python_safe_account_export_name(value: &str, fallback: &str) -> String {
    let mut clean = String::new();
    for character in value.trim().chars() {
        if character.is_ascii_alphanumeric() || matches!(character, '.' | '_' | '-') {
            clean.push(character);
        } else if !clean.ends_with('-') {
            clean.push('-');
        }
    }
    let clean = clean
        .trim_matches(['-', '.', '_'])
        .chars()
        .take(80)
        .collect::<String>();
    if clean.is_empty() {
        fallback.to_owned()
    } else {
        clean
    }
}

async fn api_accounts_export(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, ApiError> {
    admin_authenticated(&headers, &state).await?;
    let value = account_json_body(body).await?;
    let object = value.as_object().ok_or_else(ApiError::validation)?;
    let access_tokens = management_string_array(object, "access_tokens")?;
    let targets = (!access_tokens.is_empty()).then(|| {
        access_tokens
            .iter()
            .map(String::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .collect::<HashSet<_>>()
    });
    let format = match object.get("format") {
        None => "json",
        Some(Value::String(value)) => value.as_str(),
        Some(_) => return Err(ApiError::validation()),
    };
    if !matches!(format, "json" | "zip") {
        return Err(ApiError::validation());
    }
    let records = state.account_store.raw_records();
    let exported = records
        .into_iter()
        .filter(|item| {
            targets.as_ref().is_none_or(|wanted| {
                account_token(item).is_some_and(|token| wanted.contains(token.as_str()))
            })
        })
        .filter(|item| {
            ["access_token", "refresh_token", "id_token"]
                .iter()
                .all(|key| {
                    item.get(*key)
                        .and_then(Value::as_str)
                        .is_some_and(|value| !value.trim().is_empty())
                })
        })
        .collect::<Vec<_>>();
    if exported.is_empty() {
        return Err(ApiError::management_bad_request(
            "bad_request",
            "没有可导出的完整账号，需要同时有 access_token、refresh_token 和 id_token",
        ));
    }
    let timestamp = account_export_timestamp();
    if format == "zip" {
        let mut used_names = HashSet::new();
        let files = exported
            .iter()
            .enumerate()
            .map(|(index, item)| {
                let raw_name = item
                    .get("email")
                    .and_then(Value::as_str)
                    .filter(|value| !value.is_empty())
                    .or_else(|| {
                        item.get("account_id")
                            .and_then(Value::as_str)
                            .filter(|value| !value.is_empty())
                    })
                    .unwrap_or("");
                let fallback = format!("account-{index:03}");
                let base_name = python_safe_account_export_name(raw_name, &fallback);
                let mut name = base_name.clone();
                let mut suffix = 2usize;
                while !used_names.insert(name.clone()) {
                    name = format!("{base_name}-{suffix}");
                    suffix = suffix.saturating_add(1);
                }
                let mut payload =
                    serde_json::to_vec_pretty(item).map_err(|_| ApiError::unavailable())?;
                payload.push(b'\n');
                Ok((format!("{name}.json"), payload))
            })
            .collect::<Result<Vec<_>, ApiError>>()?;
        let archive = management::zip_archive(files)?;
        let mut response = (
            StatusCode::OK,
            [(header::CONTENT_TYPE, "application/zip")],
            Body::from(archive),
        )
            .into_response();
        let filename = format!("codex-accounts-{timestamp}.zip");
        response.headers_mut().insert(
            header::CONTENT_DISPOSITION,
            HeaderValue::from_str(&format!("attachment; filename=\"{filename}\""))
                .map_err(|_| ApiError::unavailable())?,
        );
        return Ok(response);
    }
    let payload = if exported.len() == 1 {
        exported.into_iter().next().expect("one exported account")
    } else {
        Value::Array(exported)
    };
    let mut bytes = serde_json::to_vec_pretty(&payload).map_err(|_| ApiError::unavailable())?;
    bytes.push(b'\n');
    let mut response = (
        StatusCode::OK,
        [(header::CONTENT_TYPE, "application/json")],
        Body::from(bytes),
    )
        .into_response();
    let filename = format!("codex-accounts-{timestamp}.json");
    response.headers_mut().insert(
        header::CONTENT_DISPOSITION,
        HeaderValue::from_str(&format!("attachment; filename=\"{filename}\""))
            .map_err(|_| ApiError::unavailable())?,
    );
    Ok(response)
}

#[allow(dead_code)]
async fn api_accounts_refresh(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
) -> Result<Json<Value>, ApiError> {
    admin_authenticated(&headers, &state).await?;
    let value = account_json_body(body).await?;
    let object = value.as_object().ok_or_else(ApiError::validation)?;
    let tokens = management_string_array(object, "access_tokens")?
        .into_iter()
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    let requested = if tokens.is_empty() {
        state
            .account_store
            .raw_records()
            .iter()
            .filter_map(account_token)
            .collect::<Vec<_>>()
    } else {
        tokens
    };
    let mut seen_tokens = HashSet::new();
    let requested = requested
        .into_iter()
        .filter(|token| seen_tokens.insert(token.clone()))
        .collect::<Vec<_>>();
    if requested.is_empty() {
        return Err(ApiError::invalid_request());
    }
    let progress_id = format!(
        "refresh-{}-{}",
        std::process::id(),
        AUTH_WRITE_SEQUENCE.fetch_add(1, Ordering::Relaxed)
    );
    {
        let mut progress = state.account_progress.lock().await;
        progress.insert(
            progress_id.clone(),
            json!({
                "progress_id": progress_id,
                "status": "queued",
                "total": requested.len(),
                "processed": 0,
                "done": false,
                "error": Value::Null,
                "completed": 0,
                "refreshed": 0,
                "result": Value::Null,
                "status_counts": {"正常": 0, "限流": 0, "异常": 0, "禁用": 0},
                "total_quota": 0,
                "errors": []
            }),
        );
    }
    let task_state = state.clone();
    let task_progress_id = progress_id.clone();
    tokio::spawn(async move {
        {
            let mut progress = task_state.account_progress.lock().await;
            if let Some(item) = progress.get_mut(&task_progress_id) {
                item["status"] = Value::String("running".to_owned());
            }
        }
        let sink = AccountRefreshProgressSink {
            state: task_state.clone(),
            progress: task_state.account_progress.clone(),
            progress_id: task_progress_id.clone(),
        };
        let result = refresh_accounts_now_with_deadline(
            &task_state,
            &requested,
            None,
            None,
            Some(sink),
            false,
        )
        .await;
        let mut progress = task_state.account_progress.lock().await;
        if let Some(item) = progress.get_mut(&task_progress_id) {
            match result {
                Ok(result) => {
                    management::append_account_log(
                        &task_state,
                        "刷新账号",
                        json!({
                            "total": item["total"],
                            "refreshed": result["refreshed"],
                            "failed": result["errors"].as_array().map_or(0, Vec::len),
                        }),
                    );
                    item["status"] = Value::String("completed".to_owned());
                    item["done"] = Value::Bool(true);
                    item["processed"] = item["total"].clone();
                    item["completed"] = item["total"].clone();
                    item["refreshed"] = result["refreshed"].clone();
                    item["errors"] = result["errors"].clone();
                    item["result"] = result.clone();
                    item["items"] = result["items"].clone();
                }
                Err(_) => {
                    management::append_account_log(
                        &task_state,
                        "刷新账号失败",
                        json!({"total": item["total"], "status": "failed"}),
                    );
                    item["status"] = Value::String("failed".to_owned());
                    item["done"] = Value::Bool(true);
                    item["processed"] = item["total"].clone();
                    item["error"] = Value::String("refresh failed".to_owned());
                }
            }
        }
    });
    Ok(Json(json!({"progress_id": progress_id})))
}

