#[allow(dead_code)]
async fn api_users(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<Value>, ApiError> {
    admin_authenticated(&headers, &state).await?;
    if !state.auth_store.reload().await {
        return Err(ApiError::unavailable());
    }
    let items = state
        .auth_store
        .public_records()
        .into_iter()
        .filter(auth_record_is_user)
        .collect::<Vec<_>>();
    Ok(Json(json!({"items": items})))
}

fn auth_record_is_user(record: &Value) -> bool {
    record
        .get("role")
        .and_then(Value::as_str)
        .map(str::trim)
        .is_some_and(|role| role.eq_ignore_ascii_case("user"))
}

fn public_auth_record(record: &Value) -> Value {
    let object = record.as_object();
    json!({
        "id": object.and_then(|value| value.get("id")).cloned().unwrap_or(Value::Null),
        "name": object.and_then(|value| value.get("name")).cloned().unwrap_or(Value::Null),
        "role": object.and_then(|value| value.get("role")).cloned().unwrap_or(Value::Null),
        "enabled": object
            .and_then(|value| value.get("enabled"))
            .map(|value| account_pool::account_value_truthy(Some(value)))
            .unwrap_or(true),
        "created_at": object
            .and_then(|value| value.get("created_at"))
            .cloned()
            .unwrap_or(Value::Null),
        "last_used_at": object
            .and_then(|value| value.get("last_used_at"))
            .cloned()
            .unwrap_or(Value::Null),
    })
}

fn random_user_key() -> Result<String, ApiError> {
    let mut bytes = [0u8; 24];
    getrandom::getrandom(&mut bytes).map_err(|_| ApiError::unavailable())?;
    Ok(format!("sk-{}", URL_SAFE_NO_PAD.encode(bytes)))
}

fn random_auth_id() -> Result<String, ApiError> {
    let mut bytes = [0u8; 6];
    getrandom::getrandom(&mut bytes).map_err(|_| ApiError::unavailable())?;
    Ok(bytes.iter().map(|byte| format!("{byte:02x}")).collect())
}

fn auth_key_hash(key: &str) -> String {
    Sha256::digest(key.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn auth_setting_bool(value: &Value) -> Option<bool> {
    match value {
        Value::Bool(value) => Some(*value),
        Value::Number(value) => match value.as_i64()? {
            0 => Some(false),
            1 => Some(true),
            _ => None,
        },
        Value::String(value) => match value.trim().to_ascii_lowercase().as_str() {
            "1" | "true" | "t" | "yes" | "y" | "on" => Some(true),
            "0" | "false" | "f" | "no" | "n" | "off" => Some(false),
            _ => None,
        },
        _ => None,
    }
}

fn user_auth_name(
    records: &[Value],
    requested: Option<&str>,
    exclude_id: Option<&str>,
) -> Result<String, ApiError> {
    let requested = requested.unwrap_or_default().trim();
    if requested.chars().count() > MAX_AUTH_KEY_NAME_LENGTH {
        return Err(ApiError::validation());
    }
    let is_taken = |candidate: &str| {
        records.iter().any(|record| {
            auth_record_is_user(record)
                && record.get("name").and_then(Value::as_str) == Some(candidate)
                && exclude_id.is_none_or(|id| record.get("id").and_then(Value::as_str) != Some(id))
        })
    };
    if !requested.is_empty() {
        if is_taken(requested) {
            return Err(ApiError::management_bad_request(
                "bad_request",
                "这个名称已经在使用中了，换一个更容易区分的名称吧",
            ));
        }
        return Ok(requested.to_owned());
    }
    let base = "普通用户";
    if !is_taken(base) {
        return Ok(base.to_owned());
    }
    for suffix in 2usize.. {
        let candidate = format!("{base} {suffix}");
        if !is_taken(&candidate) {
            return Ok(candidate);
        }
    }
    unreachable!("user key name suffix space exhausted")
}

async fn api_users_add(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
) -> Result<Json<Value>, ApiError> {
    admin_authenticated(&headers, &state).await?;
    let body = account_json_body(body).await?;
    let requested_name = match body.get("name") {
        None => String::new(),
        Some(Value::String(name)) => name.trim().to_owned(),
        Some(_) => return Err(ApiError::validation()),
    };
    if requested_name.chars().count() > MAX_AUTH_KEY_NAME_LENGTH {
        return Err(ApiError::validation());
    }
    let key = random_user_key()?;
    let id = random_auth_id()?;
    let created_at = python_utc_isoformat(time::OffsetDateTime::now_utc());
    let created = state
        .auth_store
        .mutate_raw(|records| {
            let name = user_auth_name(
                records,
                (!requested_name.is_empty()).then_some(requested_name.as_str()),
                None,
            )?;
            let record = json!({
                "id": id,
                "name": name,
                "role": "user",
                "enabled": true,
                "key_hash": auth_key_hash(&key),
                "created_at": created_at,
                "last_used_at": Value::Null,
            });
            records.push(record);
            Ok(records.last().expect("new user record").clone())
        })
        .await?;
    Ok(Json(json!({
        "item": public_auth_record(&created),
        "key": key,
        "items": state
            .auth_store
            .public_records()
            .into_iter()
            .filter(auth_record_is_user)
            .collect::<Vec<_>>(),
    })))
}

async fn api_users_update(
    State(state): State<AppState>,
    headers: HeaderMap,
    AxumPath(key_id): AxumPath<String>,
    body: Body,
) -> Result<Json<Value>, ApiError> {
    admin_authenticated(&headers, &state).await?;
    let body = account_json_body(body).await?;
    let name = match body.get("name") {
        None | Some(Value::Null) => None,
        Some(Value::String(name)) => {
            let name = name.trim().to_owned();
            if name.chars().count() > MAX_AUTH_KEY_NAME_LENGTH {
                return Err(ApiError::validation());
            }
            Some(name)
        }
        Some(_) => return Err(ApiError::validation()),
    };
    let enabled = body
        .get("enabled")
        .filter(|value| !value.is_null())
        .map(|value| auth_setting_bool(value).ok_or_else(ApiError::validation))
        .transpose()?;
    let replacement_key = if let Some(value) = body.get("key") {
        if value.is_null() {
            None
        } else {
            let key = value
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty() && value.len() <= MAX_ACCOUNT_TOKEN_LENGTH)
                .ok_or_else(|| {
                    ApiError::management_bad_request("bad_request", "请输入新的专用密钥")
                })?
                .to_owned();
            Some(key)
        }
    } else {
        None
    };
    if name.is_none() && enabled.is_none() && replacement_key.is_none() {
        return Err(ApiError::management_bad_request(
            "bad_request",
            "还没有检测到改动，请修改后再保存",
        ));
    }
    let replacement_hash = replacement_key.as_deref().map(auth_key_hash);
    let updated = state
        .auth_store
        .mutate_raw(|records| {
            let Some(index) = records.iter().position(|record| {
                record
                    .get("id")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value == key_id)
                    && auth_record_is_user(record)
            }) else {
                return Err(ApiError::not_found());
            };
            let normalized_name = if let Some(name) = &name {
                Some(user_auth_name(records, Some(name), Some(&key_id))?)
            } else {
                None
            };
            if let Some(key) = replacement_key.as_deref() {
                let hash = replacement_hash.as_deref().expect("replacement key hash");
                if state.config.auth_key.as_deref().is_some_and(|admin| {
                    constant_time_equal(key.as_bytes(), admin.trim().as_bytes())
                }) {
                    return Err(ApiError::management_bad_request(
                        "bad_request",
                        "这个密钥和管理员密钥冲突了，请换一个新的密钥",
                    ));
                }
                if records.iter().enumerate().any(|(other_index, record)| {
                    other_index != index
                        && record.get("key_hash").and_then(Value::as_str) == Some(hash)
                }) {
                    return Err(ApiError::management_bad_request(
                        "bad_request",
                        "这个专用密钥已经存在，请换一个新的密钥",
                    ));
                }
            }
            let record = &mut records[index];
            let object = record
                .as_object_mut()
                .ok_or_else(ApiError::invalid_request)?;
            if let Some(name) = normalized_name {
                object.insert("name".to_owned(), Value::String(name.clone()));
            }
            if let Some(enabled) = enabled {
                object.insert("enabled".to_owned(), Value::Bool(enabled));
            }
            if let Some(hash) = &replacement_hash {
                object.insert("key_hash".to_owned(), Value::String(hash.clone()));
            }
            Ok(record.clone())
        })
        .await?;
    let response = json!({
        "item": public_auth_record(&updated),
        "items": state
            .auth_store
            .public_records()
            .into_iter()
            .filter(auth_record_is_user)
            .collect::<Vec<_>>(),
    });
    Ok(Json(response))
}

async fn api_users_delete(
    State(state): State<AppState>,
    headers: HeaderMap,
    AxumPath(key_id): AxumPath<String>,
) -> Result<Json<Value>, ApiError> {
    admin_authenticated(&headers, &state).await?;
    state
        .auth_store
        .mutate_raw(|records| {
            let original_len = records.len();
            records.retain(|record| {
                record
                    .get("id")
                    .and_then(Value::as_str)
                    .is_none_or(|value| value != key_id)
                    || !auth_record_is_user(record)
            });
            if records.len() == original_len {
                return Err(ApiError::not_found());
            }
            Ok(())
        })
        .await?;
    let items = state
        .auth_store
        .public_records()
        .into_iter()
        .filter(auth_record_is_user)
        .collect::<Vec<_>>();
    Ok(Json(json!({"items": items})))
}

