fn bump_request_shape(shape: &mut Map<String, Value>, key: &str) {
    let next = shape
        .get(key)
        .and_then(Value::as_u64)
        .unwrap_or_default()
        .saturating_add(1);
    shape.insert(key.to_owned(), Value::from(next));
}

fn collect_request_shape(value: &Value, parent_key: &str, shape: &mut Map<String, Value>) {
    match value {
        Value::String(text) => {
            let normalized = text.trim().to_ascii_lowercase();
            if normalized.contains("<image>") {
                bump_request_shape(shape, "literal_image_placeholders");
            }
            if normalized.starts_with("data:image/") {
                bump_request_shape(shape, "data_url_images");
            } else if matches!(parent_key, "image_url" | "url")
                && (normalized.starts_with("http://") || normalized.starts_with("https://"))
            {
                bump_request_shape(shape, "remote_image_urls");
            }
        }
        Value::Array(items) => {
            for item in items {
                collect_request_shape(item, parent_key, shape);
            }
        }
        Value::Object(object) => {
            match object.get("type").and_then(Value::as_str) {
                Some("message") => bump_request_shape(shape, "response_message_items"),
                Some("input_image") => bump_request_shape(shape, "input_image_parts"),
                Some("image_url") => bump_request_shape(shape, "image_url_parts"),
                Some("image") => bump_request_shape(shape, "image_parts"),
                _ => {}
            }
            for (key, child) in object {
                collect_request_shape(child, key, shape);
            }
        }
        Value::Null | Value::Bool(_) | Value::Number(_) => {}
    }
}

fn request_log_context(
    body: &[u8],
    text_fields: &[&str],
    shape_fields: &[&str],
) -> (Option<String>, Option<Value>) {
    let Ok(value) = serde_json::from_slice::<Value>(body) else {
        return (None, None);
    };
    let text = request_text_fields(&value, text_fields);
    let request_text = (!text.trim().is_empty()).then_some(text);
    let mut shape = Map::new();
    if let Some(object) = value.as_object() {
        for field in shape_fields {
            if let Some(value) = object.get(*field) {
                collect_request_shape(value, field, &mut shape);
            }
        }
    }
    let request_shape = (!shape.is_empty()).then_some(Value::Object(shape));
    (request_text, request_shape)
}

fn request_model_for_log(body: &[u8]) -> String {
    serde_json::from_slice::<Value>(body)
        .ok()
        .and_then(|value| {
            value
                .get("model")
                .and_then(Value::as_str)
                .map(ToOwned::to_owned)
        })
        .map(|model| model.trim().to_owned())
        .filter(|model| !model.is_empty())
        .unwrap_or_else(|| "auto".to_owned())
}

