fn request_log_identity(state: &AppState, headers: &HeaderMap) -> Option<Value> {
    let value = headers
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())?;
    let (scheme, raw_token) = value.split_once(' ')?;
    if !scheme.eq_ignore_ascii_case("bearer") {
        return None;
    }
    let token = raw_token.trim();
    if token.is_empty() {
        return None;
    }
    if state
        .config
        .auth_key
        .as_deref()
        .is_some_and(|expected| constant_time_equal(token.as_bytes(), expected.trim().as_bytes()))
    {
        return Some(json!({"id":"admin","name":"管理员","role":"admin"}));
    }
    state
        .auth_store
        .identity(token)
        .map(|(role, subject, name)| json!({"id":subject,"name":name,"role":role}))
}

fn subject_log_identity(state: &AppState, subject: &str) -> Option<Value> {
    if subject == "admin" {
        return Some(json!({"id":"admin","name":"管理员","role":"admin"}));
    }
    state
        .auth_store
        .public_records()
        .into_iter()
        .find(|record| record.get("id").and_then(Value::as_str) == Some(subject))
}

#[derive(Clone, Debug, Default)]
struct NativeImageLogMetadata {
    account_email: Option<String>,
    conversation_id: Option<String>,
    urls: Vec<String>,
}

type NativeImageLogContext = Arc<StdMutex<NativeImageLogMetadata>>;

fn native_image_account_email(state: &AppState, token: &str) -> Option<String> {
    state
        .account_store
        .records()
        .into_iter()
        .find(|record| record.token == token)
        .and_then(|record| {
            record
                .raw
                .get("email")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        })
}

fn set_native_image_log_account(
    context: Option<&NativeImageLogContext>,
    account_email: Option<&str>,
) {
    let Some(context) = context else {
        return;
    };
    let mut metadata = context.lock().expect("native image log context lock");
    metadata.account_email = account_email
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    metadata.conversation_id = None;
}

fn update_native_image_log_context(
    context: Option<&NativeImageLogContext>,
    account_email: Option<&str>,
    conversation_id: Option<&str>,
) {
    let Some(context) = context else {
        return;
    };
    let mut metadata = context.lock().expect("native image log context lock");
    if let Some(account_email) = account_email
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        metadata.account_email = Some(account_email.to_owned());
    }
    if let Some(conversation_id) = conversation_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        metadata.conversation_id = Some(conversation_id.to_owned());
    }
}

fn snapshot_native_image_log_context(context: &NativeImageLogContext) -> NativeImageLogMetadata {
    context
        .lock()
        .expect("native image log context lock")
        .clone()
}
fn native_image_task_error_updates(context: &NativeImageLogContext) -> Map<String, Value> {
    let mut updates = Map::new();
    if let Some(conversation_id) = snapshot_native_image_log_context(context).conversation_id {
        updates.insert("conversation_id".to_owned(), Value::String(conversation_id));
    }
    updates
}

fn clear_native_image_log_context(context: Option<&NativeImageLogContext>) {
    if let Some(context) = context {
        *context.lock().expect("native image log context lock") = NativeImageLogMetadata::default();
    }
}

