#[allow(clippy::too_many_arguments)]
fn append_api_call_log_with_metadata_identity(
    state: &AppState,
    endpoint: &str,
    model: &str,
    summary: &str,
    started: Instant,
    status: &str,
    request_text: Option<&str>,
    request_shape: Option<&Value>,
    error: Option<&str>,
    metadata: Option<&NativeImageLogMetadata>,
    identity: Option<&Value>,
) {
    let mut detail = Map::new();
    if let Some(identity) = identity.and_then(Value::as_object) {
        for (source, target) in [("id", "key_id"), ("name", "key_name"), ("role", "role")] {
            if let Some(value) = identity
                .get(source)
                .and_then(Value::as_str)
                .filter(|value| !value.trim().is_empty())
            {
                detail.insert(target.to_owned(), Value::String(value.to_owned()));
            }
        }
    }
    detail.insert("endpoint".to_owned(), Value::String(endpoint.to_owned()));
    detail.insert("model".to_owned(), Value::String(model.to_owned()));
    detail.insert("status".to_owned(), Value::String(status.to_owned()));
    let ended_at = SystemTime::now();
    let started_at = ended_at.checked_sub(started.elapsed()).unwrap_or(ended_at);
    detail.insert(
        "duration_ms".to_owned(),
        Value::from(started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64),
    );
    detail.insert(
        "started_at".to_owned(),
        Value::String(management::local_timestamp(started_at)),
    );
    detail.insert(
        "ended_at".to_owned(),
        Value::String(management::local_timestamp(ended_at)),
    );
    if let Some(text) = request_text.map(str::trim).filter(|text| !text.is_empty()) {
        detail.insert(
            "request_text".to_owned(),
            Value::String(text.chars().take(1000).collect()),
        );
    }
    if let Some(shape) = request_shape {
        detail.insert("request_shape".to_owned(), shape.clone());
    }
    if let Some(error) = error.map(str::trim).filter(|error| !error.is_empty()) {
        detail.insert(
            "error".to_owned(),
            Value::String(error.chars().take(4096).collect()),
        );
    }
    if let Some(metadata) = metadata {
        if let Some(account_email) = metadata
            .account_email
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            detail.insert(
                "account_email".to_owned(),
                Value::String(account_email.to_owned()),
            );
        }
        if let Some(conversation_id) = metadata
            .conversation_id
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            detail.insert(
                "conversation_id".to_owned(),
                Value::String(conversation_id.to_owned()),
            );
        }
        let mut urls = Vec::new();
        for url in metadata
            .urls
            .iter()
            .map(|url| url.trim())
            .filter(|url| !url.is_empty())
        {
            if !urls.iter().any(|existing| existing == url) {
                urls.push(url.to_owned());
            }
        }
        if !urls.is_empty() {
            detail.insert(
                "urls".to_owned(),
                Value::Array(urls.into_iter().map(Value::String).collect()),
            );
        }
    }
    management::append_call_log(state, summary, Value::Object(detail));
}

