#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeModelSettings {
    upstream_model: String,
}

fn configured_global_system_prompt(state: &AppState) -> Option<String> {
    fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .and_then(|value| {
            value
                .get("global_system_prompt")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        })
}

fn python_content_text(value: &Value, depth: usize) -> String {
    if depth > 128 {
        return String::new();
    }
    match value {
        Value::String(text) => text.clone(),
        Value::Array(items) => items
            .iter()
            .map(|item| python_content_text(item, depth + 1))
            .collect::<Vec<_>>()
            .join("\n"),
        Value::Object(object) => [
            "text",
            "input_text",
            "content",
            "input",
            "instructions",
            "system",
            "prompt",
        ]
        .iter()
        .map(|key| {
            object
                .get(*key)
                .map(|value| python_content_text(value, depth + 1))
                .unwrap_or_default()
        })
        .collect::<Vec<_>>()
        .join("\n"),
        Value::Null | Value::Bool(_) | Value::Number(_) => String::new(),
    }
}

fn request_text_fields(value: &Value, fields: &[&str]) -> String {
    let Some(object) = value.as_object() else {
        return String::new();
    };
    fields
        .iter()
        .filter_map(|field| object.get(*field))
        .map(|value| python_content_text(value, 0).trim().to_owned())
        .filter(|text| !text.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

fn reject_sensitive_words(state: &AppState, value: &Value) -> Result<(), ApiError> {
    let config = fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .unwrap_or_else(|| json!({}));
    let words = config
        .get("sensitive_words")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|word| protocol_anthropic::python_text(Some(word)))
        .map(|word| word.trim().to_owned())
        .filter(|word| !word.is_empty())
        .collect::<Vec<_>>();
    if words.is_empty() {
        return Ok(());
    }
    let text = python_content_text(value, 0);
    if words.iter().any(|word| text.contains(word)) {
        return Err(ApiError::content_policy("检测到敏感词，拒绝本次任务"));
    }
    Ok(())
}

fn sanitize_review_text(text: &str) -> String {
    let mut output = String::with_capacity(text.len().min(100_000));
    let mut remaining = text;
    while let Some(start) = remaining.find("data:") {
        output.push_str(&remaining[..start]);
        let uri = &remaining[start..];
        let after_scheme = &uri["data:".len()..];
        let Some(marker_start) = after_scheme.find(";base64,") else {
            output.push_str("data:");
            remaining = &uri["data:".len()..];
            continue;
        };
        let media_type = &after_scheme[..marker_start];
        if media_type.is_empty()
            || !media_type.chars().all(|character| {
                character.is_alphanumeric()
                    || matches!(character, '_' | '/' | '.' | '+' | ';' | '-')
            })
        {
            output.push_str("data:");
            remaining = &uri["data:".len()..];
            continue;
        }
        let payload_start = "data:".len() + marker_start + ";base64,".len();
        let payload = &uri[payload_start..];
        let payload_len = payload
            .bytes()
            .take_while(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'+' | b'/' | b'='))
            .count();
        if payload_len == 0 {
            output.push_str("data:");
            remaining = &uri["data:".len()..];
            continue;
        }
        output.push_str("[image]");
        remaining = &uri[payload_start + payload_len..];
    }
    output.push_str(remaining);
    let output_chars = output.chars().count();
    if output_chars <= 100_000 {
        return output;
    }
    let marker = "\n…[truncated]…\n";
    let half = (100_000 - marker.chars().count()) / 2;
    let head = output.chars().take(half).collect::<String>();
    let tail = output.chars().skip(output_chars - half).collect::<String>();
    format!("{head}{marker}{tail}")
}

async fn review_request_content(state: &AppState, value: &Value) -> Result<(), ApiError> {
    let text = python_content_text(value, 0);
    if text.trim().is_empty() {
        return Ok(());
    }
    let config = fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .unwrap_or_else(|| json!({}));
    let review = config.get("ai_review").and_then(Value::as_object);
    if !python_truthy(review.and_then(|object| object.get("enabled")), false) {
        return Ok(());
    }
    let base_url = review
        .and_then(|object| object.get("base_url"))
        .map(|value| protocol_anthropic::python_text(Some(value)))
        .unwrap_or_default()
        .trim()
        .trim_end_matches('/')
        .to_owned();
    let api_key = review
        .and_then(|object| object.get("api_key"))
        .map(|value| protocol_anthropic::python_text(Some(value)))
        .unwrap_or_default()
        .trim()
        .to_owned();
    let model = review
        .and_then(|object| object.get("model"))
        .map(|value| protocol_anthropic::python_text(Some(value)))
        .unwrap_or_default()
        .trim()
        .to_owned();
    if base_url.is_empty() || api_key.is_empty() || model.is_empty() {
        return Err(ApiError::content_review_config_incomplete());
    }
    let fail_open = python_ai_review_fail_open(review.and_then(|object| object.get("fail_open")));
    let prompt = configured_ai_review_prompt(review.and_then(|object| object.get("prompt")));
    let legacy_proxy = config.get("proxy").and_then(Value::as_str);
    let profile = proxy_service::profile_from_runtime(
        &proxy_runtime_value(state),
        None,
        None,
        legacy_proxy,
        false,
        false,
    );
    let client = if profile.proxy_url.is_empty() && !profile.skip_ssl_verify {
        state.client.clone()
    } else {
        match upstream_client_for_profile(&profile) {
            Ok(client) => client,
            Err(_) if fail_open => return Ok(()),
            Err(_) => return Err(ApiError::content_review_unavailable()),
        }
    };
    let body = json!({
        "model": model,
        "messages": [{"role":"user","content":format!("{}\n\n用户请求:\n{}\n\n只回答 ALLOW 或 REJECT。", prompt, sanitize_review_text(&text))}],
        "temperature": 0
    });
    let response = match tokio::time::timeout(
        Duration::from_secs(60),
        client
            .post(format!("{base_url}/v1/chat/completions"))
            .header(header::AUTHORIZATION, format!("Bearer {api_key}"))
            .header(header::CONTENT_TYPE, "application/json")
            .json(&body)
            .send(),
    )
    .await
    {
        Ok(Ok(response)) => response,
        Ok(Err(_)) | Err(_) if fail_open => return Ok(()),
        Ok(Err(_)) | Err(_) => return Err(ApiError::content_review_unavailable()),
    };
    let value: Value = match response.json().await {
        Ok(value) => value,
        Err(_) if fail_open => return Ok(()),
        Err(_) => return Err(ApiError::content_review_unavailable()),
    };
    let Some(decision) = value
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .and_then(|choice| choice.get("message"))
        .and_then(|message| message.get("content"))
        .filter(|content| !content.is_null())
        .map(protocol_anthropic::python_str)
        .map(|content| content.trim().to_lowercase())
    else {
        return if fail_open {
            Ok(())
        } else {
            Err(ApiError::content_review_unavailable())
        };
    };
    if decision.starts_with("allow")
        || decision.starts_with("pass")
        || decision.starts_with("true")
        || decision.starts_with("yes")
        || decision.starts_with("通过")
        || decision.starts_with("允许")
        || decision.starts_with("安全")
    {
        return Ok(());
    }
    if decision.starts_with("reject")
        || decision.starts_with("deny")
        || decision.starts_with("block")
        || decision.starts_with("false")
        || decision.starts_with("no")
        || decision.starts_with("拒绝")
        || decision.starts_with("不允许")
        || decision.starts_with("违规")
        || decision.starts_with("禁止")
    {
        return Err(ApiError::content_policy("AI 审核未通过，拒绝本次任务"));
    }
    if fail_open {
        Ok(())
    } else {
        Err(ApiError::content_review_unavailable())
    }
}

fn apply_global_system_prompt_to_chat(state: &AppState, object: &mut Map<String, Value>) {
    let Some(prompt) = configured_global_system_prompt(state) else {
        return;
    };
    let has_messages = object
        .get("messages")
        .and_then(Value::as_array)
        .is_some_and(|messages| !messages.is_empty());
    if has_messages {
        if let Some(messages) = object.get_mut("messages").and_then(Value::as_array_mut) {
            messages.insert(0, json!({"role": "system", "content": prompt}));
        }
    } else {
        let mut messages = vec![json!({"role": "system", "content": prompt})];
        if let Some(user_prompt) = object
            .get("prompt")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            messages.push(json!({"role": "user", "content": user_prompt}));
        }
        object.insert("messages".to_owned(), Value::Array(messages));
    }
}

fn apply_global_system_prompt_to_responses(state: &AppState, object: &mut Map<String, Value>) {
    let Some(prompt) = configured_global_system_prompt(state) else {
        return;
    };
    match object.get_mut("instructions") {
        Some(Value::String(existing)) if !existing.trim().is_empty() => {
            *existing = format!("{prompt}\n\n{existing}");
        }
        _ => {
            object.insert("instructions".to_owned(), Value::String(prompt));
        }
    }
}

fn native_image_operation_timeout(state: &AppState) -> Duration {
    let configured_secs = fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .and_then(|value| {
            value
                .get("image_poll_timeout_secs")
                .and_then(|value| match value {
                    Value::Number(number) => number.as_u64(),
                    Value::String(text) => text.trim().parse::<u64>().ok(),
                    _ => None,
                })
        })
        .unwrap_or(120)
        .clamp(30, 3600);
    Duration::from_secs(configured_secs.saturating_mul(2).saturating_add(30))
        .max(NATIVE_IMAGE_DEFAULT_TIMEOUT)
}

fn native_image_poll_timeout(state: &AppState) -> Duration {
    let config = fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .unwrap_or_else(|| json!({}));
    Duration::from_secs(settings_u64(config.get("image_poll_timeout_secs"), 120, 1))
}

fn native_image_poll_timing(state: &AppState) -> (Duration, Duration, Duration, bool, bool) {
    let config = fs::read(state.config_path.as_ref())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
        .unwrap_or_else(|| json!({}));
    let test_defaults = cfg!(test)
        && !config
            .as_object()
            .is_some_and(|object| object.contains_key("image_poll_initial_wait_secs"))
        && !config
            .as_object()
            .is_some_and(|object| object.contains_key("image_settle_enabled"));
    let number = |key: &str, default: f64, minimum: f64| {
        Duration::from_secs_f64(settings_f64(config.get(key), default, minimum))
    };
    let bool_setting = |key: &str, default: bool| match config.get(key) {
        None => default,
        Some(Value::String(value)) => matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        ),
        Some(value) => python_truthy(Some(value), false),
    };
    let enabled = bool_setting("image_settle_enabled", !test_defaults);
    let check_before_hit = bool_setting("image_check_before_hit_enabled", !test_defaults);
    (
        number(
            "image_poll_initial_wait_secs",
            if test_defaults { 0.0 } else { 10.0 },
            0.0,
        ),
        number("image_poll_interval_secs", 10.0, 0.5),
        number(
            "image_settle_secs",
            if test_defaults { 0.0 } else { 2.0 },
            if test_defaults { 0.0 } else { 0.5 },
        ),
        enabled,
        check_before_hit,
    )
}

fn normalize_persisted_settings(object: &mut Map<String, Value>) {
    if object.contains_key("refresh_account_interval_minute") {
        object.insert(
            "refresh_account_interval_minute".to_owned(),
            json!(settings_u64(
                object.get("refresh_account_interval_minute"),
                5,
                0
            )),
        );
    }
    for (key, default, minimum) in [
        ("image_retention_days", 30, 1),
        ("image_poll_timeout_secs", 120, 1),
        ("image_account_concurrency", 3, 1),
        ("image_timeout_retry_secs", 30, 1),
    ] {
        if object.contains_key(key) {
            object.insert(
                key.to_owned(),
                json!(settings_u64(object.get(key), default, minimum)),
            );
        }
    }
    for (key, default, minimum) in [
        ("image_poll_interval_secs", 10.0, 0.5),
        ("image_poll_initial_wait_secs", 10.0, 0.0),
        ("image_settle_secs", 2.0, 0.5),
    ] {
        if object.contains_key(key) {
            object.insert(
                key.to_owned(),
                json!(settings_f64(object.get(key), default, minimum)),
            );
        }
    }
    for (key, default) in [
        ("image_parallel_generation", true),
        ("image_settle_enabled", true),
        ("image_check_before_hit_enabled", true),
        ("image_remove_conversation_after_result", false),
        ("image_remove_conversation_always", false),
        ("auto_remove_invalid_accounts", false),
        ("auto_remove_rate_limited_accounts", false),
        ("auto_relogin_after_refresh", false),
    ] {
        if object.contains_key(key) {
            object.insert(
                key.to_owned(),
                json!(settings_bool(object.get(key), default)),
            );
        }
    }
    if object.contains_key("sensitive_words") {
        object.insert(
            "sensitive_words".to_owned(),
            normalize_sensitive_words(object.get("sensitive_words")),
        );
    }
    if object.contains_key("global_system_prompt") {
        object.insert(
            "global_system_prompt".to_owned(),
            json!(settings_text(object.get("global_system_prompt"), "")),
        );
    }
    if object.contains_key("default_upstream_model_name") {
        let value = settings_text(object.get("default_upstream_model_name"), "gpt-5-5");
        object.insert(
            "default_upstream_model_name".to_owned(),
            json!(if value.is_empty() { "gpt-5-5" } else { &value }),
        );
    }
    if object.contains_key("ai_review") {
        object.insert(
            "ai_review".to_owned(),
            normalize_ai_review(object.get("ai_review"), false),
        );
    }
    if object.contains_key("backup") {
        object.insert(
            "backup".to_owned(),
            normalize_backup(object.get("backup"), false),
        );
    }
    if object.contains_key("image_storage") {
        object.insert(
            "image_storage".to_owned(),
            normalize_image_storage(object.get("image_storage"), false),
        );
    }
    if object.contains_key("third_party_apps") {
        object.insert(
            "third_party_apps".to_owned(),
            normalize_third_party_apps(object.get("third_party_apps")),
        );
    }
    if object.contains_key("log_levels") {
        object.insert(
            "log_levels".to_owned(),
            normalize_log_levels(object.get("log_levels")),
        );
    }
    if object.contains_key("default_thinking_effort") {
        object.insert(
            "default_thinking_effort".to_owned(),
            normalize_thinking_effort(object.get("default_thinking_effort")),
        );
    }
    if object.contains_key("chat_completion_cache") {
        object.insert(
            "chat_completion_cache".to_owned(),
            normalize_chat_completion_cache(object.get("chat_completion_cache")),
        );
    }
    if object.contains_key("proxy_runtime") {
        object.insert(
            "proxy_runtime".to_owned(),
            normalize_proxy_runtime(object.get("proxy_runtime"), false),
        );
    }
}

fn restore_masked_settings_fields(next: &mut Map<String, Value>, current: &Map<String, Value>) {
    for (section, fields) in [
        ("ai_review", ["api_key"].as_slice()),
        ("backup", ["secret_access_key", "passphrase"].as_slice()),
        ("image_storage", ["webdav_password"].as_slice()),
    ] {
        let Some(incoming) = next.get_mut(section).and_then(Value::as_object_mut) else {
            continue;
        };
        let previous = current
            .get(section)
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default();
        for field in fields {
            if incoming
                .get(*field)
                .and_then(Value::as_str)
                .is_some_and(|value| value.trim() == "********")
                && previous
                    .get(*field)
                    .and_then(Value::as_str)
                    .is_some_and(|value| !value.trim().is_empty())
                && let Some(value) = previous.get(*field)
            {
                incoming.insert((*field).to_owned(), value.clone());
            }
        }
    }
}
fn restore_proxy_runtime_clearance_fields(
    next: &mut Map<String, Value>,
    current: &Map<String, Value>,
) {
    let Some(incoming_clearance) = next
        .get_mut("proxy_runtime")
        .and_then(Value::as_object_mut)
        .and_then(|runtime| runtime.get_mut("clearance"))
        .and_then(Value::as_object_mut)
    else {
        return;
    };
    let Some(previous_clearance) = current
        .get("proxy_runtime")
        .and_then(Value::as_object)
        .and_then(|runtime| runtime.get("clearance"))
        .and_then(Value::as_object)
    else {
        return;
    };
    for (field, flag) in [
        ("cf_cookies", "has_cf_cookies"),
        ("cf_clearance", "has_cf_clearance"),
    ] {
        if settings_bool(incoming_clearance.get(flag), false)
            && settings_text(incoming_clearance.get(field), "").is_empty()
            && let Some(value) = previous_clearance.get(field)
        {
            incoming_clearance.insert(field.to_owned(), value.clone());
        }
    }
}

fn restore_public_url_value(value: Option<&Value>, previous: Option<&Value>) -> Value {
    let candidate = settings_text(value, "");
    let previous_text = settings_text(previous, "");
    if !previous_text.is_empty()
        && !candidate.is_empty()
        && (candidate == settings_public_config_url(previous)
            || candidate == settings_redacted_config_url(previous))
    {
        return Value::String(previous_text);
    }
    value.cloned().unwrap_or(Value::Null)
}

fn restore_public_url_field(
    next: &mut Map<String, Value>,
    current: &Map<String, Value>,
    section: &str,
    field: &str,
) {
    let Some(incoming) = next.get_mut(section).and_then(Value::as_object_mut) else {
        return;
    };
    let previous = current
        .get(section)
        .and_then(Value::as_object)
        .and_then(|object| object.get(field));
    let restored = restore_public_url_value(incoming.get(field), previous);
    incoming.insert(field.to_owned(), restored);
}

fn restore_redacted_settings_urls(next: &mut Map<String, Value>, current: &Map<String, Value>) {
    if next.contains_key("proxy") {
        let restored = restore_public_url_value(next.get("proxy"), current.get("proxy"));
        next.insert("proxy".to_owned(), restored);
    }
    for (section, field) in [
        ("ai_review", "base_url"),
        ("image_storage", "webdav_url"),
        ("proxy_runtime", "proxy_url"),
        ("proxy_runtime", "resource_proxy_url"),
    ] {
        restore_public_url_field(next, current, section, field);
    }
    let Some(incoming_runtime) = next.get_mut("proxy_runtime").and_then(Value::as_object_mut)
    else {
        return;
    };
    let Some(incoming_clearance) = incoming_runtime
        .get_mut("clearance")
        .and_then(Value::as_object_mut)
    else {
        return;
    };
    let previous = current
        .get("proxy_runtime")
        .and_then(Value::as_object)
        .and_then(|object| object.get("clearance"))
        .and_then(Value::as_object)
        .and_then(|object| object.get("flaresolverr_url"));
    let restored = restore_public_url_value(incoming_clearance.get("flaresolverr_url"), previous);
    incoming_clearance.insert("flaresolverr_url".to_owned(), restored);
}

