#[derive(Debug, Deserialize)]
struct HealthQuery {
    format: Option<String>,
}

fn health_response(
    state: &AppState,
    query: &HealthQuery,
    accounts: Value,
    storage: (Value, bool),
) -> Response {
    let payload = health_payload_with_storage(state, accounts, storage);
    if query.format.as_deref() == Some("json") {
        Json(payload).into_response()
    } else {
        Html(health_html(&payload)).into_response()
    }
}

async fn health(State(state): State<AppState>, Query(query): Query<HealthQuery>) -> Response {
    const OVERALL: Duration = Duration::from_millis(500);
    const SUBCHECK: Duration = Duration::from_millis(250);
    if let Some(backend) = state.storage_backend.clone() {
        let cache = state
            .health_snapshot_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .clone();
        let local_snapshot_available = cache.local_snapshot_available;
        if let Some(backend_health) = backend.cached_health(local_snapshot_available) {
            let info = backend.info();
            let (mut storage, storage_healthy) = public_storage_snapshot(&info, &backend_health);
            if !storage_healthy {
                storage["health"]["status"] = Value::String("unhealthy".to_owned());
                storage["health"]["error"] = Value::String("存储后端健康检查失败".to_owned());
            }
            let accounts = if local_snapshot_available {
                cache.accounts
            } else {
                empty_health_accounts()
            };
            return health_response(&state, &query, accounts, (storage, storage_healthy));
        }
        let account_permit = tokio::time::timeout(
            SUBCHECK,
            state.health_accounts_semaphore.clone().acquire_owned(),
        );
        let storage_permit = tokio::time::timeout(
            SUBCHECK,
            state.health_storage_semaphore.clone().acquire_owned(),
        );
        let (account_permit, storage_permit) = tokio::join!(account_permit, storage_permit);
        let permits = account_permit
            .ok()
            .and_then(Result::ok)
            .zip(storage_permit.ok().and_then(Result::ok));
        let Some((account_permit, storage_permit)) = permits else {
            let info = backend.info();
            let (storage, _) = public_storage_snapshot(&info, &json!({"status": "unhealthy"}));
            return health_response(&state, &query, empty_health_accounts(), (storage, false));
        };
        let account_store = state.account_store.clone();
        let auth_store = state.auth_store.clone();
        let generation_gate = state.health_snapshot_gate.clone();
        let health_snapshot_cache = state.health_snapshot_cache.clone();
        let health_backend = backend.clone();
        #[cfg(test)]
        let publish_test_hook = state.health_snapshot_publish_test_hook.clone();
        let remote = tokio::time::timeout(OVERALL, async move {
            let generation_guard = generation_gate.write_owned().await;
            let Some(account_gate) =
                tokio::time::timeout(SUBCHECK, account_store.lock_reload_gate())
                    .await
                    .ok()
            else {
                drop((account_permit, storage_permit));
                return (false, false, None);
            };
            let Some(auth_gate) = tokio::time::timeout(SUBCHECK, auth_store.lock_reload_gate())
                .await
                .ok()
            else {
                drop((
                    account_gate,
                    account_permit,
                    storage_permit,
                    generation_guard,
                ));
                return (false, false, None);
            };
            let loaded = tokio::time::timeout(SUBCHECK, health_backend.load_health_snapshots())
                .await
                .ok()
                .and_then(Result::ok);
            let (account_ok, backend_ok, backend_health) = match loaded {
                Some((accounts, auth_keys, backend_health)) => {
                    let parsed_accounts = parse_backend_snapshot(accounts);
                    let parsed_auth = parse_auth_backend_snapshot(auth_keys);
                    match (parsed_accounts, parsed_auth) {
                        (
                            Ok((account_records, account_fingerprint, cumulative_total)),
                            Ok((auth_records, auth_fingerprint)),
                        ) => {
                            account_store.publish_validated_backend_snapshot_silent(
                                account_records,
                                account_fingerprint,
                                cumulative_total,
                            );
                            #[cfg(test)]
                            {
                                let hook = publish_test_hook
                                    .read()
                                    .expect("database health publish hook")
                                    .clone();
                                if let Some(hook) = hook
                                    && hook.pause_between.swap(false, Ordering::SeqCst)
                                {
                                    hook.after_accounts.notify_one();
                                    hook.release_before_auth.notified().await;
                                }
                            }
                            auth_store.publish_validated_backend_snapshot_silent(
                                auth_records,
                                auth_fingerprint,
                            );
                            sync_health_snapshot_cache(
                                &health_snapshot_cache,
                                &account_store,
                                &auth_store,
                            );
                            (true, true, Some(backend_health))
                        }
                        _ => {
                            invalidate_health_snapshot_pair(
                                &health_snapshot_cache,
                                &account_store,
                                &auth_store,
                            )
                            .await;
                            (false, false, None)
                        }
                    }
                }
                None => {
                    invalidate_health_snapshot_pair(
                        &health_snapshot_cache,
                        &account_store,
                        &auth_store,
                    )
                    .await;
                    (false, false, None)
                }
            };
            drop((account_gate, auth_gate, generation_guard));
            drop((account_permit, storage_permit));
            (account_ok, backend_ok, backend_health)
        })
        .await;
        let (account_ok, backend_ok, backend_health) = remote.unwrap_or((false, false, None));
        let cache = state
            .health_snapshot_cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .clone();
        let accounts = if account_ok && cache.local_snapshot_available {
            cache.accounts.clone()
        } else {
            empty_health_accounts()
        };
        let info = state
            .storage_backend
            .as_deref()
            .map(storage::StorageBackend::info)
            .unwrap_or_else(|| json!({"type": "database"}));
        let raw_health = backend_health.unwrap_or_else(|| json!({"status": "unhealthy"}));
        let (mut storage, backend_healthy) = public_storage_snapshot(&info, &raw_health);
        let storage_healthy = backend_healthy && backend_ok;
        if !storage_healthy {
            storage["health"]["status"] = Value::String("unhealthy".to_owned());
            storage["health"]["error"] = Value::String("存储后端健康检查失败".to_owned());
        }
        return health_response(&state, &query, accounts, (storage, storage_healthy));
    }
    let account_store = state.account_store.clone();
    let account_state = state.clone();
    let storage_state = state.clone();
    let probes = async move {
        let account_probe = async move {
            let permit = tokio::time::timeout(
                SUBCHECK,
                account_state
                    .health_accounts_semaphore
                    .clone()
                    .acquire_owned(),
            )
            .await
            .ok()
            .and_then(Result::ok);
            let Some(permit) = permit else {
                return empty_health_accounts();
            };
            tokio::time::timeout(
                SUBCHECK,
                tokio::task::spawn_blocking(move || {
                    let accounts = if account_store.health_validated() {
                        health_accounts(&account_state)
                    } else {
                        empty_health_accounts()
                    };
                    drop(permit);
                    accounts
                }),
            )
            .await
            .ok()
            .and_then(Result::ok)
            .unwrap_or_else(empty_health_accounts)
        };
        let storage_probe = async {
            let permit = tokio::time::timeout(
                SUBCHECK,
                storage_state
                    .health_storage_semaphore
                    .clone()
                    .acquire_owned(),
            )
            .await
            .ok()
            .and_then(Result::ok);
            let Some(permit) = permit else {
                return (
                    json!({
                        "backend": "json",
                        "health": {"status": "unhealthy", "error": "存储后端健康检查失败"},
                    }),
                    false,
                );
            };
            tokio::time::timeout(
                SUBCHECK,
                tokio::task::spawn_blocking(move || {
                    let storage = health_storage(&storage_state);
                    drop(permit);
                    storage
                }),
            )
            .await
            .ok()
            .and_then(Result::ok)
            .unwrap_or_else(unhealthy_health_storage)
        };
        tokio::join!(account_probe, storage_probe)
    };
    let (accounts, storage) = tokio::time::timeout(OVERALL, probes)
        .await
        .unwrap_or_else(|_| (empty_health_accounts(), unhealthy_health_storage()));
    health_response(&state, &query, accounts, storage)
}

const ACCOUNT_TYPE_MODEL_TTL: Duration = Duration::from_secs(300);
const ACCOUNT_TYPE_MODEL_RETRY_BACKOFF: Duration = Duration::from_secs(5);
const ACCOUNT_TYPE_MODEL_REFRESH_DEADLINE: Duration = Duration::from_secs(90);
const ACCOUNT_TYPE_REFRESH_CONCURRENCY: usize = 4;
const ACCOUNT_REFRESH_CONCURRENCY: usize = 10;
const ACCOUNT_REFRESH_PERSIST_BATCH: usize = 32;
const PUBLIC_IMAGE_QUOTA_REFRESH_DEADLINE: Duration = Duration::from_secs(8);
type AccountRefreshFuture =
    Pin<Box<dyn Future<Output = (String, bool, Result<Value, &'static str>)> + Send>>;

#[derive(Clone)]
struct AccountRefreshProgressSink {
    state: AppState,
    progress: Arc<Mutex<HashMap<String, Value>>>,
    progress_id: String,
}

fn python_refresh_progress_status(account: Option<&Value>) -> String {
    account
        .and_then(|account| account.get("status"))
        .filter(|status| account_pool::account_value_truthy(Some(status)))
        .map(account_pool::python_account_value_string)
        .unwrap_or_else(|| "正常".to_owned())
        .trim()
        .to_owned()
}

impl AccountRefreshProgressSink {
    async fn record(
        &self,
        token: &str,
        account_known: bool,
        result: &Result<Value, &'static str>,
        removed_for_rate_limit: bool,
    ) {
        let mut progress = self.progress.lock().await;
        let Some(item) = progress.get_mut(&self.progress_id) else {
            return;
        };
        item["processed"] = Value::from(
            item["processed"]
                .as_u64()
                .unwrap_or_default()
                .saturating_add(1),
        );
        if result.is_ok() && account_known && !removed_for_rate_limit {
            item["refreshed"] = Value::from(
                item["refreshed"]
                    .as_u64()
                    .unwrap_or_default()
                    .saturating_add(1),
            );
        } else if let Err(code) = result {
            let errors = item["errors"].as_array_mut();
            if *code != "tls_error"
                && let Some(errors) = errors
            {
                errors.push(refresh_error_value(token, code));
            }
        }
        let current = if removed_for_rate_limit {
            None
        } else {
            (account_known && result.is_ok())
                .then(|| result.as_ref().ok().cloned())
                .flatten()
                .or_else(|| {
                    self.state
                        .account_store
                        .raw_records()
                        .into_iter()
                        .find(|record| account_token(record).as_deref() == Some(token))
                })
        };
        let status = python_refresh_progress_status(current.as_ref());
        let counts = item["status_counts"].as_object_mut();
        if let Some(counts) = counts {
            let next = counts
                .get(&status)
                .and_then(Value::as_u64)
                .unwrap_or_default()
                .saturating_add(1);
            counts.insert(status, Value::from(next));
        }
        item["total_quota"] = Value::from(
            item["total_quota"]
                .as_u64()
                .unwrap_or_default()
                .saturating_add(
                    current
                        .as_ref()
                        .and_then(|account| account.get("quota"))
                        .and_then(Value::as_u64)
                        .unwrap_or_default(),
                ),
        );
    }
}

fn refresh_result_removes_account(
    account: Option<&Value>,
    result: &Result<Value, &'static str>,
    remove_invalid: bool,
    remove_rate_limited: bool,
    defer_invalid_removal: bool,
    now: time::OffsetDateTime,
) -> bool {
    if remove_rate_limited
        && result
            .as_ref()
            .ok()
            .is_some_and(|updated| updated.get("status").and_then(Value::as_str) == Some("限流"))
    {
        return true;
    }
    remove_invalid
        && matches!(result, Err("invalid_token"))
        && account
            .is_some_and(|account| !invalid_token_should_defer(account, now, defer_invalid_removal))
}

fn parse_python_account_time(value: Option<&Value>) -> Option<time::OffsetDateTime> {
    let value = value.and_then(Value::as_str)?.trim();
    if value.is_empty() {
        return None;
    }
    if let Ok(parsed) =
        time::OffsetDateTime::parse(value, &time::format_description::well_known::Rfc3339)
    {
        return Some(parsed);
    }
    for format in [
        "[year]-[month]-[day] [hour]:[minute]:[second]",
        "[year]-[month]-[day]T[hour]:[minute]:[second]",
        "[year]-[month]-[day] [hour]:[minute]:[second].[subsecond digits:1+]",
        "[year]-[month]-[day]T[hour]:[minute]:[second].[subsecond digits:1+]",
    ] {
        let Ok(description) = time::format_description::parse_borrowed::<1>(format) else {
            continue;
        };
        if let Ok(parsed) = time::PrimitiveDateTime::parse(value, &description) {
            return Some(parsed.assume_utc());
        }
    }
    None
}

fn python_utc_isoformat(value: time::OffsetDateTime) -> String {
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}+00:00",
        value.year(),
        value.month() as u8,
        value.day(),
        value.hour(),
        value.minute(),
        value.second(),
        value.nanosecond() / 1_000,
    )
}

fn invalid_token_should_defer(account: &Value, now: time::OffsetDateTime, enabled: bool) -> bool {
    if !enabled {
        return false;
    }
    if parse_python_account_time(account.get("created_at"))
        .is_some_and(|created| (now - created).whole_seconds() < 10 * 60)
    {
        return true;
    }
    let invalid_count = account_pool::account_invalid_count(account.get("invalid_count"));
    if invalid_count <= 1 {
        return true;
    }
    parse_python_account_time(account.get("last_invalid_at"))
        .is_some_and(|last_invalid| (now - last_invalid).whole_seconds() < 30)
}

fn account_tokens_to_remove_after_refresh(
    updated_records: &[(String, Value)],
    confirmed_invalid_tokens: &[String],
    remove_invalid: bool,
    remove_rate_limited: bool,
) -> HashSet<String> {
    let mut tokens = HashSet::new();
    if remove_invalid {
        for token in confirmed_invalid_tokens {
            tokens.insert(token.clone());
        }
    }
    if remove_rate_limited {
        tokens.extend(
            updated_records
                .iter()
                .filter(|(_, updated)| {
                    updated.get("status").and_then(Value::as_str) == Some("限流")
                })
                .map(|(token, _)| token.clone()),
        );
    }
    tokens
}
const AUTHENTICATED_NATIVE_MODEL_PATHS: &[&str] = &[
    "/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true",
    "/backend-api/tpp/models/?supports_model_picker_upgrade_presets=true",
];
const ACCOUNT_MODEL_SOURCE_VERSION: u64 = 1;

struct NativeModelIdentity<'a> {
    token: &'a str,
    account_type: Option<&'a str>,
    account_id: Option<&'a str>,
}

enum NativeModelCatalogFetchOutcome {
    Complete(Vec<PublicModel>),
    RetryableUnavailable,
    PermanentUnavailable,
}

async fn fetch_native_model_catalog(
    state: Option<&AppState>,
    client: &Client,
    base_url: &str,
    context: &NativeRequestContext,
    identity: NativeModelIdentity<'_>,
    proxy_url: &str,
    deadline: Instant,
) -> Option<Vec<PublicModel>> {
    match fetch_native_model_catalog_with_outcome(
        state, client, base_url, context, identity, proxy_url, deadline,
    )
    .await
    {
        NativeModelCatalogFetchOutcome::Complete(models) => Some(models),
        NativeModelCatalogFetchOutcome::RetryableUnavailable
        | NativeModelCatalogFetchOutcome::PermanentUnavailable => None,
    }
}

async fn fetch_native_model_catalog_with_outcome(
    state: Option<&AppState>,
    client: &Client,
    base_url: &str,
    context: &NativeRequestContext,
    identity: NativeModelIdentity<'_>,
    proxy_url: &str,
    deadline: Instant,
) -> NativeModelCatalogFetchOutcome {
    if identity.token.is_empty() {
        return NativeModelCatalogFetchOutcome::PermanentUnavailable;
    }
    {
        let bootstrap = tokio::time::timeout_at(
            tokio::time::Instant::from_std(deadline),
            native_bootstrap(client, base_url, identity.token, context),
        )
        .await;
        match bootstrap {
            Ok(Ok(_)) => {}
            Ok(Err((_, retryable))) => {
                return if retryable {
                    NativeModelCatalogFetchOutcome::RetryableUnavailable
                } else {
                    NativeModelCatalogFetchOutcome::PermanentUnavailable
                };
            }
            Err(_) => return NativeModelCatalogFetchOutcome::RetryableUnavailable,
        }
    }
    let paths = AUTHENTICATED_NATIVE_MODEL_PATHS.to_vec();
    let mut indexes = HashMap::<String, usize>::new();
    let mut models: Vec<PublicModel> = Vec::new();
    let mut retryable_failure = false;
    for path in paths {
        if Instant::now() >= deadline {
            break;
        }
        let target_path = path.split('?').next().unwrap_or(path);
        let mut request = if let Some(state) = state {
            native_browser_headers_with_clearance(
                client.get(format!("{}{path}", base_url.trim_end_matches('/'))),
                context,
                &format!("{}/", base_url.trim_end_matches('/')),
                Some(&state.clearance_store),
                Some(&proxy_runtime_value(state)),
                proxy_url,
                base_url,
                None,
            )
            .await
        } else {
            native_browser_headers(
                client.get(format!("{}{path}", base_url.trim_end_matches('/'))),
                context,
            )
        }
        .header("X-OpenAI-Target-Path", target_path)
        .header("X-OpenAI-Target-Route", target_path);
        request = request.header(header::AUTHORIZATION, format!("Bearer {}", identity.token));
        if let Some(account_id) = identity.account_id {
            request = request.header("ChatGPT-Account-ID", account_id);
        }
        let response =
            match tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), request.send())
                .await
            {
                Ok(Ok(response)) => response,
                _ => {
                    retryable_failure = true;
                    continue;
                }
            };
        if !response.status().is_success() {
            if response.status() == StatusCode::TOO_MANY_REQUESTS
                || response.status().is_server_error()
            {
                retryable_failure = true;
            }
            continue;
        }
        if upstream_declares_oversize(&response) {
            continue;
        }
        let body = match tokio::time::timeout_at(
            tokio::time::Instant::from_std(deadline),
            bounded_response_body(response),
        )
        .await
        {
            Ok(Ok(body)) => body,
            _ => {
                retryable_failure = true;
                continue;
            }
        };
        let Ok(value) = serde_json::from_slice::<Value>(&body) else {
            continue;
        };
        let provenance = ModelProvenance::Web;
        for field in ["models", "data", "items"] {
            let Some(projected) = project_remote_model_list_with_provenance(
                &value,
                field,
                false,
                identity.account_type,
                true,
                false,
                provenance,
            ) else {
                continue;
            };
            for model in projected {
                if model_provenance_is_untrusted(model.provenance) {
                    continue;
                }
                if let Some(index) = indexes.get(&model.id).copied() {
                    if model_provenance_rank(model.provenance)
                        > model_provenance_rank(models[index].provenance)
                    {
                        models[index] = model;
                    }
                } else {
                    indexes.insert(model.id.clone(), models.len());
                    models.push(model);
                }
            }
        }
    }
    if !models.is_empty() {
        NativeModelCatalogFetchOutcome::Complete(models)
    } else if retryable_failure {
        NativeModelCatalogFetchOutcome::RetryableUnavailable
    } else {
        NativeModelCatalogFetchOutcome::PermanentUnavailable
    }
}

pub(crate) async fn fetch_imported_model_catalog(
    cache: &ImportedModelCatalogCache,
    client: &Client,
    base_url: &str,
    account_type: &str,
    token: &str,
    account_id: Option<&str>,
    deadline: Instant,
) -> Option<Vec<PublicModel>> {
    fetch_imported_model_catalog_request(ImportedModelCatalogRequest {
        cache: cache.clone(),
        client: client.clone(),
        base_url: base_url.to_owned(),
        account_type: account_type.to_owned(),
        token: token.to_owned(),
        account_id: account_id.map(ToOwned::to_owned),
        deadline,
        batch: None,
        retry: true,
        require_web_catalog: true,
    })
    .await
}

pub(crate) async fn fetch_imported_account_model_catalog(
    state: &AppState,
    account_type: &str,
    token: &str,
    account_id: Option<&str>,
    account_proxy: Option<&str>,
    deadline: Instant,
    batch: Option<Arc<ImportedModelCatalogBatchStats>>,
) -> Option<Vec<PublicModel>> {
    let base_url = state.config.upstream_base_url.as_deref()?;
    let (client, _) = state
        .account_type_catalog
        .model_catalog_client(account_proxy, Some(token));
    fetch_imported_model_catalog_request(ImportedModelCatalogRequest {
        cache: state.imported_model_catalog.clone(),
        client,
        base_url: base_url.to_owned(),
        account_type: account_type.to_owned(),
        token: token.to_owned(),
        account_id: account_id.map(ToOwned::to_owned),
        deadline,
        batch,
        retry: true,
        require_web_catalog: true,
    })
    .await
}

struct ImportedModelCatalogRequest {
    cache: ImportedModelCatalogCache,
    client: Client,
    base_url: String,
    account_type: String,
    token: String,
    account_id: Option<String>,
    deadline: Instant,
    batch: Option<Arc<ImportedModelCatalogBatchStats>>,
    retry: bool,
    require_web_catalog: bool,
}

async fn fetch_imported_model_catalog_request(
    request: ImportedModelCatalogRequest,
) -> Option<Vec<PublicModel>> {
    let ImportedModelCatalogRequest {
        cache,
        client,
        base_url,
        account_type,
        token,
        account_id,
        deadline,
        batch,
        retry,
        require_web_catalog,
    } = request;
    let key = account_type.to_ascii_lowercase();
    let retry_key = key.clone();
    let retry_cache = cache.clone();
    let retry_batch = batch.clone();
    let fetch = move || async move {
        let fetched = if retry {
            fetch_imported_native_model_catalog_with_retry(NativeModelCatalogRetryRequest {
                cache: retry_cache,
                key: retry_key,
                deadline,
                batch: retry_batch,
                client,
                base_url,
                account_type,
                token,
                account_id,
            })
            .await
        } else {
            match fetch_native_model_catalog_with_outcome(
                None,
                &client,
                &base_url,
                &NativeRequestContext::new(),
                NativeModelIdentity {
                    token: &token,
                    account_type: Some(account_type.as_str()),
                    account_id: account_id.as_deref(),
                },
                "",
                deadline,
            )
            .await
            {
                NativeModelCatalogFetchOutcome::Complete(models) => Some(models),
                NativeModelCatalogFetchOutcome::RetryableUnavailable
                | NativeModelCatalogFetchOutcome::PermanentUnavailable => None,
            }
        };
        fetched.map(ImportedModelCatalogFetch::Complete)
    };
    if require_web_catalog {
        cache
            .fetch_or_reuse_complete_catalog(&key, batch.clone(), fetch)
            .await
    } else {
        cache
            .fetch_or_reuse_with_catalog_batch(&key, batch.clone(), fetch)
            .await
    }
}

struct NativeModelCatalogRetryRequest {
    cache: ImportedModelCatalogCache,
    key: String,
    deadline: Instant,
    batch: Option<Arc<ImportedModelCatalogBatchStats>>,
    client: Client,
    base_url: String,
    account_type: String,
    token: String,
    account_id: Option<String>,
}

async fn fetch_imported_native_model_catalog_with_retry(
    request: NativeModelCatalogRetryRequest,
) -> Option<Vec<PublicModel>> {
    let NativeModelCatalogRetryRequest {
        cache,
        key,
        deadline,
        batch,
        client,
        base_url,
        account_type,
        token,
        account_id,
    } = request;
    for attempt in 0..IMPORTED_MODEL_CATALOG_MAX_ATTEMPTS {
        cache.record_attempt(&key).await;
        if let Some(batch) = &batch {
            batch.record(&key, 0);
        }
        let result = fetch_native_model_catalog_with_outcome(
            None,
            &client,
            &base_url,
            &NativeRequestContext::new(),
            NativeModelIdentity {
                token: &token,
                account_type: Some(account_type.as_str()),
                account_id: account_id.as_deref(),
            },
            "",
            deadline,
        )
        .await;
        match result {
            NativeModelCatalogFetchOutcome::Complete(models) => return Some(models),
            NativeModelCatalogFetchOutcome::PermanentUnavailable => return None,
            NativeModelCatalogFetchOutcome::RetryableUnavailable
                if attempt + 1 < IMPORTED_MODEL_CATALOG_MAX_ATTEMPTS =>
            {
                let remaining = deadline
                    .checked_duration_since(Instant::now())
                    .unwrap_or_default();
                if remaining.is_zero() {
                    return None;
                }
                cache.record_retry(&key).await;
                if let Some(batch) = &batch {
                    batch.record(&key, 1);
                }
                tokio::time::sleep(IMPORTED_MODEL_CATALOG_RETRY_BACKOFF.min(remaining)).await;
            }
            NativeModelCatalogFetchOutcome::RetryableUnavailable => return None,
        }
    }
    None
}

async fn fetch_imported_model_catalog_with_retry<F, Fut>(
    cache: &ImportedModelCatalogCache,
    key: &str,
    deadline: Instant,
    batch: Option<Arc<ImportedModelCatalogBatchStats>>,
    mut fetch: F,
) -> Option<Vec<PublicModel>>
where
    F: FnMut() -> Fut,
    Fut: Future<Output = Option<Vec<PublicModel>>>,
{
    for attempt in 0..IMPORTED_MODEL_CATALOG_MAX_ATTEMPTS {
        cache.record_attempt(key).await;
        if let Some(batch) = &batch {
            batch.record(key, 0);
        }
        if attempt > 0 {
            cache.record_retry(key).await;
            if let Some(batch) = &batch {
                batch.record(key, 1);
            }
        }
        let result = fetch().await.filter(|models| !models.is_empty());
        if result.is_some() || attempt + 1 == IMPORTED_MODEL_CATALOG_MAX_ATTEMPTS {
            return result;
        }
        let remaining = deadline
            .checked_duration_since(Instant::now())
            .unwrap_or_default();
        if remaining.is_zero() {
            return None;
        }
        tokio::time::sleep(IMPORTED_MODEL_CATALOG_RETRY_BACKOFF.min(remaining)).await;
    }
    None
}

// Model discovery is published by normalized account type.  One authenticated
// Web catalog represents the type; source_type remains metadata for later
// conversation capability routing.
#[derive(Clone)]
struct CatalogOwners {
    candidates: Vec<CatalogAccountCandidate>,
    model_sources: HashMap<String, HashSet<String>>,
}

impl CatalogOwners {
    fn first(candidates: &[CatalogAccountCandidate]) -> Self {
        Self {
            candidates: candidates.first().cloned().into_iter().collect(),
            model_sources: HashMap::new(),
        }
    }

    fn with_model_sources(
        candidates: Vec<CatalogAccountCandidate>,
        model_sources: HashMap<String, HashSet<String>>,
    ) -> Self {
        Self {
            candidates,
            model_sources,
        }
    }

    fn is_current(&self, candidates: &[CatalogAccountCandidate]) -> bool {
        !self.candidates.is_empty()
            && self
                .candidates
                .iter()
                .all(|owner| candidates.iter().any(|candidate| candidate == owner))
    }

    fn any_current(&self, candidates: &[CatalogAccountCandidate]) -> bool {
        self.candidates
            .iter()
            .any(|owner| candidates.iter().any(|candidate| candidate == owner))
    }
}

#[derive(Clone)]
struct AccountTypeCatalogEntry {
    models: Arc<Vec<PublicModel>>,
    model_sources: HashMap<String, HashSet<String>>,
    ready: bool,
    tokens: Vec<String>,
    owners: CatalogOwners,
    expires_at: Instant,
    retry_at: Instant,
}

#[derive(Clone)]
struct AccountTypeCatalogSnapshot {
    generation: u64,
    anonymous_models: Arc<Vec<PublicModel>>,
    anonymous_ready: bool,
    anonymous_expires_at: Instant,
    anonymous_retry_at: Instant,
    entries: HashMap<AccountModelGroup, AccountTypeCatalogEntry>,
    live_tokens: HashMap<AccountModelGroup, Vec<String>>,
    live_candidates: HashMap<AccountModelGroup, Vec<CatalogAccountCandidate>>,
}

#[derive(Clone, Eq, Hash, PartialEq)]
enum CatalogFetchKey {
    Anonymous,
    AccountType {
        account_group: AccountModelGroup,
        expected_candidates: Vec<CatalogAccountCandidate>,
    },
}

enum CatalogFetchJob {
    Anonymous,
    AccountType {
        account_group: AccountModelGroup,
        expected_candidates: Vec<CatalogAccountCandidate>,
        candidate_accounts: Vec<CatalogAccountCandidate>,
    },
}

struct CatalogFetchResult {
    job: CatalogFetchJob,
    models: Option<Vec<PublicModel>>,
    owners: Option<CatalogOwners>,
    complete: bool,
}

impl CatalogFetchJob {
    fn key(&self) -> CatalogFetchKey {
        match self {
            Self::Anonymous => CatalogFetchKey::Anonymous,
            Self::AccountType {
                account_group,
                expected_candidates,
                ..
            } => CatalogFetchKey::AccountType {
                account_group: account_group.clone(),
                expected_candidates: expected_candidates.clone(),
            },
        }
    }
}

impl Default for AccountTypeCatalogSnapshot {
    fn default() -> Self {
        let now = Instant::now();
        Self {
            generation: 0,
            anonymous_models: Arc::new(Vec::new()),
            anonymous_ready: false,
            anonymous_expires_at: now,
            anonymous_retry_at: now,
            entries: HashMap::new(),
            live_tokens: HashMap::new(),
            live_candidates: HashMap::new(),
        }
    }
}

