async fn native_chat_requirements_with_resources_for_route_context(
    client: &Client,
    base_url: &str,
    token: &str,
    resources: &NativePowResources,
    timeout: Duration,
    authenticated: bool,
    context: &NativeRequestContext,
) -> Result<NativeRequirements, (ApiError, bool)> {
    let deadline = Instant::now() + timeout;
    let base_url = base_url.trim_end_matches('/');
    let route_base = if authenticated {
        "/backend-api"
    } else {
        "/backend-anon"
    };
    // The original web client builds a fresh PoW config for the prepare token
    // and another one when producing the optional proof token.
    let pow_config = native_pow_config_runtime(context.user_agent(), resources);
    let p_token =
        native_requirements_token_from_config(&pow_config).map_err(|error| (error, false))?;
    let prepare_path = format!("{route_base}/sentinel/chat-requirements/prepare");
    let mut prepare_request =
        native_browser_headers(client.post(format!("{base_url}{prepare_path}")), context)
            .header("X-OpenAI-Target-Path", &prepare_path)
            .header("X-OpenAI-Target-Route", &prepare_path)
            .json(&json!({"p": p_token}));
    if authenticated {
        prepare_request = prepare_request.header(header::AUTHORIZATION, format!("Bearer {token}"));
    }
    let prepare = prepare_request.send();
    let prepare_body = tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), async {
        let prepare = prepare
            .await
            .map_err(|error| (ApiError::upstream_detail(error.to_string()), true))?;
        let status = prepare.status();
        if !status.is_success() {
            return Err(
                native_upstream_failure(prepare, native_stage_retryable(status, true)).await,
            );
        }
        bounded_response_body(prepare)
            .await
            .map_err(|error| (error, false))
    })
    .await
    .map_err(|_| (ApiError::upstream_detail("operation timed out"), true))??;
    let prepare_value: Value =
        serde_json::from_slice(&prepare_body).map_err(|_| (ApiError::upstream(), false))?;
    if native_challenge_required(&prepare_value, "arkose").map_err(|error| (error, false))? {
        return Err((ApiError::upstream(), false));
    }
    let prepare_token = prepare_value
        .get("prepare_token")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| (ApiError::upstream(), false))?;
    let proof_token = native_proof_token(
        prepare_value.get("proofofwork"),
        context.user_agent(),
        resources,
        deadline,
    )
    .await
    .map_err(|_| (ApiError::upstream(), false))?;
    let turnstile_token =
        native_turnstile_token(prepare_value.get("turnstile"), &p_token, deadline)
            .await
            .map_err(|_| (ApiError::upstream(), false))?;
    let finalize_path = format!("{route_base}/sentinel/chat-requirements/finalize");
    let mut finalize_request =
        native_browser_headers(client.post(format!("{base_url}{finalize_path}")), context)
            .header("X-OpenAI-Target-Path", &finalize_path)
            .header("X-OpenAI-Target-Route", &finalize_path)
            .json(&json!({
                "prepare_token": prepare_token,
                "proof_token": proof_token.clone(),
                "turnstile_token": turnstile_token.clone(),
            }));
    if authenticated {
        finalize_request =
            finalize_request.header(header::AUTHORIZATION, format!("Bearer {token}"));
    }
    let finalize = finalize_request.send();
    let finalize_body = tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), async {
        let finalize = finalize
            .await
            .map_err(|error| (ApiError::upstream_detail(error.to_string()), true))?;
        let status = finalize.status();
        if !status.is_success() {
            return Err(
                native_upstream_failure(finalize, native_stage_retryable(status, false)).await,
            );
        }
        bounded_response_body(finalize)
            .await
            .map_err(|error| (error, false))
    })
    .await
    .map_err(|_| (ApiError::upstream_detail("operation timed out"), true))??;
    let finalize_value: Value =
        serde_json::from_slice(&finalize_body).map_err(|_| (ApiError::upstream(), false))?;
    if native_challenge_required(&finalize_value, "arkose").map_err(|error| (error, false))? {
        return Err((ApiError::upstream(), false));
    }
    if finalize_value
        .get("proof_token")
        .is_some_and(|value| !value.is_null())
        || finalize_value
            .get("turnstile_token")
            .is_some_and(|value| !value.is_null())
    {
        return Err((ApiError::upstream(), false));
    }
    let token = finalize_value
        .get("token")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(ToOwned::to_owned)
        .ok_or_else(|| (ApiError::upstream(), false))?;
    let optional_text = |key: &str| -> Result<Option<String>, (ApiError, bool)> {
        match finalize_value.get(key) {
            None | Some(Value::Null) => Ok(None),
            Some(Value::String(value)) if !value.trim().is_empty() => Ok(Some(value.clone())),
            _ => Err((ApiError::upstream(), false)),
        }
    };
    Ok(NativeRequirements {
        token,
        so_token: optional_text("so_token")?,
        proof_token: (!proof_token.is_empty()).then_some(proof_token),
        turnstile_token: (!turnstile_token.is_empty()).then_some(turnstile_token),
    })
}

type NativeChatUpstreamStream = Pin<Box<dyn Stream<Item = Result<Bytes, io::Error>> + Send>>;

async fn prime_native_chat_stream(
    response: reqwest::Response,
) -> Result<NativeChatUpstreamStream, ApiError> {
    let mut source = response.bytes_stream();
    let mut chunks = Vec::new();
    let mut buffer = Vec::new();
    let mut visible_text = String::new();
    let mut total = 0usize;
    let completion_id = native_completion_id();
    let model = "stream-prime";
    let created = native_created();
    let deadline = Instant::now() + NATIVE_UPSTREAM_TIMEOUT;
    let mut first_visible_event = false;
    let mut clean_eof = false;
    while !first_visible_event {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(ApiError::upstream());
        }
        let next = tokio::time::timeout(remaining, source.next())
            .await
            .map_err(|_| ApiError::upstream())?;
        let Some(next) = next else {
            clean_eof = true;
            break;
        };
        let chunk = next.map_err(|_| ApiError::upstream())?;
        total = total
            .checked_add(chunk.len())
            .filter(|total| *total <= MAX_UPSTREAM_BODY_BYTES)
            .ok_or_else(ApiError::upstream)?;
        chunks.push(chunk.clone());
        buffer.extend_from_slice(&chunk);
        while let Some((position, delimiter_length)) = sse_delimiter(&buffer) {
            let event = buffer.drain(..position).collect::<Vec<_>>();
            buffer.drain(..delimiter_length);
            if let Some(frame) = native_frame(
                &event,
                &mut visible_text,
                &completion_id,
                model,
                created,
                false,
            )
            .map_err(|_| ApiError::upstream())?
            {
                if frame == b"data: [DONE]\n\n" {
                    first_visible_event = true;
                    break;
                }
                let json = frame
                    .strip_prefix(b"data: ")
                    .and_then(|frame| serde_json::from_slice::<Value>(frame).ok());
                first_visible_event = json
                    .as_ref()
                    .and_then(|frame| frame["choices"][0]["delta"]["content"].as_str())
                    .is_some_and(|delta| !delta.is_empty());
                if first_visible_event {
                    break;
                }
            }
        }
    }
    if clean_eof && !first_visible_event {
        chunks.push(Bytes::from_static(b"data: [DONE]\n\n"));
    }
    let prefix = stream::iter(chunks.into_iter().map(Ok::<Bytes, io::Error>));
    let remainder =
        source.map(|chunk| chunk.map_err(|_| io::Error::other("upstream stream failed")));
    Ok(Box::pin(prefix.chain(remainder)))
}

fn openai_stream_error_frame() -> Bytes {
    Bytes::from_static(
        br#"data: {"error":{"message":"upstream stream failed","type":"RuntimeError"}}

data: [DONE]

"#,
    )
}

#[allow(clippy::too_many_arguments)]
async fn native_stream_response(
    state: AppState,
    response: reqwest::Response,
    lease: Option<AccountLease>,
    model: String,
    include_usage: bool,
    prompt_tokens: usize,
    stream_cache: Option<(String, Arc<ChatCacheInflight>)>,
    history_text: String,
    history_messages: Vec<String>,
) -> Result<Response, ApiError> {
    let input: NativeChatUpstreamStream = match prime_native_chat_stream(response).await {
        Ok(input) => input,
        Err(error) => {
            if let Some((key, inflight)) = stream_cache.as_ref() {
                chat_cache_finish_stream(
                    &state,
                    key,
                    inflight,
                    Err("upstream stream failed".to_owned()),
                );
            }
            return Err(error);
        }
    };
    let completion_id = native_completion_id();
    let created = native_created();
    let cache_state = stream_cache.map(|(key, inflight)| StreamCacheOutput {
        state: state.clone(),
        key,
        inflight,
        frames: Vec::new(),
        finished: false,
    });
    let history_text = Arc::<str>::from(history_text);
    let history_messages = Arc::new(history_messages);
    let history_index = Arc::new(AtomicUsize::new(0));
    let stream = stream::unfold(
        (
            input,
            VecDeque::from([b": stream-open\n\n".to_vec()]),
            Vec::new(),
            String::new(),
            0usize,
            false,
            false,
            Some(lease),
            completion_id,
            model,
            created,
            include_usage,
            prompt_tokens,
            cache_state,
        ),
        move |(
            mut input,
            mut pending,
            mut buffer,
            mut text,
            mut total,
            mut finished,
            mut role_sent,
            mut lease,
            completion_id,
            model,
            created,
            include_usage,
            prompt_tokens,
            mut cache_state,
        )| {
            let history_text = history_text.clone();
            let history_messages = history_messages.clone();
            let history_index = history_index.clone();
            async move {
                loop {
                    if let Some(frame) = pending.pop_front() {
                        if let Some(cache) = cache_state.as_mut() {
                            cache.frames.push(frame.clone());
                        }
                        return Some((
                            Ok(Bytes::from(frame)),
                            (
                                input,
                                pending,
                                buffer,
                                text,
                                total,
                                finished,
                                role_sent,
                                lease,
                                completion_id,
                                model,
                                created,
                                include_usage,
                                prompt_tokens,
                                cache_state,
                            ),
                        ));
                    }
                    if finished {
                        if let Some(cache) = cache_state.as_mut() {
                            cache.finish(Ok(cache.frames.clone()));
                        }
                        drop(lease.take());
                        return None;
                    }
                    let next = tokio::time::timeout(NATIVE_UPSTREAM_TIMEOUT, input.next()).await;
                    let chunk = match next {
                        Ok(Some(Ok(chunk))) => chunk,
                        Ok(Some(Err(_))) | Err(_) => {
                            if let Some(cache) = cache_state.as_mut() {
                                cache.finish(Err("upstream stream failed".to_owned()));
                            }
                            drop(lease.take());
                            return Some((
                                Err(io::Error::other("upstream stream failed")),
                                (
                                    input,
                                    pending,
                                    buffer,
                                    text,
                                    total,
                                    true,
                                    role_sent,
                                    lease,
                                    completion_id,
                                    model,
                                    created,
                                    include_usage,
                                    prompt_tokens,
                                    cache_state,
                                ),
                            ));
                        }
                        Ok(None) => {
                            if !buffer.is_empty() {
                                buffer.extend_from_slice(b"\n\n");
                            }
                            buffer.extend_from_slice(b"data: [DONE]\n\n");
                            Bytes::new()
                        }
                    };
                    total = match total.checked_add(chunk.len()) {
                        Some(total) if total <= MAX_UPSTREAM_BODY_BYTES => total,
                        _ => {
                            if let Some(cache) = cache_state.as_mut() {
                                cache.finish(Err("upstream body exceeded limit".to_owned()));
                            }
                            drop(lease.take());
                            return Some((
                                Err(io::Error::other("upstream body exceeded limit")),
                                (
                                    input,
                                    pending,
                                    buffer,
                                    text,
                                    total,
                                    true,
                                    role_sent,
                                    lease,
                                    completion_id,
                                    model,
                                    created,
                                    include_usage,
                                    prompt_tokens,
                                    cache_state,
                                ),
                            ));
                        }
                    };
                    buffer.extend_from_slice(&chunk);
                    while let Some((position, delimiter_length)) = sse_delimiter(&buffer) {
                        let event = buffer.drain(..position).collect::<Vec<_>>();
                        buffer.drain(..delimiter_length);
                        match native_frame_with_history_messages(
                            &event,
                            &mut text,
                            &completion_id,
                            &model,
                            created,
                            include_usage,
                            &history_text,
                            &history_messages,
                            &history_index,
                        ) {
                            Ok(Some(frame)) => {
                                if frame == b"data: [DONE]\n\n" {
                                    finished = true;
                                    if !role_sent {
                                        pending.push_back(native_role_frame(
                                            &completion_id,
                                            &model,
                                            created,
                                            include_usage,
                                        ));
                                        role_sent = true;
                                    }
                                    pending.push_back(native_finish_frame(
                                        &completion_id,
                                        &model,
                                        created,
                                        include_usage,
                                    ));
                                    if include_usage {
                                        match native_usage_for_prompt_tokens(
                                            &model,
                                            prompt_tokens,
                                            &text,
                                        ) {
                                            Ok(usage) => pending.push_back(native_usage_frame(
                                                &completion_id,
                                                &model,
                                                created,
                                                usage,
                                            )),
                                            Err(_) => {
                                                if let Some(cache) = cache_state.as_mut() {
                                                    cache.finish(Err(
                                                        "upstream usage calculation failed"
                                                            .to_owned(),
                                                    ));
                                                }
                                                drop(lease.take());
                                                return Some((
                                                    Err(io::Error::other(
                                                        "upstream usage calculation failed",
                                                    )),
                                                    (
                                                        input,
                                                        pending,
                                                        buffer,
                                                        text,
                                                        total,
                                                        true,
                                                        role_sent,
                                                        lease,
                                                        completion_id,
                                                        model,
                                                        created,
                                                        include_usage,
                                                        prompt_tokens,
                                                        cache_state,
                                                    ),
                                                ));
                                            }
                                        }
                                    }
                                } else {
                                    role_sent = true;
                                }
                                pending.push_back(frame);
                                if finished {
                                    break;
                                }
                            }
                            Ok(None) => {}
                            Err(error) => {
                                if let Some(cache) = cache_state.as_mut() {
                                    cache.finish(Err(error.to_string()));
                                }
                                drop(lease.take());
                                return Some((
                                    Err(error),
                                    (
                                        input,
                                        pending,
                                        buffer,
                                        text,
                                        total,
                                        true,
                                        role_sent,
                                        lease,
                                        completion_id,
                                        model,
                                        created,
                                        include_usage,
                                        prompt_tokens,
                                        cache_state,
                                    ),
                                ));
                            }
                        }
                    }
                    if finished {
                        continue;
                    }
                }
            }
        },
    );
    let stream = stream.map(|item| match item {
        Ok(bytes) => Ok::<Bytes, io::Error>(bytes),
        Err(_) => Ok::<Bytes, io::Error>(openai_stream_error_frame()),
    });
    let mut output = Response::new(Body::from_stream(stream));
    output.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    output
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    Ok(output)
}

fn native_turnstile_concat_string(value: &Value) -> Option<String> {
    match value {
        Value::Array(values) if !values.iter().all(Value::is_string) => {
            native_turnstile_python_repr(value)
        }
        Value::Object(_) => native_turnstile_python_repr(value),
        _ => native_turnstile_string(value),
    }
}

fn native_chat_tool_frame(
    completion_id: &str,
    model: &str,
    created: i64,
    tool_call: Value,
    include_usage: bool,
) -> Vec<u8> {
    let mut frame = json!({
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model,
        "choices": [{"index":0,"delta":{"tool_calls":[tool_call]},"finish_reason":null}],
    });
    if include_usage {
        frame["usage"] = Value::Null;
    }
    let mut output = b"data: ".to_vec();
    output.extend(serde_json::to_vec(&frame).expect("static tool frame"));
    output.extend_from_slice(b"\n\n");
    output
}

fn native_chat_finish_frame(
    completion_id: &str,
    model: &str,
    created: i64,
    reason: &str,
    include_usage: bool,
) -> Vec<u8> {
    let mut frame = json!({
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model,
        "choices": [{"index":0,"delta":{},"finish_reason":reason}],
    });
    if include_usage {
        frame["usage"] = Value::Null;
    }
    let mut output = b"data: ".to_vec();
    output.extend(serde_json::to_vec(&frame).expect("static finish frame"));
    output.extend_from_slice(b"\n\n");
    output
}

fn native_chat_usage_from_response(
    response: &Value,
    model: &str,
    prompt_tokens: usize,
) -> Result<Value, io::Error> {
    let Some(usage) = response.get("usage").and_then(Value::as_object) else {
        return native_usage_for_prompt_tokens(model, prompt_tokens, "")
            .map_err(|_| io::Error::other("Codex usage calculation failed"));
    };
    let input_tokens = usage
        .get("input_tokens")
        .and_then(Value::as_u64)
        .ok_or_else(|| io::Error::other("malformed Codex usage"))?;
    let output_tokens = usage
        .get("output_tokens")
        .and_then(Value::as_u64)
        .ok_or_else(|| io::Error::other("malformed Codex usage"))?;
    let total_tokens = usage
        .get("total_tokens")
        .and_then(Value::as_u64)
        .ok_or_else(|| io::Error::other("malformed Codex usage"))?;
    Ok(json!({
        "prompt_tokens": input_tokens,
        "completion_tokens": output_tokens,
        "total_tokens": total_tokens,
    }))
}

struct NativeCodexChatStreamState {
    input: Pin<Box<dyn Stream<Item = Result<Bytes, reqwest::Error>> + Send>>,
    pending: VecDeque<Vec<u8>>,
    buffer: Vec<u8>,
    total: usize,
    finished: bool,
    role_sent: bool,
    lease: Option<AccountLease>,
    completion_id: String,
    model: String,
    created: i64,
    include_usage: bool,
    prompt_tokens: usize,
    item_indexes: HashMap<String, usize>,
    argument_deltas: HashSet<String>,
    saw_tool_call: bool,
}

fn native_codex_stream_response(
    response: reqwest::Response,
    lease: Option<AccountLease>,
    model: String,
    include_usage: bool,
    prompt_tokens: usize,
) -> Response {
    let state = NativeCodexChatStreamState {
        input: Box::pin(response.bytes_stream()),
        pending: VecDeque::from([b": stream-open\n\n".to_vec()]),
        buffer: Vec::new(),
        total: 0,
        finished: false,
        role_sent: false,
        lease,
        completion_id: native_completion_id(),
        created: native_created(),
        model,
        include_usage,
        prompt_tokens,
        item_indexes: HashMap::new(),
        argument_deltas: HashSet::new(),
        saw_tool_call: false,
    };
    let stream = stream::unfold(state, |mut state| async move {
        loop {
            if let Some(frame) = state.pending.pop_front() {
                return Some((Ok(Bytes::from(frame)), state));
            }
            if state.finished {
                drop(state.lease.take());
                return None;
            }
            let next = tokio::time::timeout(NATIVE_UPSTREAM_TIMEOUT, state.input.next()).await;
            let chunk = match next {
                Ok(Some(Ok(chunk))) => chunk,
                Ok(Some(Err(_))) | Err(_) => {
                    drop(state.lease.take());
                    state.finished = true;
                    return Some((Err(io::Error::other("Codex upstream stream failed")), state));
                }
                Ok(None) => {
                    drop(state.lease.take());
                    state.finished = true;
                    return Some((
                        Err(io::Error::other(
                            "Codex stream ended without terminal event",
                        )),
                        state,
                    ));
                }
            };
            state.total = match state.total.checked_add(chunk.len()) {
                Some(total) if total <= MAX_UPSTREAM_BODY_BYTES => total,
                _ => {
                    drop(state.lease.take());
                    state.finished = true;
                    return Some((
                        Err(io::Error::other("Codex upstream body exceeded limit")),
                        state,
                    ));
                }
            };
            state.buffer.extend_from_slice(&chunk);
            while let Some((position, delimiter_length)) = sse_delimiter(&state.buffer) {
                let event = state.buffer.drain(..position).collect::<Vec<_>>();
                state.buffer.drain(..delimiter_length);
                let data = match codex_sse_data(&event) {
                    Ok(Some(data)) => data,
                    Ok(None) => continue,
                    Err(error) => {
                        drop(state.lease.take());
                        state.finished = true;
                        return Some((Err(error), state));
                    }
                };
                if data == "[DONE]" {
                    continue;
                }
                let value: Value = match serde_json::from_str(&data) {
                    Ok(value) => value,
                    Err(_) => {
                        drop(state.lease.take());
                        state.finished = true;
                        return Some((Err(io::Error::other("malformed Codex event")), state));
                    }
                };
                if !codex_response_event_is_known(&value) {
                    continue;
                }
                let event_type = match validate_codex_response_event(&value) {
                    Ok(event_type) => event_type,
                    Err(error) => {
                        drop(state.lease.take());
                        state.finished = true;
                        return Some((Err(error), state));
                    }
                };
                match event_type {
                    "response.created" => {
                        if let Some(response) = value.get("response").and_then(Value::as_object) {
                            if let Some(id) = response.get("id").and_then(Value::as_str) {
                                state.completion_id = if id.starts_with("chatcmpl-") {
                                    id.to_owned()
                                } else {
                                    format!("chatcmpl-{id}")
                                };
                            }
                            if let Some(model) = response.get("model").and_then(Value::as_str) {
                                state.model = model.to_owned();
                            }
                            if let Some(created) =
                                response.get("created_at").and_then(Value::as_i64)
                            {
                                state.created = created;
                            }
                        }
                        if !state.role_sent {
                            state.pending.push_back(native_role_frame(
                                &state.completion_id,
                                &state.model,
                                state.created,
                                state.include_usage,
                            ));
                            state.role_sent = true;
                        }
                    }
                    "response.output_text.delta" => {
                        let delta = value
                            .get("delta")
                            .and_then(Value::as_str)
                            .ok_or_else(|| io::Error::other("malformed Codex delta"));
                        let delta = match delta {
                            Ok(delta) => delta,
                            Err(error) => {
                                drop(state.lease.take());
                                state.finished = true;
                                return Some((Err(error), state));
                            }
                        };
                        state.pending.push_back(native_codex_delta_frame(
                            &state.completion_id,
                            &state.model,
                            state.created,
                            delta,
                            state.include_usage,
                            !state.role_sent,
                        ));
                        state.role_sent = true;
                    }
                    "response.output_item.added" => {
                        let item = value.get("item").expect("validated output item");
                        if item.get("type").and_then(Value::as_str) == Some("function_call") {
                            let item_id =
                                item.get("id").and_then(Value::as_str).unwrap_or_else(|| {
                                    item.get("call_id")
                                        .and_then(Value::as_str)
                                        .unwrap_or_default()
                                });
                            let call_id = item
                                .get("call_id")
                                .and_then(Value::as_str)
                                .unwrap_or_default();
                            let name = item.get("name").and_then(Value::as_str).unwrap_or_default();
                            let index = state.item_indexes.len();
                            state.item_indexes.insert(item_id.to_owned(), index);
                            state.saw_tool_call = true;
                            if !state.role_sent {
                                state.pending.push_back(native_role_frame(
                                    &state.completion_id,
                                    &state.model,
                                    state.created,
                                    state.include_usage,
                                ));
                                state.role_sent = true;
                            }
                            state.pending.push_back(native_chat_tool_frame(
                                &state.completion_id,
                                &state.model,
                                state.created,
                                json!({
                                    "index": index,
                                    "id": call_id,
                                    "type": "function",
                                    "function": {"name": name, "arguments": ""}
                                }),
                                state.include_usage,
                            ));
                        }
                    }
                    "response.function_call_arguments.delta" => {
                        let item_id = value.get("item_id").and_then(Value::as_str);
                        let delta = value.get("delta").and_then(Value::as_str);
                        let (Some(item_id), Some(delta), Some(index)) = (
                            item_id,
                            delta,
                            item_id.and_then(|id| state.item_indexes.get(id).copied()),
                        ) else {
                            drop(state.lease.take());
                            state.finished = true;
                            return Some((
                                Err(io::Error::other("malformed Codex function call delta")),
                                state,
                            ));
                        };
                        state.argument_deltas.insert(item_id.to_owned());
                        if !state.role_sent {
                            state.pending.push_back(native_role_frame(
                                &state.completion_id,
                                &state.model,
                                state.created,
                                state.include_usage,
                            ));
                            state.role_sent = true;
                        }
                        state.pending.push_back(native_chat_tool_frame(
                            &state.completion_id,
                            &state.model,
                            state.created,
                            json!({"index":index,"function":{"arguments":delta}}),
                            state.include_usage,
                        ));
                    }
                    "response.output_item.done" => {
                        let item = value.get("item").expect("validated output item");
                        if item.get("type").and_then(Value::as_str) == Some("function_call") {
                            let item_id =
                                item.get("id").and_then(Value::as_str).unwrap_or_else(|| {
                                    item.get("call_id")
                                        .and_then(Value::as_str)
                                        .unwrap_or_default()
                                });
                            if let Some(index) = state.item_indexes.get(item_id).copied()
                                && !state.argument_deltas.contains(item_id)
                                && let Some(arguments) =
                                    item.get("arguments").and_then(Value::as_str)
                            {
                                state.pending.push_back(native_chat_tool_frame(
                                    &state.completion_id,
                                    &state.model,
                                    state.created,
                                    json!({"index":index,"function":{"arguments":arguments}}),
                                    state.include_usage,
                                ));
                            }
                        }
                    }
                    "response.completed" | "response.incomplete" => {
                        if !state.role_sent {
                            state.pending.push_back(native_role_frame(
                                &state.completion_id,
                                &state.model,
                                state.created,
                                state.include_usage,
                            ));
                            state.role_sent = true;
                        }
                        let reason = if event_type == "response.incomplete" {
                            "length"
                        } else if state.saw_tool_call {
                            "tool_calls"
                        } else {
                            "stop"
                        };
                        state.pending.push_back(native_chat_finish_frame(
                            &state.completion_id,
                            &state.model,
                            state.created,
                            reason,
                            state.include_usage,
                        ));
                        if state.include_usage {
                            let response = value.get("response").cloned().unwrap_or(Value::Null);
                            let usage = match native_chat_usage_from_response(
                                &response,
                                &state.model,
                                state.prompt_tokens,
                            ) {
                                Ok(usage) => usage,
                                Err(error) => {
                                    drop(state.lease.take());
                                    state.finished = true;
                                    return Some((Err(error), state));
                                }
                            };
                            state.pending.push_back(native_usage_frame(
                                &state.completion_id,
                                &state.model,
                                state.created,
                                usage,
                            ));
                        }
                        state.pending.push_back(b"data: [DONE]\n\n".to_vec());
                        state.finished = true;
                        break;
                    }
                    "response.failed" | "error" => {
                        drop(state.lease.take());
                        state.finished = true;
                        return Some((Err(io::Error::other("Codex response failed")), state));
                    }
                    _ => {}
                }
                if state.finished {
                    break;
                }
            }
            if !state.pending.is_empty() || state.finished {
                continue;
            }
        }
    });
    let stream = stream.map(|item| match item {
        Ok(bytes) => Ok::<Bytes, io::Error>(bytes),
        Err(_) => Ok::<Bytes, io::Error>(openai_stream_error_frame()),
    });
    let mut output = Response::new(Body::from_stream(stream));
    output.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    output
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    output
}

async fn native_codex_response_attempt(
    state: &AppState,
    client: &Client,
    lease: &AccountLease,
    base_url: &str,
    payload: &Value,
    version: Option<&str>,
    timeout: Duration,
) -> Result<reqwest::Response, (ApiError, bool)> {
    let url = format!(
        "{}/backend-api/codex/responses",
        base_url.trim_end_matches('/')
    );
    let request = codex_request_headers(
        native_browser_headers_with_clearance(
            client.post(url),
            &lease.native_request_context(),
            &format!("{base_url}/"),
            Some(&state.clearance_store),
            Some(&proxy_runtime_value(state)),
            lease.proxy_url().unwrap_or_default(),
            base_url,
            None,
        )
        .await,
        lease.token(),
        lease.chatgpt_account_id().map(ToOwned::to_owned),
        version,
    )
    .ok_or_else(|| (ApiError::upstream(), false))?
    .json(payload);
    let response = tokio::time::timeout(timeout, request.send())
        .await
        .map_err(|_| (ApiError::upstream(), false))?
        .map_err(|_| (ApiError::upstream(), false))?;
    if !response.status().is_success() {
        if response.status() == StatusCode::UNAUTHORIZED {
            return Err((ApiError::unauthorized(), false));
        }
        let retryable = matches!(
            response.status(),
            StatusCode::TOO_MANY_REQUESTS
                | StatusCode::INTERNAL_SERVER_ERROR
                | StatusCode::BAD_GATEWAY
                | StatusCode::SERVICE_UNAVAILABLE
                | StatusCode::GATEWAY_TIMEOUT
        );
        return Err((ApiError::upstream(), retryable));
    }
    if upstream_declares_oversize(&response) {
        return Err((ApiError::upstream(), false));
    }
    Ok(response)
}

async fn native_conversation_attempt(
    state: &AppState,
    client: &Client,
    lease: Option<&AccountLease>,
    base_url: &str,
    token: &str,
    payload: &Value,
    chat_object: &mut Map<String, Value>,
) -> Result<reqwest::Response, (ApiError, bool)> {
    let authenticated = !token.is_empty();
    let context = lease
        .map(AccountLease::native_request_context)
        .unwrap_or_else(NativeRequestContext::new);
    let pow_resources = match native_bootstrap(client, base_url, token, &context).await {
        Ok(resources) => resources,
        Err(error) => return Err(error),
    };
    let requirements = match native_chat_requirements_with_resources_for_route_context(
        client,
        base_url,
        token,
        &pow_resources,
        NATIVE_UPSTREAM_TIMEOUT,
        authenticated,
        &context,
    )
    .await
    {
        Ok(requirements) => requirements,
        Err(error) => return Err(error),
    };
    let mut payload = native_conversation_payload_with_images(
        state,
        client,
        lease,
        &context,
        payload,
        chat_object,
    )
    .await
    .map_err(|error| (error, false))?;
    if !authenticated {
        payload["timezone"] = Value::String("America/Los_Angeles".to_owned());
    }
    let route_base = if authenticated {
        "/backend-api/conversation"
    } else {
        "/backend-anon/conversation"
    };
    let url = format!("{}{route_base}", base_url.trim_end_matches('/'));
    let mut request = if let Some(lease) = lease {
        native_browser_headers_with_clearance(
            client.post(url),
            &context,
            &format!("{base_url}/"),
            Some(&state.clearance_store),
            Some(&proxy_runtime_value(state)),
            lease.proxy_url().unwrap_or_default(),
            base_url,
            None,
        )
        .await
    } else {
        native_browser_headers(client.post(url), &context)
    }
    .header(header::ACCEPT, "text/event-stream")
    .header("X-OpenAI-Target-Path", route_base)
    .header("X-OpenAI-Target-Route", route_base)
    .header(
        "OpenAI-Sentinel-Chat-Requirements-Token",
        requirements.token,
    )
    .json(&payload);
    if authenticated {
        request = request.header(header::AUTHORIZATION, format!("Bearer {token}"));
    }
    if let Some(value) = requirements.so_token {
        request = request.header("OpenAI-Sentinel-SO-Token", value);
    }
    if let Some(value) = requirements.proof_token {
        request = request.header("OpenAI-Sentinel-Proof-Token", value);
    }
    if let Some(value) = requirements.turnstile_token {
        request = request.header("OpenAI-Sentinel-Turnstile-Token", value);
    }
    let upstream = tokio::time::timeout(NATIVE_UPSTREAM_TIMEOUT, request.send())
        .await
        .map_err(|_| (ApiError::upstream(), false))?
        .map_err(|_| (ApiError::upstream(), false))?;
    if !upstream.status().is_success() {
        let status = upstream.status();
        let retryable = matches!(
            status,
            StatusCode::TOO_MANY_REQUESTS
                | StatusCode::INTERNAL_SERVER_ERROR
                | StatusCode::BAD_GATEWAY
                | StatusCode::SERVICE_UNAVAILABLE
                | StatusCode::GATEWAY_TIMEOUT
        );
        return Err(native_upstream_failure(upstream, retryable).await);
    }
    if upstream_declares_oversize(&upstream) {
        return Err((ApiError::upstream(), false));
    }
    Ok(upstream)
}

async fn chat_completions(
    state: State<AppState>,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, ApiError> {
    authenticated(&headers, &state).await?;
    let started = Instant::now();
    let log_state = state.0.clone();
    let log_identity = request_log_identity(&log_state, &headers);
    let bytes = to_bytes(body, MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::validation())?;
    let request_model = request_model_for_log(&bytes);
    let (request_text, request_shape) =
        request_log_context(&bytes, &["prompt", "messages"], &["messages"]);
    let result = chat_completions_authenticated_with_timeout(
        state,
        headers,
        Body::from(bytes),
        NATIVE_UPSTREAM_TIMEOUT,
        false,
        None,
    )
    .await;
    match &result {
        Ok(_) => append_api_call_log_with_context_and_identity(
            &log_state,
            "/v1/chat/completions",
            &request_model,
            "文本生成",
            started,
            "success",
            request_text.as_deref(),
            request_shape.as_ref(),
            None,
            log_identity.as_ref(),
        ),
        Err(error) => append_api_call_log_with_context_and_identity(
            &log_state,
            "/v1/chat/completions",
            &request_model,
            "文本生成",
            started,
            "failed",
            request_text.as_deref(),
            request_shape.as_ref(),
            Some(error.code()),
            log_identity.as_ref(),
        ),
    }
    result
}

