fn responses_text_to_chat_object(
    object: &Map<String, Value>,
) -> Result<Map<String, Value>, ApiError> {
    let normalized = if let Some(input) = object.get("input") {
        native_responses_text_input(input)?
    } else {
        Value::Array(Vec::new())
    };
    let items = normalized
        .as_array()
        .ok_or_else(ApiError::invalid_request)?;
    let mut messages = Vec::new();
    if let Some(instructions) = object
        .get("instructions")
        .filter(|value| account_pool::account_value_truthy(Some(value)))
        .map(|value| protocol_anthropic::python_text(Some(value)))
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
    {
        messages.push(json!({"role": "system", "content": instructions}));
    }
    for item in items {
        let item = item.as_object().ok_or_else(ApiError::invalid_request)?;
        let role_value = item
            .get("role")
            .filter(|value| account_pool::account_value_truthy(Some(value)))
            .map(account_pool::python_account_value_string)
            .map(Value::String)
            .unwrap_or_else(|| json!("user"));
        let role = role_value.as_str().unwrap_or("user");
        let content = item.get("content").ok_or_else(ApiError::invalid_request)?;
        let content = match content {
            Value::String(value) => Value::String(value.clone()),
            Value::Array(parts) => {
                let mut chat_parts = Vec::new();
                for part in parts {
                    let Some(part) = part.as_object() else {
                        if let Some(text) = part.as_str() {
                            chat_parts.push(json!({"type":"text","text":text}));
                        }
                        continue;
                    };
                    let raw_kind = part.get("type").and_then(Value::as_str);
                    let trimmed_kind = raw_kind.map(str::trim);
                    match raw_kind {
                        Some("input_text" | "output_text" | "text") => {
                            let text = part
                                .get("text")
                                .map(|value| protocol_anthropic::python_text(Some(value)))
                                .unwrap_or_default();
                            chat_parts.push(json!({"type":"text","text":text}));
                        }
                        _ if role == "user"
                            && matches!(
                                trimmed_kind,
                                Some("input_image" | "image_url" | "image")
                            ) =>
                        {
                            let image_url = if trimmed_kind == Some("image_url") {
                                native_image_url_reference(part)
                            } else {
                                native_image_part_reference(part)
                            };
                            if let Some(image_url) = image_url {
                                chat_parts.push(json!({
                                    "type": "image_url",
                                    "image_url": image_url,
                                }));
                            }
                        }
                        _ => {}
                    }
                }
                if chat_parts.is_empty() {
                    Value::String(String::new())
                } else {
                    Value::Array(chat_parts)
                }
            }
            _ => return Err(ApiError::invalid_request()),
        };
        messages.push(json!({"role": role_value, "content": content}));
    }
    let mut chat = Map::new();
    chat.insert(
        "model".to_owned(),
        object
            .get("model")
            .cloned()
            .ok_or_else(ApiError::invalid_request)?,
    );
    chat.insert("messages".to_owned(), Value::Array(messages));
    chat.insert(
        "stream".to_owned(),
        object
            .get("stream")
            .cloned()
            .unwrap_or_else(|| json!(false)),
    );
    if native_response_has_web_search_tool(object) {
        chat.insert(
            "tools".to_owned(),
            Value::Array(vec![json!({"type":"web_search_preview"})]),
        );
    }
    if let Some(reasoning) = object.get("reasoning").filter(|value| !value.is_null()) {
        chat.insert("reasoning".to_owned(), reasoning.clone());
    }
    if object.contains_key("reasoning")
        || object.contains_key("thinking_effort")
        || object.contains_key("reasoning_effort")
    {
        chat.insert(
            "thinking_effort".to_owned(),
            Value::String(protocol_responses::python_responses_thinking_effort(object)),
        );
    }
    Ok(chat)
}

fn ensure_responses_chat_route_messages(chat: &mut Map<String, Value>) {
    if chat
        .get("messages")
        .and_then(Value::as_array)
        .is_none_or(|messages| messages.is_empty())
    {
        chat.insert(
            "messages".to_owned(),
            json!([{"role": "user", "content": ""}]),
        );
    }
}

fn response_from_chat_value(value: &Value, model: &str) -> Result<Value, ApiError> {
    let choice = value
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .and_then(Value::as_object)
        .ok_or_else(ApiError::upstream)?;
    let message = choice
        .get("message")
        .and_then(Value::as_object)
        .ok_or_else(ApiError::upstream)?;
    let text = message
        .get("content")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let response_id = format!("resp_{}", native_message_id());
    let item_id = format!("msg_{}", native_message_id());
    let item = json!({
        "id": item_id,
        "type": "message",
        "status": "completed",
        "role": "assistant",
        "content": [{"type": "output_text", "text": text, "annotations": []}],
    });
    let mut response = json!({
        "id": response_id,
        "object": "response",
        "created_at": native_created(),
        "status": "completed",
        "error": Value::Null,
        "incomplete_details": Value::Null,
        "model": model,
        "output": [item],
        "parallel_tool_calls": false,
    });
    if let Some(usage) = value.get("usage").and_then(Value::as_object) {
        response["usage"] = native_responses_usage_from_chat(&Value::Object(usage.clone()));
    }
    Ok(response)
}

fn native_responses_usage_from_chat(usage: &Value) -> Value {
    let input_details = usage.get("prompt_tokens_details");
    let output_details = usage.get("completion_tokens_details");
    let input_tokens = usage
        .get("prompt_tokens")
        .and_then(Value::as_u64)
        .unwrap_or_default();
    let output_tokens = usage
        .get("completion_tokens")
        .and_then(Value::as_u64)
        .unwrap_or_default();
    json!({
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "total_tokens": input_tokens.saturating_add(output_tokens),
        "input_tokens_details": {
            "text_tokens": input_details.and_then(|details| details.get("text_tokens")).and_then(Value::as_u64).unwrap_or_default(),
            "image_tokens": input_details.and_then(|details| details.get("image_tokens")).and_then(Value::as_u64).unwrap_or_default(),
            "cached_tokens": input_details.and_then(|details| details.get("cached_tokens")).and_then(Value::as_u64).unwrap_or_default(),
        },
        "output_tokens_details": {
            "text_tokens": output_details.and_then(|details| details.get("text_tokens")).and_then(Value::as_u64).unwrap_or_default(),
            "image_tokens": output_details.and_then(|details| details.get("image_tokens")).and_then(Value::as_u64).unwrap_or_default(),
            "reasoning_tokens": output_details.and_then(|details| details.get("reasoning_tokens")).and_then(Value::as_u64).unwrap_or_default(),
        }
    })
}

fn native_responses_web_search_output(query: &str, result: &Value) -> (Value, String, Value) {
    let (text, chat_annotations) = native_chat_search_text(result);
    let annotations = chat_annotations
        .iter()
        .filter_map(|annotation| {
            let citation = annotation.get("url_citation")?;
            Some(json!({
                "type":"url_citation",
                "start_index":citation.get("start_index").cloned().unwrap_or(json!(0)),
                "end_index":citation.get("end_index").cloned().unwrap_or(json!(0)),
                "url":citation.get("url").cloned().unwrap_or(Value::Null),
                "title":citation.get("title").cloned().unwrap_or(Value::Null),
            }))
        })
        .collect::<Vec<_>>();
    let sources = result
        .get("sources")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|source| {
            let url = source
                .get("url")
                .and_then(Value::as_str)
                .filter(|url| url.starts_with("http://") || url.starts_with("https://"))?;
            Some(json!({"type":"url","url":url}))
        })
        .take(NATIVE_SEARCH_MAX_SOURCES)
        .collect::<Vec<_>>();
    let search_item = json!({
        "id": format!("ws_{}", native_message_id()),
        "type":"web_search_call",
        "status":"completed",
        "action": {
            "type":"search",
            "query":query,
            "queries":[query],
            "sources":sources,
        }
    });
    let message_item = json!({
        "id":format!("msg_{}", native_message_id()),
        "type":"message",
        "status":"completed",
        "role":"assistant",
        "content":[{"type":"output_text","text":text,"annotations":annotations}]
    });
    (search_item, text, message_item)
}

async fn native_responses_web_search_completion(
    state: AppState,
    object: Map<String, Value>,
    timeout: Duration,
) -> Result<Response, ApiError> {
    let model = object
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or("auto")
        .to_owned();
    let mut chat = responses_text_to_chat_object(&object)?;
    apply_global_system_prompt_to_chat(&state, &mut chat);
    let query = native_chat_search_query(&chat)?;
    let result_response = native_search_with_timeout(state, query.clone(), timeout).await?;
    let body = to_bytes(result_response.into_body(), MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::upstream())?;
    let result: Value = serde_json::from_slice(&body).map_err(|_| ApiError::upstream())?;
    let (search_item, text, message_item) = native_responses_web_search_output(&query, &result);
    let usage = native_usage(&chat, &text)?;
    let response_id = format!("resp_{}", native_message_id());
    let created = native_created();
    let usage = json!({
        "input_tokens":usage["prompt_tokens"],
        "output_tokens":usage["completion_tokens"],
        "total_tokens":usage["total_tokens"],
        "input_tokens_details":{
            "text_tokens":usage["prompt_tokens_details"]["text_tokens"],
            "image_tokens":usage["prompt_tokens_details"]["image_tokens"],
            "cached_tokens":usage["prompt_tokens_details"]["cached_tokens"],
        },
        "output_tokens_details":{
            "text_tokens":usage["completion_tokens_details"]["text_tokens"],
            "image_tokens":usage["completion_tokens_details"]["image_tokens"],
            "reasoning_tokens":usage["completion_tokens_details"]["reasoning_tokens"],
        },
    });
    let response_value = json!({
        "id":response_id,
        "object":"response",
        "created_at":created,
        "status":"completed",
        "error":null,
        "incomplete_details":null,
        "model":model,
        "output":[search_item, message_item],
        "parallel_tool_calls":false,
        "usage":usage,
    });
    if !object
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(Json(response_value).into_response());
    }
    let response_id = response_value["id"].clone();
    let created = response_value["created_at"].clone();
    let model = response_value["model"].clone();
    let output = response_value["output"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let mut events = vec![json!({
        "type":"response.created",
        "response":{
            "id":response_id,
            "object":"response",
            "created_at":created,
            "status":"in_progress",
            "error":null,
            "incomplete_details":null,
            "model":model,
            "output":[],
            "parallel_tool_calls":false
        }
    })];
    events.push(
        json!({"type":"response.output_item.added","output_index":0,"item":{
            "id":output[0]["id"],"type":"web_search_call","status":"in_progress",
            "action":{"type":"search","query":query,"queries":[query]}
        }}),
    );
    events.push(json!({"type":"response.web_search_call.in_progress","output_index":0,"item_id":output[0]["id"]}));
    events.push(json!({"type":"response.web_search_call.searching","output_index":0,"item_id":output[0]["id"]}));
    events.push(json!({"type":"response.web_search_call.completed","output_index":0,"item_id":output[0]["id"]}));
    events.push(json!({"type":"response.output_item.done","output_index":0,"item":output[0]}));
    events.push(json!({"type":"response.output_item.added","output_index":1,"item":{
        "id":output[1]["id"],"type":"message","status":"in_progress","role":"assistant",
        "content":[{"type":"output_text","text":"","annotations":output[1]["content"][0]["annotations"]}]
    }}));
    if !text.is_empty() {
        events.push(json!({"type":"response.output_text.delta","item_id":output[1]["id"],"output_index":1,"content_index":0,"delta":text}));
    }
    events.push(json!({"type":"response.output_text.done","item_id":output[1]["id"],"output_index":1,"content_index":0,"text":text}));
    events.push(json!({"type":"response.output_item.done","output_index":1,"item":output[1]}));
    events.push(json!({"type":"response.completed","response":response_value}));
    let mut body = String::from(": stream-open\n\n");
    body.push_str(
        &events
            .into_iter()
            .map(|event| {
                serde_json::to_string(&event)
                    .map(|event| format!("data: {event}\n\n"))
                    .map_err(|_| ApiError::upstream())
            })
            .collect::<Result<String, _>>()?,
    );
    body.push_str("data: [DONE]\n\n");
    let mut response = Response::new(Body::from(body));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    Ok(response)
}

type ChatResponseInputStream =
    Pin<Box<dyn Stream<Item = Result<Bytes, io::Error>> + Send + 'static>>;

fn response_stream_from_chat(
    response: Response,
    model: String,
    deadline: Instant,
    text_prompt_tokens: usize,
    image_tokens: usize,
) -> Response {
    let input = response
        .into_body()
        .into_data_stream()
        .map(|chunk| chunk.map_err(|_| io::Error::other("chat response stream failed")));
    struct StreamState {
        input: ChatResponseInputStream,
        buffer: Vec<u8>,
        pending: VecDeque<Bytes>,
        model: String,
        response_id: String,
        item_id: String,
        created: i64,
        text: String,
        terminal: bool,
        total: usize,
        text_prompt_tokens: usize,
        image_tokens: usize,
    }
    let response_id = format!("resp_{}", native_message_id());
    let item_id = format!("msg_{}", native_message_id());
    let created = native_created();
    let mut pending = VecDeque::from([Bytes::from_static(b": stream-open\n\n")]);
    pending.push_back(Bytes::from(format!(
        "data: {}\n\n",
        serde_json::to_string(&json!({
            "type": "response.created",
            "response": {
                "id": response_id.clone(),
                "object": "response",
                "created_at": created,
                "status": "in_progress",
                "error": Value::Null,
                "incomplete_details": Value::Null,
                "model": model.clone(),
                "output": [],
                "parallel_tool_calls": false
            }
        }))
        .unwrap_or_default()
    )));
    pending.push_back(Bytes::from(format!(
        "data: {}\n\n",
        serde_json::to_string(&json!({
            "type": "response.output_item.added",
            "output_index": 0,
            "item": {
                "id": item_id.clone(),
                "type": "message",
                "status": "in_progress",
                "role": "assistant",
                "content": [{"type": "output_text", "text": "", "annotations": []}]
            }
        }))
        .unwrap_or_default()
    )));
    let state = StreamState {
        input: Box::pin(input),
        buffer: Vec::new(),
        pending,
        model,
        response_id,
        item_id,
        created,
        text_prompt_tokens,
        image_tokens,
        text: String::new(),
        terminal: false,
        total: 0,
    };
    let stream = stream::unfold(state, move |mut state| async move {
        loop {
            if let Some(frame) = state.pending.pop_front() {
                return Some((Ok(frame), state));
            }
            if state.terminal {
                return None;
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                state.terminal = true;
                return Some((Err(io::Error::other("response stream timed out")), state));
            }
            let next = tokio::time::timeout(remaining, state.input.next()).await;
            let chunk = match next {
                Ok(Some(Ok(chunk))) => chunk,
                Ok(Some(Err(error))) => {
                    state.terminal = true;
                    return Some((Err(io::Error::other(error.to_string())), state));
                }
                Err(_) => {
                    state.terminal = true;
                    return Some((
                        Err(io::Error::other("chat response stream timed out")),
                        state,
                    ));
                }
                Ok(None) => {
                    let item = json!({
                        "id": state.item_id.clone(),
                        "type": "message",
                        "status": "completed",
                        "role": "assistant",
                        "content": [{"type": "output_text", "text": state.text.clone(), "annotations": []}]
                    });
                    state.pending.push_back(Bytes::from(format!(
                        "data: {}\n\n",
                        serde_json::to_string(&json!({
                            "type": "response.output_text.done",
                            "item_id": state.item_id.clone(),
                            "output_index": 0,
                            "content_index": 0,
                            "text": state.text.clone(),
                        }))
                        .unwrap_or_default()
                    )));
                    state.pending.push_back(Bytes::from(format!(
                        "data: {}\n\n",
                        serde_json::to_string(&json!({
                            "type": "response.output_item.done",
                            "output_index": 0,
                            "item": item.clone(),
                        }))
                        .unwrap_or_default()
                    )));
                    let usage = match native_usage_for_prompt_tokens_with_images(
                        &state.model,
                        state.text_prompt_tokens,
                        state.image_tokens,
                        &state.text,
                    ) {
                        Ok(usage) => native_responses_usage_from_chat(&usage),
                        Err(_) => {
                            state.terminal = true;
                            return Some((
                                Err(io::Error::other("Responses usage calculation failed")),
                                state,
                            ));
                        }
                    };
                    state.pending.push_back(Bytes::from(format!(
                        "data: {}\n\n",
                        serde_json::to_string(&json!({
                            "type": "response.completed",
                            "response": {
                                "id": state.response_id.clone(),
                                "object": "response",
                                "created_at": state.created,
                                "status": "completed",
                                "error": Value::Null,
                                "incomplete_details": Value::Null,
                                "model": state.model.clone(),
                                "output": [item],
                                "usage": usage,
                                "parallel_tool_calls": false
                            }
                        }))
                        .unwrap_or_default()
                    )));
                    state
                        .pending
                        .push_back(Bytes::from_static(b"data: [DONE]\n\n"));
                    state.terminal = true;
                    continue;
                }
            };
            state.buffer.extend_from_slice(&chunk);
            while let Some((position, delimiter_length)) = sse_delimiter(&state.buffer) {
                let event = state.buffer.drain(..position).collect::<Vec<_>>();
                state.buffer.drain(..delimiter_length);
                let data = match codex_sse_data(&event) {
                    Ok(Some(data)) => data,
                    Ok(None) => continue,
                    Err(error) => {
                        state.terminal = true;
                        return Some((Err(error), state));
                    }
                };
                if data == "[DONE]" {
                    state.input = Box::pin(stream::empty());
                    continue;
                }
                let value: Value = match serde_json::from_str(&data) {
                    Ok(value) => value,
                    Err(_) => continue,
                };
                let delta = value
                    .get("choices")
                    .and_then(Value::as_array)
                    .and_then(|choices| choices.first())
                    .and_then(Value::as_object)
                    .and_then(|choice| choice.get("delta"))
                    .and_then(Value::as_object)
                    .and_then(|delta| delta.get("content"))
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                if !delta.is_empty() {
                    state.text.push_str(delta);
                    state.pending.push_back(Bytes::from(format!(
                        "data: {}\n\n",
                        serde_json::to_string(&json!({
                            "type": "response.output_text.delta",
                            "item_id": state.item_id.clone(),
                            "output_index": 0,
                            "content_index": 0,
                            "delta": delta,
                        }))
                        .unwrap_or_default()
                    )));
                }
            }
            if !state.pending.is_empty() {
                continue;
            }
        }
    });
    let stream = stream.map(|item| match item {
        Ok(bytes) => Ok::<Bytes, io::Error>(bytes),
        Err(_) => Ok::<Bytes, io::Error>(openai_stream_error_frame()),
    });
    let mut output = Response::new(Body::from_stream(stream));
    output.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    output
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    output
}

async fn native_normalize_chat_image_sources(
    state: &AppState,
    object: &mut Map<String, Value>,
) -> Result<(), ApiError> {
    let message_count = object
        .get("messages")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    for index in 0..message_count {
        let refs = object
            .get("messages")
            .and_then(Value::as_array)
            .and_then(|messages| messages.get(index))
            .and_then(|message| {
                message
                    .get("role")
                    .and_then(Value::as_str)
                    .map(|role| (role, message))
            })
            .filter(|(role, _)| *role == "user")
            .and_then(|(_, message)| message.get("content"))
            .and_then(Value::as_array)
            .map(|parts| {
                parts
                    .iter()
                    .enumerate()
                    .filter_map(|(part_index, part)| {
                        let part = part.as_object()?;
                        (part.get("type").and_then(Value::as_str) == Some("image_url"))
                            .then(|| {
                                native_image_url_reference(part).map(|value| (part_index, value))
                            })
                            .flatten()
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        for (part_index, reference) in refs {
            let source = native_chat_image_source(state, reference).await?;
            if let NativeImageSource::Text(value) = source
                && let Some(part) = object
                    .get_mut("messages")
                    .and_then(Value::as_array_mut)
                    .and_then(|messages| messages.get_mut(index))
                    .and_then(|message| message.get_mut("content"))
                    .and_then(Value::as_array_mut)
                    .and_then(|parts| parts.get_mut(part_index))
                    .and_then(Value::as_object_mut)
            {
                part.insert("image_url".to_owned(), Value::String(value));
            }
        }
    }
    Ok(())
}

async fn native_responses_via_web_chat(
    state: AppState,
    headers: HeaderMap,
    object: Map<String, Value>,
    cache_model: Value,
    timeout: Duration,
) -> Result<Response, ApiError> {
    let model = object
        .get("model")
        .and_then(Value::as_str)
        .ok_or_else(ApiError::invalid_request)?
        .to_owned();
    let mut chat_object = responses_text_to_chat_object(&object)?;
    ensure_responses_chat_route_messages(&mut chat_object);
    native_normalize_chat_image_sources(&state, &mut chat_object).await?;
    let mut usage_chat_object = chat_object.clone();
    apply_global_system_prompt_to_chat(&state, &mut usage_chat_object);
    let prompt_usage = native_usage(&usage_chat_object, "")?;
    let text_prompt_tokens = prompt_usage["prompt_tokens_details"]["text_tokens"]
        .as_u64()
        .and_then(|value| usize::try_from(value).ok())
        .ok_or_else(ApiError::upstream)?;
    let image_tokens = prompt_usage["prompt_tokens_details"]["image_tokens"]
        .as_u64()
        .and_then(|value| usize::try_from(value).ok())
        .ok_or_else(ApiError::upstream)?;
    let body =
        serde_json::to_vec(&Value::Object(chat_object)).map_err(|_| ApiError::invalid_request())?;
    let mut cache_body = object.clone();
    cache_body.insert("model".to_owned(), cache_model);
    let routed = chat_completions_authenticated_with_timeout(
        State(state),
        headers,
        Body::from(body),
        timeout,
        true,
        Some(cache_body),
    )
    .await?;
    if object
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(response_stream_from_chat(
            routed,
            model,
            Instant::now() + timeout,
            text_prompt_tokens,
            image_tokens,
        ));
    }
    let body = to_bytes(routed.into_body(), MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::upstream())?;
    let value: Value = serde_json::from_slice(&body).map_err(|_| ApiError::upstream())?;
    Ok(Json(response_from_chat_value(&value, &model)?).into_response())
}

async fn messages(State(state): State<AppState>, headers: HeaderMap, body: Body) -> Response {
    let mut auth_headers = headers.clone();
    let bearer = match headers
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| {
            headers
                .get("x-api-key")
                .and_then(|value| value.to_str().ok())
                .filter(|value| !value.is_empty())
                .map(|value| format!("Bearer {value}"))
        }) {
        Some(value) => value,
        None => return ApiError::unauthorized().into_anthropic_response(),
    };
    let auth_value = match HeaderValue::from_str(&bearer) {
        Ok(value) => value,
        Err(_) => return ApiError::unauthorized().into_anthropic_response(),
    };
    auth_headers.insert(header::AUTHORIZATION, auth_value);
    if let Err(error) = authenticated(&auth_headers, &state).await {
        return error.into_anthropic_response();
    }
    let started = Instant::now();
    let log_state = state.clone();
    let log_identity = request_log_identity(&log_state, &auth_headers);
    let (body, request_model, request_text, request_shape) =
        match to_bytes(body, MAX_REQUEST_BODY_BYTES).await {
            Ok(bytes) => {
                let request_model = request_model_for_log(&bytes);
                let (request_text, request_shape) =
                    request_log_context(&bytes, &["system", "messages", "tools"], &[]);
                (
                    Body::from(bytes),
                    request_model,
                    request_text,
                    request_shape,
                )
            }
            Err(_) => {
                return ApiError::validation().into_anthropic_response();
            }
        };
    let result = messages_inner(State(state), auth_headers, body).await;
    match &result {
        Ok(_) => append_api_call_log_with_context_and_identity(
            &log_state,
            "/v1/messages",
            &request_model,
            "Messages",
            started,
            "success",
            request_text.as_deref(),
            request_shape.as_ref(),
            None,
            log_identity.as_ref(),
        ),
        Err(error) => append_api_call_log_with_context_and_identity(
            &log_state,
            "/v1/messages",
            &request_model,
            "Messages",
            started,
            "failed",
            request_text.as_deref(),
            request_shape.as_ref(),
            Some(error.code()),
            log_identity.as_ref(),
        ),
    }
    match result {
        Ok(response) => response,
        Err(error) => error.into_anthropic_response(),
    }
}

async fn messages_inner(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, ApiError> {
    let bytes = to_bytes(body, MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::validation())?;
    let payload = match serde_json::from_slice::<Value>(&bytes) {
        Ok(value) => value,
        Err(error) => {
            let line_offset = bytes
                .split(|byte| *byte == b'\n')
                .take(error.line().saturating_sub(1))
                .map(|line| line.len().saturating_add(1))
                .sum::<usize>();
            let position = line_offset.saturating_add(error.column().saturating_sub(1));
            return Err(ApiError::validation_message(format!(
                "{position}: JSON decode error"
            )));
        }
    };
    let mut request = validate_message_request(payload)?;
    let content = Value::String(request_text_fields(
        &Value::Object(request.clone()),
        &["system", "messages", "tools"],
    ));
    reject_sensitive_words(&state, &content)?;
    review_request_content(&state, &content).await?;
    resolve_anthropic_remote_image_urls(&state, &mut request).await?;
    let model = request
        .get("model")
        .and_then(Value::as_str)
        .ok_or_else(ApiError::invalid_request)?
        .to_owned();
    let wants_stream = request
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let tools_enabled = anthropic_has_tools(&request);
    let input_tokens =
        anthropic_input_token_count(&request, configured_global_system_prompt(&state).as_deref())?;
    if state.config.upstream_protocol == UpstreamProtocol::ChatGpt {
        let mut payload = to_chat_payload(&request)?;
        if let Some(payload_object) = payload.as_object_mut() {
            apply_global_system_prompt_to_chat(&state, payload_object);
            if payload_object
                .get("messages")
                .and_then(Value::as_array)
                .is_none_or(|messages| messages.is_empty())
            {
                payload_object.insert("messages".to_owned(), json!([{"role":"user","content":""}]));
            }
        }
        let internal_body =
            serde_json::to_vec(&payload).map_err(|_| ApiError::invalid_request())?;
        let routed = chat_completions_authenticated_with_timeout(
            State(state.clone()),
            headers,
            Body::from(internal_body),
            NATIVE_UPSTREAM_TIMEOUT,
            true,
            Some(Map::from_iter([(
                CHAT_CACHE_BYPASS_MARKER.to_owned(),
                Value::Bool(true),
            )])),
        )
        .await?;
        if wants_stream {
            return Ok(anthropic_stream_body_response_with_options(
                routed.into_body(),
                model,
                Instant::now() + NATIVE_UPSTREAM_TIMEOUT,
                tools_enabled,
                input_tokens,
            ));
        }
        let body = to_bytes(routed.into_body(), MAX_REQUEST_BODY_BYTES)
            .await
            .map_err(|_| ApiError::upstream())?;
        return Ok((
            StatusCode::OK,
            [(header::CONTENT_TYPE, "application/json")],
            Json(from_chat_response(
                &body,
                &model,
                tools_enabled,
                input_tokens,
            )?),
        )
            .into_response());
    }
    if state.config.upstream_protocol != UpstreamProtocol::OpenAi {
        return Err(ApiError::unavailable());
    }
    let mut payload = to_chat_payload(&request)?;
    if let Some(object) = payload.as_object_mut() {
        apply_global_system_prompt_to_chat(&state, object);
    }
    let base_url = state
        .config
        .upstream_base_url
        .as_deref()
        .ok_or_else(ApiError::unavailable)?;
    let url = format!("{}/v1/chat/completions", base_url.trim_end_matches('/'));
    let mut upstream_request = legacy_global_proxy_client(&state).post(url).json(&payload);
    if let Some(auth) = state.config.upstream_auth.as_deref() {
        upstream_request = upstream_request.header(header::AUTHORIZATION, auth);
    }
    let deadline = Instant::now() + NATIVE_UPSTREAM_TIMEOUT;
    let upstream = tokio::time::timeout_at(
        tokio::time::Instant::from_std(deadline),
        upstream_request.send(),
    )
    .await
    .map_err(|_| ApiError::upstream())?
    .map_err(|_| ApiError::upstream())?;
    if !upstream.status().is_success() || upstream_declares_oversize(&upstream) {
        return Err(ApiError::upstream());
    }
    if wants_stream {
        return Ok(anthropic_stream_response_with_options(
            upstream,
            model,
            deadline,
            tools_enabled,
            input_tokens,
        ));
    }
    let body = tokio::time::timeout_at(
        tokio::time::Instant::from_std(deadline),
        bounded_response_body(upstream),
    )
    .await
    .map_err(|_| ApiError::upstream())??;
    Ok((
        StatusCode::OK,
        [(header::CONTENT_TYPE, "application/json")],
        Json(from_chat_response(
            &body,
            &model,
            tools_enabled,
            input_tokens,
        )?),
    )
        .into_response())
}

async fn resolve_anthropic_remote_image_urls(
    state: &AppState,
    request: &mut Map<String, Value>,
) -> Result<(), ApiError> {
    let Some(messages) = request.get_mut("messages").and_then(Value::as_array_mut) else {
        return Ok(());
    };
    for message in messages {
        if message.get("role").and_then(Value::as_str) != Some("user") {
            continue;
        }
        let Some(content) = message.get_mut("content").and_then(Value::as_array_mut) else {
            continue;
        };
        for part in content {
            let Some(object) = part.as_object_mut() else {
                continue;
            };
            let Some(image_field) = ["image_url", "url"].into_iter().find(|field| {
                object
                    .get(*field)
                    .and_then(|value| {
                        value.as_str().or_else(|| {
                            value
                                .as_object()
                                .and_then(|image| {
                                    image
                                        .get("url")
                                        .filter(|value| {
                                            account_pool::account_value_truthy(Some(value))
                                        })
                                        .or_else(|| {
                                            image.get("image_url").filter(|value| {
                                                account_pool::account_value_truthy(Some(value))
                                            })
                                        })
                                })
                                .and_then(Value::as_str)
                        })
                    })
                    .is_some_and(|url| !url.trim().is_empty())
            }) else {
                continue;
            };
            if !object
                .get("type")
                .and_then(Value::as_str)
                .map(str::trim)
                .is_some_and(|kind| matches!(kind, "image" | "image_url" | "input_image"))
            {
                continue;
            }
            let Some(value) = object.get(image_field) else {
                continue;
            };
            let Some(url) = value.as_str().or_else(|| {
                value
                    .as_object()
                    .and_then(|image| {
                        image
                            .get("url")
                            .filter(|value| account_pool::account_value_truthy(Some(value)))
                            .or_else(|| {
                                image
                                    .get("image_url")
                                    .filter(|value| account_pool::account_value_truthy(Some(value)))
                            })
                    })
                    .and_then(Value::as_str)
            }) else {
                continue;
            };
            if !url.starts_with("http://") && !url.starts_with("https://") {
                continue;
            }
            let parsed = url::Url::parse(url).map_err(|_| ApiError::invalid_request())?;
            if !matches!(parsed.scheme(), "http" | "https") || parsed.host_str().is_none() {
                return Err(ApiError::invalid_request());
            }
            let data_url = native_download_image_reference_with_limits(
                state,
                &parsed,
                10 * 1024 * 1024,
                Duration::from_secs(20),
                "chatgpt2api vision fetcher",
            )
            .await?;
            match object.get_mut(image_field) {
                Some(Value::String(value)) => *value = data_url,
                Some(Value::Object(image)) => {
                    let key = if image
                        .get("url")
                        .filter(|value| account_pool::account_value_truthy(Some(value)))
                        .is_some()
                    {
                        "url"
                    } else {
                        "image_url"
                    };
                    image.insert(key.to_owned(), Value::String(data_url));
                }
                _ => {}
            }
        }
    }
    Ok(())
}

fn native_codex_responses_stream_response(
    response: reqwest::Response,
    lease: AccountLease,
    deadline: Instant,
) -> Response {
    type UpstreamStream = Pin<Box<dyn Stream<Item = Result<Bytes, reqwest::Error>> + Send>>;
    struct State {
        input: UpstreamStream,
        buffer: Vec<u8>,
        pending: VecDeque<Bytes>,
        total: usize,
        terminal: bool,
        lease: Option<AccountLease>,
    }
    let state = State {
        input: Box::pin(response.bytes_stream()),
        buffer: Vec::new(),
        pending: VecDeque::from([Bytes::from_static(b": stream-open\n\n")]),
        total: 0,
        terminal: false,
        lease: Some(lease),
    };
    let stream = stream::unfold(state, move |mut state| async move {
        loop {
            if let Some(frame) = state.pending.pop_front() {
                return Some((Ok(frame), state));
            }
            if state.terminal {
                drop(state.lease.take());
                return None;
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                drop(state.lease.take());
                state.terminal = true;
                return Some((
                    Err(io::Error::other("Codex Responses stream timed out")),
                    state,
                ));
            }
            let next = tokio::time::timeout(remaining, state.input.next()).await;
            let chunk = match next {
                Ok(Some(Ok(chunk))) => chunk,
                Ok(Some(Err(_))) | Err(_) => {
                    drop(state.lease.take());
                    state.terminal = true;
                    return Some((
                        Err(io::Error::other("Codex Responses stream failed")),
                        state,
                    ));
                }
                Ok(None) => {
                    drop(state.lease.take());
                    state.terminal = true;
                    let error = if state.buffer.iter().all(u8::is_ascii_whitespace) {
                        "Codex Responses stream ended without completion"
                    } else {
                        "Codex Responses stream ended with an incomplete SSE event"
                    };
                    return Some((Err(io::Error::other(error)), state));
                }
            };
            state.total = match state.total.checked_add(chunk.len()) {
                Some(total) if total <= MAX_UPSTREAM_BODY_BYTES => total,
                _ => {
                    drop(state.lease.take());
                    state.terminal = true;
                    return Some((
                        Err(io::Error::other("Codex Responses body exceeded limit")),
                        state,
                    ));
                }
            };
            state.buffer.extend_from_slice(&chunk);
            while let Some((position, delimiter_length)) = sse_delimiter(&state.buffer) {
                let event = state.buffer.drain(..position).collect::<Vec<_>>();
                state.buffer.drain(..delimiter_length);
                let data = match codex_sse_data(&event) {
                    Ok(Some(data)) => data,
                    Ok(None) => continue,
                    Err(error) => {
                        drop(state.lease.take());
                        state.terminal = true;
                        return Some((Err(error), state));
                    }
                };
                if data == "[DONE]" {
                    continue;
                }
                if state.terminal {
                    drop(state.lease.take());
                    return Some((
                        Err(io::Error::other(
                            "Codex Responses stream emitted an event after terminal",
                        )),
                        state,
                    ));
                }
                let value: Value = match serde_json::from_str(&data) {
                    Ok(value) => value,
                    Err(_) => {
                        drop(state.lease.take());
                        state.terminal = true;
                        return Some((Err(io::Error::other("malformed Codex event")), state));
                    }
                };
                if !codex_response_event_is_known(&value) {
                    continue;
                }
                let event_type = match validate_codex_response_event(&value) {
                    Ok(event_type) => event_type,
                    Err(error) => {
                        drop(state.lease.take());
                        state.terminal = true;
                        return Some((Err(error), state));
                    }
                };
                let public = match project_codex_response_event(&value) {
                    Ok(public) => public,
                    Err(error) => {
                        drop(state.lease.take());
                        state.terminal = true;
                        return Some((Err(error), state));
                    }
                };
                if let Some(public) = public {
                    let mut frame = b"data: ".to_vec();
                    let serialized = match serde_json::to_vec(&public) {
                        Ok(serialized) => serialized,
                        Err(_) => {
                            drop(state.lease.take());
                            state.terminal = true;
                            return Some((
                                Err(io::Error::other("Codex event projection failed")),
                                state,
                            ));
                        }
                    };
                    frame.extend(serialized);
                    frame.extend_from_slice(b"\n\n");
                    state.pending.push_back(Bytes::from(frame));
                }
                if matches!(
                    event_type,
                    "response.completed" | "response.incomplete" | "response.failed" | "error"
                ) {
                    state
                        .pending
                        .push_back(Bytes::from_static(b"data: [DONE]\n\n"));
                    state.terminal = true;
                }
            }
            if !state.pending.is_empty() || state.terminal {
                continue;
            }
        }
    });
    let stream = stream.map(|item| match item {
        Ok(bytes) => Ok::<Bytes, io::Error>(bytes),
        Err(_) => Ok::<Bytes, io::Error>(openai_stream_error_frame()),
    });
    let mut output = Response::new(Body::from_stream(stream));
    output.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    output
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    output
}

async fn acquire_native_codex_lease(
    state: &AppState,
    model: &str,
    excluded_tokens: &HashSet<String>,
) -> Option<AccountLease> {
    acquire_native_codex_lease_with_groups(state, model, excluded_tokens, None).await
}

async fn acquire_native_codex_lease_with_groups(
    state: &AppState,
    model: &str,
    excluded_tokens: &HashSet<String>,
    forced_groups: Option<&HashSet<String>>,
) -> Option<AccountLease> {
    let allowed_groups = forced_groups.cloned();
    state
        .account_store
        .acquire_excluding_with_type_and_source_filter(
            model,
            excluded_tokens,
            allowed_groups.as_ref(),
            Some("codex"),
        )
        .await
}

async fn responses_with_timeout(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
    upstream_timeout: Duration,
    policy_checked: bool,
) -> Result<Response, ApiError> {
    authenticated(&headers, &state).await?;
    responses_authenticated_with_timeout(
        State(state),
        headers,
        body,
        upstream_timeout,
        policy_checked,
    )
    .await
}

async fn responses_authenticated_with_timeout(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
    upstream_timeout: Duration,
    policy_checked: bool,
) -> Result<Response, ApiError> {
    let bytes = to_bytes(body, MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::validation())?;
    let payload: Value = serde_json::from_slice(&bytes).map_err(|_| ApiError::validation())?;
    let cache_model = payload.get("model").cloned().unwrap_or(Value::Null);
    let mut object = validate_responses_payload(payload)?;
    if !policy_checked {
        let content = Value::String(request_text_fields(
            &Value::Object(object.clone()),
            &["input", "instructions"],
        ));
        reject_sensitive_words(&state, &content)?;
        review_request_content(&state, &content).await?;
    }
    if state.config.upstream_protocol == UpstreamProtocol::ChatGpt {
        if native_response_image_tool(&object).is_some() {
            apply_global_system_prompt_to_responses(&state, &mut object);
            return native_responses_image_completion(state, object).await;
        }
        if native_response_has_web_search_tool(&object)
            && !native_response_has_unsupported_tools(&object)
        {
            return native_responses_web_search_completion(state, object, upstream_timeout).await;
        }
        return native_responses_via_web_chat(
            state,
            headers,
            object,
            cache_model,
            upstream_timeout,
        )
        .await;
    }
    if state.config.upstream_protocol != UpstreamProtocol::OpenAi {
        return Err(ApiError::unavailable());
    }
    apply_global_system_prompt_to_responses(&state, &mut object);
    let Some(base_url) = state.config.upstream_base_url.as_deref() else {
        return Err(ApiError::unavailable());
    };
    let route_deadline = Instant::now() + upstream_timeout;
    let url = format!("{}/v1/responses", base_url.trim_end_matches('/'));
    let mut request = legacy_global_proxy_client(&state).post(url).json(&object);
    if let Some(auth) = state.config.upstream_auth.as_deref() {
        request = request.header(header::AUTHORIZATION, auth);
    }
    let upstream = tokio::time::timeout_at(
        tokio::time::Instant::from_std(route_deadline),
        request.send(),
    )
    .await
    .map_err(|_| ApiError::upstream())?
    .map_err(|_| ApiError::upstream())?;
    if !upstream.status().is_success() || upstream_declares_oversize(&upstream) {
        return Err(ApiError::upstream());
    }
    if object
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(stream_response_with_timeout(upstream, upstream_timeout));
    }
    let body = tokio::time::timeout_at(
        tokio::time::Instant::from_std(route_deadline),
        bounded_response_body(upstream),
    )
    .await
    .map_err(|_| ApiError::upstream())??;
    let value: Value = serde_json::from_slice(&body).map_err(|_| ApiError::upstream())?;
    if !value.is_object() {
        return Err(ApiError::upstream());
    }
    Ok((
        StatusCode::OK,
        [(header::CONTENT_TYPE, "application/json")],
        Json(value),
    )
        .into_response())
}

async fn native_responses_with_timeout(
    state: AppState,
    object: Map<String, Value>,
    upstream_timeout: Duration,
) -> Result<Response, ApiError> {
    native_responses_with_timeout_and_groups(state, object, upstream_timeout, None).await
}

async fn native_responses_with_timeout_and_groups(
    state: AppState,
    object: Map<String, Value>,
    upstream_timeout: Duration,
    forced_groups: Option<HashSet<String>>,
) -> Result<Response, ApiError> {
    let payload = native_codex_responses_payload(&object)?;
    let model = object
        .get("model")
        .and_then(Value::as_str)
        .ok_or_else(ApiError::invalid_request)?
        .to_owned();
    let base_url = state
        .config
        .upstream_base_url
        .as_deref()
        .ok_or_else(ApiError::unavailable)?;
    let route_deadline = Instant::now() + upstream_timeout;
    let mut attempted_tokens = HashSet::new();
    let mut lease = tokio::time::timeout_at(
        tokio::time::Instant::from_std(route_deadline),
        acquire_native_codex_lease_with_groups(
            &state,
            &model,
            &attempted_tokens,
            forced_groups.as_ref(),
        ),
    )
    .await
    .map_err(|_| ApiError::upstream())?
    .ok_or_else(ApiError::unavailable)?;
    let codex_client_version = state.account_type_catalog.codex_client_version();
    let upstream = loop {
        let remaining = route_deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            drop(lease);
            return Err(ApiError::upstream());
        }
        attempted_tokens.insert(lease.token().to_owned());
        let client = upstream_client_for_lease(&state, &lease, false);
        match native_codex_response_attempt(
            &state,
            &client,
            &lease,
            base_url,
            &payload,
            codex_client_version.as_deref(),
            remaining,
        )
        .await
        {
            Ok(response) => break response,
            Err((error, retryable)) if retryable => {
                drop(lease);
                let acquired = match tokio::time::timeout_at(
                    tokio::time::Instant::from_std(route_deadline),
                    acquire_native_codex_lease_with_groups(
                        &state,
                        &model,
                        &attempted_tokens,
                        forced_groups.as_ref(),
                    ),
                )
                .await
                {
                    Ok(acquired) => acquired,
                    Err(_) => return Err(error),
                };
                lease = match acquired {
                    Some(lease) => lease,
                    None => return Err(error),
                };
            }
            Err((error, _)) => {
                if error.code() == "invalid_api_key" {
                    let token = lease.token().to_owned();
                    let config = fs::read(state.config_path.as_ref())
                        .ok()
                        .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
                        .unwrap_or_else(|| json!({}));
                    let remove = settings_bool(config.get("auto_remove_invalid_accounts"), false);
                    record_invalid_token_with_log(&state, &token, "invalid_token", remove).await;
                }
                drop(lease);
                return Err(error);
            }
        }
    };
    if object
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(native_codex_responses_stream_response(
            upstream,
            lease,
            route_deadline,
        ));
    }
    let body = tokio::time::timeout_at(
        tokio::time::Instant::from_std(route_deadline),
        bounded_response_body(upstream),
    )
    .await
    .map_err(|_| ApiError::upstream())??;
    let response = native_codex_responses_json(&body, &model)?;
    let used_token = lease.token().to_owned();
    if !state.account_store.mark_text_used(&used_token).await {
        AccountStore::note_usage_mark_failure();
    }
    drop(lease);
    Ok((
        StatusCode::OK,
        [(header::CONTENT_TYPE, "application/json")],
        Json(response),
    )
        .into_response())
}

fn native_image_adapter_text_error(error: &ApiError) -> bool {
    matches!(error.code(), "upstream_text_reply" | "image_message")
}

fn native_chat_image_text_response(model: &str, text: &str, usage: Value) -> Response {
    Json(json!({
        "id": native_completion_id(),
        "object": "chat.completion",
        "created": native_created(),
        "model": model,
        "choices": [{
            "index": 0,
            "message": {"role": "assistant", "content": text},
            "finish_reason": "stop"
        }],
        "usage": native_chat_image_usage(&usage),
    }))
    .into_response()
}

fn native_chat_image_text_stream_completion(model: &str, text: &str) -> Response {
    let completion_id = native_completion_id();
    let created = native_created();
    let first = json!({
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model,
        "choices": [{"index":0,"delta":{"role":"assistant","content":text},"finish_reason":null}]
    });
    let finish = json!({
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model,
        "choices": [{"index":0,"delta":{},"finish_reason":"stop"}]
    });
    let body = format!(
        "data: {}\n\ndata: {}\n\ndata: [DONE]\n\n",
        serde_json::to_string(&first).unwrap_or_default(),
        serde_json::to_string(&finish).unwrap_or_default(),
    );
    let mut response = Response::new(Body::from(body));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    response
}

fn native_responses_image_text_completion(
    model: &str,
    text: &str,
    stream: bool,
    usage: Value,
) -> Result<Response, ApiError> {
    let response_id = format!("resp_{}", native_message_id());
    let item_id = format!("msg_{}", native_message_id());
    let created = native_created();
    let item = json!({
        "id": item_id,
        "type": "message",
        "status": "completed",
        "role": "assistant",
        "content": [{"type":"output_text","text":text,"annotations":[]}]
    });
    let response_value = json!({
        "id": response_id,
        "object": "response",
        "created_at": created,
        "status": "completed",
        "error": Value::Null,
        "incomplete_details": Value::Null,
        "model": model,
        "output": [item],
        "parallel_tool_calls": false,
        "usage": usage,
    });
    if !stream {
        return Ok(Json(response_value).into_response());
    }
    let output_item = response_value["output"][0].clone();
    let events = vec![
        json!({
            "type":"response.created",
            "response":{
                "id":response_value["id"],"object":"response","created_at":created,
                "status":"in_progress","error":null,"incomplete_details":null,
                "model":model,"output":[],"parallel_tool_calls":false
            }
        }),
        json!({"type":"response.output_text.delta","item_id":output_item["id"],"output_index":0,"content_index":0,"delta":text}),
        json!({"type":"response.output_text.done","item_id":output_item["id"],"output_index":0,"content_index":0,"text":text}),
        json!({"type":"response.output_item.done","output_index":0,"item":output_item}),
        json!({"type":"response.completed","response":response_value}),
    ];
    let mut body = String::from(": stream-open\n\n");
    body.push_str(
        &events
            .into_iter()
            .map(|event| {
                serde_json::to_string(&event)
                    .map(|event| format!("data: {event}\n\n"))
                    .map_err(|_| ApiError::upstream())
            })
            .collect::<Result<String, _>>()?,
    );
    body.push_str("data: [DONE]\n\n");
    let mut response = Response::new(Body::from(body));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    Ok(response)
}

fn native_chat_image_content(data: &[Value]) -> String {
    let mut parts = Vec::new();
    for (index, item) in data.iter().enumerate() {
        let Some(object) = item.as_object() else {
            continue;
        };
        if let Some(encoded) = object
            .get("b64_json")
            .filter(|value| account_pool::account_value_truthy(Some(value)))
            .map(protocol_anthropic::python_str)
            .map(|value| value.trim().to_owned())
            .filter(|value| !value.is_empty())
        {
            parts.push(format!(
                "![image_{}](data:image/png;base64,{encoded})",
                index + 1
            ));
        }
    }
    if parts.is_empty() {
        "Image generation completed.".to_owned()
    } else {
        parts.join("\n\n")
    }
}

fn native_chat_image_stream_completion(model: &str, body: &[u8]) -> Result<Response, ApiError> {
    let text = std::str::from_utf8(body).map_err(|_| ApiError::upstream())?;
    let completion_id = native_completion_id();
    let created = native_created();
    let mut frames = Vec::new();
    let mut sent_role = false;
    let mut sent_text = String::new();
    for event in text.split("\n\n") {
        let Some(data) = event
            .lines()
            .find_map(|line| {
                line.strip_prefix("data: ")
                    .or_else(|| line.strip_prefix("data:"))
            })
            .map(str::trim)
        else {
            continue;
        };
        if data == "[DONE]" {
            continue;
        }
        let value: Value = serde_json::from_str(data).map_err(|_| ApiError::upstream())?;
        let content = match value.get("object").and_then(Value::as_str) {
            Some("image.generation.chunk") => {
                let text = value
                    .get("progress_text")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_owned();
                sent_text.push_str(&text);
                text
            }
            Some("image.generation.message") => {
                let message = value
                    .get("message")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                if message.starts_with(&sent_text) {
                    message[sent_text.len()..].to_owned()
                } else {
                    message.to_owned()
                }
            }
            Some("image.generation.result") => value
                .get("data")
                .and_then(Value::as_array)
                .map(|data| native_chat_image_content(data))
                .unwrap_or_default(),
            _ => continue,
        };
        if content.is_empty() {
            continue;
        }
        let delta = if sent_role {
            json!({"content": content})
        } else {
            sent_role = true;
            json!({"role":"assistant","content":content})
        };
        frames.push(json!({
            "id":completion_id,
            "object":"chat.completion.chunk",
            "created":created,
            "model":model,
            "choices":[{"index":0,"delta":delta,"finish_reason":null}]
        }));
    }
    if !sent_role {
        frames.push(json!({
            "id":completion_id,
            "object":"chat.completion.chunk",
            "created":created,
            "model":model,
            "choices":[{"index":0,"delta":{"role":"assistant","content":""},"finish_reason":null}]
        }));
    }
    frames.push(json!({
        "id":completion_id,
        "object":"chat.completion.chunk",
        "created":created,
        "model":model,
        "choices":[{"index":0,"delta":{},"finish_reason":"stop"}]
    }));
    let mut output = String::from(": stream-open\n\n");
    output.push_str(
        &frames
            .into_iter()
            .map(|frame| {
                serde_json::to_string(&frame)
                    .map(|frame| format!("data: {frame}\n\n"))
                    .map_err(|_| ApiError::upstream())
            })
            .collect::<Result<String, _>>()?,
    );
    output.push_str("data: [DONE]\n\n");
    let mut response = Response::new(Body::from(output));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    Ok(response)
}

async fn native_chat_image_completion(
    state: AppState,
    object: Map<String, Value>,
) -> Result<Response, ApiError> {
    let requested_model = object
        .get("model")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("gpt-image-2")
        .to_owned();
    let stream_requested = object
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let mut request = native_chat_image_request_from_object(&state, &object).await?;
    request.base_url = configured_image_base_url(&state);
    request.stream = stream_requested;
    let fallback_usage = native_image_usage_for_request(&request, &[]);
    let image_response = if request.codex {
        native_codex_image_request_proxy(state, request, "images/generations").await
    } else {
        native_web_image_request_proxy(state, request, "images/generations").await
    };
    let image_response = match image_response {
        Ok(response) => response,
        Err(error) if native_image_adapter_text_error(&error) => {
            let text = error.message().to_owned();
            if stream_requested {
                return Ok(native_chat_image_text_stream_completion(
                    &requested_model,
                    &text,
                ));
            }
            return Ok(native_chat_image_text_response(
                &requested_model,
                &text,
                fallback_usage,
            ));
        }
        Err(error) => return Err(error),
    };
    if stream_requested {
        let body = to_bytes(image_response.into_body(), MAX_REQUEST_BODY_BYTES)
            .await
            .map_err(|_| ApiError::upstream())?;
        return native_chat_image_stream_completion(&requested_model, &body);
    }
    let body = to_bytes(image_response.into_body(), MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::upstream())?;
    let value: Value = serde_json::from_slice(&body).map_err(|_| ApiError::upstream())?;
    let data = value
        .get("data")
        .and_then(Value::as_array)
        .ok_or_else(ApiError::upstream)?;
    let content = native_chat_image_content(data);
    let response = json!({
        "id": native_completion_id(),
        "object": "chat.completion",
        "created": native_created(),
        "model": requested_model,
        "choices": [{
            "index": 0,
            "message": {"role": "assistant", "content": content},
            "finish_reason": "stop"
        }],
        "usage": native_chat_image_usage(value.get("usage").unwrap_or(&Value::Null)),
    });
    if !stream_requested {
        return Ok(Json(response).into_response());
    }
    let completion_id = response["id"].as_str().unwrap_or("chatcmpl-rust");
    let created = response["created"].as_i64().unwrap_or_else(native_created);
    let model = response["model"].as_str().unwrap_or("gpt-image-2");
    let role = json!({
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model,
        "choices": [{"index":0,"delta":{"role":"assistant","content":content},"finish_reason":null}]
    });
    let finish = json!({
        "id": completion_id,
        "object": "chat.completion.chunk",
        "created": created,
        "model": model,
        "choices": [{"index":0,"delta":{},"finish_reason":"stop"}]
    });
    let body = format!(
        ": stream-open\n\ndata: {}\n\ndata: {}\n\ndata: [DONE]\n\n",
        serde_json::to_string(&role).map_err(|_| ApiError::upstream())?,
        serde_json::to_string(&finish).map_err(|_| ApiError::upstream())?,
    );
    let mut response = Response::new(Body::from(body));
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    response
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    Ok(response)
}

async fn chat_completions_with_timeout(
    State(state): State<AppState>,
    headers: HeaderMap,
    body: Body,
    upstream_timeout: Duration,
    policy_checked: bool,
    cache_body: Option<Map<String, Value>>,
) -> Result<Response, ApiError> {
    authenticated(&headers, &state).await?;
    chat_completions_authenticated_with_timeout(
        State(state),
        headers,
        body,
        upstream_timeout,
        policy_checked,
        cache_body,
    )
    .await
}

async fn chat_completions_authenticated_with_timeout(
    State(state): State<AppState>,
    _headers: HeaderMap,
    body: Body,
    upstream_timeout: Duration,
    policy_checked: bool,
    cache_body: Option<Map<String, Value>>,
) -> Result<Response, ApiError> {
    let bytes = to_bytes(body, MAX_REQUEST_BODY_BYTES)
        .await
        .map_err(|_| ApiError::validation())?;
    let payload: Value = serde_json::from_slice(&bytes).map_err(|_| ApiError::validation())?;
    let mut cache_body =
        cache_body.unwrap_or_else(|| payload.as_object().cloned().unwrap_or_else(Map::new));
    let bypass_chat_cache = cache_body
        .remove(CHAT_CACHE_BYPASS_MARKER)
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    cache_body.entry("model".to_owned()).or_insert(Value::Null);
    let mut object = validate_chat_payload(payload)?;
    if !policy_checked {
        let content = Value::String(request_text_fields(
            &Value::Object(object.clone()),
            &["prompt", "messages"],
        ));
        reject_sensitive_words(&state, &content)?;
        review_request_content(&state, &content).await?;
    }
    apply_global_system_prompt_to_chat(&state, &mut object);
    let image_request = !bypass_chat_cache && native_chat_image_request(&object);
    if state.config.upstream_protocol == UpstreamProtocol::ChatGpt && image_request {
        return native_chat_image_completion(state, object).await;
    }
    let fallback_unsupported_tools = state.config.upstream_protocol == UpstreamProtocol::ChatGpt
        && (native_chat_has_unsupported_tools(&object)
            || native_response_has_unsupported_tools(&cache_body));
    if fallback_unsupported_tools {
        object.remove("tools");
        object.remove("tool_choice");
        object.remove("web_search_options");
    }
    if !image_request {
        normalize_chat_text_messages(&state, &mut object);
        if fallback_unsupported_tools
            && let Some(messages) = object.get_mut("messages").and_then(Value::as_array_mut)
        {
            messages.insert(
                0,
                json!({"role":"system","content":TOOL_UNAVAILABLE_SYSTEM_MESSAGE}),
            );
        }
    }
    if state.config.upstream_protocol == UpstreamProtocol::ChatGpt {
        if !fallback_unsupported_tools
            && native_chat_search_requested(&object)
            && !native_chat_search_has_unsupported_tools(&object)
        {
            return native_chat_search_completion(state, object).await;
        }
        let chat_payload = native_conversation_payload(&object)?;
        let model = object
            .get("model")
            .and_then(Value::as_str)
            .unwrap_or("auto")
            .to_owned();
        let stream_requested = object
            .get("stream")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let cache_key = (!image_request && !bypass_chat_cache)
            .then(|| {
                object
                    .get("messages")
                    .and_then(|messages| chat_cache_key(&cache_body, messages, stream_requested))
            })
            .flatten();
        let mut response_cache_owner = None;
        if !stream_requested && let Some(key) = cache_key.as_deref() {
            if let Some(cached) = chat_cache_read(&state, key) {
                return Ok(Json(cached).into_response());
            }
            if let Some(start) = chat_cache_begin_response(&state, key) {
                match start {
                    ChatCacheResponseStart::Cached(cached) => {
                        return Ok(Json(cached).into_response());
                    }
                    ChatCacheResponseStart::Owner(inflight) => {
                        response_cache_owner = Some(ChatCacheResponseOwner::new(
                            state.clone(),
                            key.to_owned(),
                            inflight,
                        ));
                    }
                    ChatCacheResponseStart::Waiter(inflight) => {
                        let cached = chat_cache_wait_response(&inflight).await?;
                        return Ok(Json(cached).into_response());
                    }
                }
            }
        }
        let mut stream_cache_owner = None;
        if stream_requested && let Some(key) = cache_key.as_deref() {
            if let Some(frames) = chat_cache_read_stream_frames(&state, key) {
                return Ok(response_from_cached_stream_frames(frames));
            }
            if let Some((inflight, owner)) = chat_cache_begin_stream(&state, key) {
                if owner {
                    stream_cache_owner = Some(ChatCacheStreamOwner::new(
                        state.clone(),
                        key.to_owned(),
                        inflight,
                    ));
                } else {
                    let frames = chat_cache_wait_stream(&inflight).await?;
                    return Ok(response_from_cached_stream_frames(frames));
                }
            } else if let Some(frames) = chat_cache_read_stream_frames(&state, key) {
                return Ok(response_from_cached_stream_frames(frames));
            }
        }
        let base_url = state
            .config
            .upstream_base_url
            .as_deref()
            .ok_or_else(ApiError::unavailable)?;
        // v1.7 selects active accounts independently of their cached model catalogs.
        let mut attempted_tokens = HashSet::new();
        let mut lease = state
            .account_store
            .acquire_excluding_with_type_and_source_filter(&model, &attempted_tokens, None, None)
            .await;
        let mut transient_failover_used = false;
        let upstream = loop {
            let token = lease.as_ref().map_or("", AccountLease::token);
            if !token.is_empty() {
                attempted_tokens.insert(token.to_owned());
            }
            let client = native_chat_upstream_client(&state, lease.as_ref());
            let attempt = native_conversation_attempt(
                &state,
                &client,
                lease.as_ref(),
                base_url,
                token,
                &chat_payload,
                &mut object,
            )
            .await;
            match attempt {
                Ok(upstream) => break upstream,
                Err((error, retryable)) => {
                    let invalid_token =
                        !token.is_empty() && error.message() == INVALID_UPSTREAM_TOKEN_MARKER;
                    let public_error = if error.message() == INVALID_UPSTREAM_TOKEN_MARKER {
                        ApiError::upstream()
                    } else {
                        error
                    };
                    if invalid_token {
                        let config = fs::read(state.config_path.as_ref())
                            .ok()
                            .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
                            .unwrap_or_else(|| json!({}));
                        let remove =
                            settings_bool(config.get("auto_remove_invalid_accounts"), false);
                        record_invalid_token_with_log(&state, token, "invalid_token", remove).await;
                    }
                    if invalid_token || (retryable && !transient_failover_used) {
                        transient_failover_used |= retryable;
                        drop(lease);
                        lease = state
                            .account_store
                            .acquire_excluding_with_type_and_source_filter(
                                &model,
                                &attempted_tokens,
                                None,
                                None,
                            )
                            .await;
                        if lease.is_none() {
                            return Err(public_error);
                        }
                    } else {
                        drop(lease);
                        return Err(public_error);
                    }
                }
            }
        };
        let history_text = native_assistant_history(&object);
        let history_messages = native_assistant_history_messages(&object);
        if object
            .get("stream")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            let include_usage = false;
            let prompt_tokens = 0;
            return native_stream_response(
                state.clone(),
                upstream,
                lease,
                model.to_owned(),
                include_usage,
                prompt_tokens,
                stream_cache_owner
                    .take()
                    .map(ChatCacheStreamOwner::into_parts),
                history_text.clone(),
                history_messages,
            )
            .await;
        }
        let body = tokio::time::timeout(NATIVE_UPSTREAM_TIMEOUT, bounded_response_body(upstream))
            .await
            .map_err(|_| ApiError::upstream())??;
        let text = native_completion_text_with_history(&body, &history_text)?;
        let usage = native_usage(&object, &text)?;
        let response = json!({
            "id": native_completion_id(),
            "object": "chat.completion",
            "created": native_created(),
            "model": model,
            "choices": [{"index": 0, "message": {"role": "assistant", "content": text}, "finish_reason": "stop"}],
            "usage": usage,
        });
        if let Some(owner) = response_cache_owner.take() {
            owner.complete(response.clone());
        } else if let Some(key) = cache_key {
            chat_cache_write(&state, key, response.clone());
        }
        drop(lease);
        return Ok(Json(response).into_response());
    }
    let payload = Value::Object(object.clone());
    let Some(base_url) = state.config.upstream_base_url.as_deref() else {
        return Err(ApiError::unavailable());
    };
    let url = format!("{}/v1/chat/completions", base_url.trim_end_matches('/'));
    let mut request = legacy_global_proxy_client(&state).post(url).json(&payload);
    if let Some(auth) = state.config.upstream_auth.as_deref() {
        request = request.header(header::AUTHORIZATION, auth);
    }
    let route_deadline = Instant::now() + upstream_timeout;
    let upstream = tokio::time::timeout_at(
        tokio::time::Instant::from_std(route_deadline),
        request.send(),
    )
    .await
    .map_err(|_| ApiError::upstream())?
    .map_err(|_| ApiError::upstream())?;
    if !upstream.status().is_success() {
        return Err(ApiError::upstream());
    }
    if upstream_declares_oversize(&upstream) {
        return Err(ApiError::upstream());
    }
    let wants_stream = object
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if wants_stream {
        return Ok(stream_response_with_timeout(upstream, upstream_timeout));
    }
    let body = tokio::time::timeout_at(
        tokio::time::Instant::from_std(route_deadline),
        bounded_response_body(upstream),
    )
    .await
    .map_err(|_| ApiError::upstream())??;
    let value: Value = serde_json::from_slice(&body).map_err(|_| ApiError::upstream())?;
    if !value.is_object() {
        return Err(ApiError::upstream());
    }
    Ok((
        StatusCode::OK,
        [(header::CONTENT_TYPE, "application/json")],
        Json(value),
    )
        .into_response())
}

async fn bounded_response_body(response: reqwest::Response) -> Result<Vec<u8>, ApiError> {
    if upstream_declares_oversize(&response) {
        return Err(ApiError::upstream());
    }
    let mut total = 0usize;
    let mut body = Vec::new();
    let mut chunks = response.bytes_stream();
    while let Some(chunk) = chunks.next().await {
        let chunk = chunk.map_err(|_| ApiError::upstream())?;
        total = total
            .checked_add(chunk.len())
            .ok_or_else(ApiError::upstream)?;
        if total > MAX_UPSTREAM_BODY_BYTES {
            return Err(ApiError::upstream());
        }
        body.extend_from_slice(&chunk);
    }
    Ok(body)
}

fn upstream_declares_oversize(response: &reqwest::Response) -> bool {
    response
        .content_length()
        .is_some_and(|length| length > MAX_UPSTREAM_BODY_BYTES as u64)
}

fn stream_response_with_timeout(response: reqwest::Response, read_timeout: Duration) -> Response {
    let stream = bounded_stream_with_timeout(response.bytes_stream(), read_timeout);
    let mut output = Response::new(Body::from_stream(stream));
    output.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/event-stream"),
    );
    output
        .headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"));
    output
}

fn bounded_stream_with_timeout<S, E>(
    input: S,
    read_timeout: Duration,
) -> impl Stream<Item = Result<Bytes, io::Error>>
where
    S: Stream<Item = Result<axum::body::Bytes, E>> + Send + 'static,
    E: Send + 'static,
{
    stream::unfold(
        (Box::pin(input), 0usize, false),
        move |(mut input, total, terminated)| async move {
            if terminated {
                return None;
            }
            match tokio::time::timeout(read_timeout, input.next()).await {
                Err(_) => Some((
                    Err(io::Error::other("upstream stream timed out")),
                    (input, total, true),
                )),
                Ok(None) => None,
                Ok(Some(Err(_))) => Some((
                    Err(io::Error::other("upstream stream failed")),
                    (input, total, true),
                )),
                Ok(Some(Ok(chunk))) => {
                    let Some(next_total) = total.checked_add(chunk.len()) else {
                        return Some((
                            Err(io::Error::other("upstream body exceeded limit")),
                            (input, total, true),
                        ));
                    };
                    if next_total > MAX_UPSTREAM_BODY_BYTES {
                        Some((
                            Err(io::Error::other("upstream body exceeded limit")),
                            (input, total, true),
                        ))
                    } else {
                        Some((Ok(chunk), (input, next_total, false)))
                    }
                }
            }
        },
    )
}

#[cfg(test)]
fn absolute_test_temp_path(path: PathBuf) -> PathBuf {
    if path.is_absolute() {
        path
    } else {
        env::current_dir()
            .expect("test temp current directory")
            .join(path)
    }
}

#[cfg(test)]
fn project_local_test_tmp_dir() -> PathBuf {
    let path = env::var_os("CHATGPT2API_TEST_TMPDIR")
        .map(PathBuf::from)
        .map(absolute_test_temp_path)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .parent()
                .expect("project root above Rust manifest")
                .join(".local")
                .join("codex")
                .join("tmp")
                .join("rust")
        });
    fs::create_dir_all(&path).expect("project-local test temp directory");
    path
}

