    #[tokio::test]
    async fn user_key_management_returns_plaintext_once_and_redacts_snapshots() {
        let path = account_snapshot_path("auth-users");
        fs::write(
            &path,
            serde_json::to_vec(&json!({
                "items": [{
                    "id": "u0",
                    "name": "old",
                    "role": "user",
                    "enabled": true,
                    "key_hash": auth_key_hash("old-key"),
                    "internal_secret": "should-not-leak"
                }, {
                    "id": "admin-key",
                    "name": "admin",
                    "role": "admin",
                    "enabled": true,
                    "key_hash": auth_key_hash("admin")
                }]
            }))
            .expect("auth snapshot"),
        )
        .expect("write auth snapshot");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("admin".to_owned()),
            models: Vec::new(),
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: Some(path.clone()),
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let listed = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/api/auth/users")
                    .header(header::AUTHORIZATION, "Bearer admin")
                    .body(Body::empty())
                    .expect("list request"),
            )
            .await
            .expect("list response");
        let listed = json_response(listed).await;
        assert!(
            listed["items"]
                .as_array()
                .expect("listed users")
                .iter()
                .all(|item| item["role"] == "user")
        );
        assert!(
            listed["items"]
                .as_array()
                .expect("listed users")
                .iter()
                .all(|item| item.get("internal_secret").is_none())
        );
        let create = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/api/auth/users")
                    .header(header::AUTHORIZATION, "Bearer admin")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"name":"new"}"#))
                    .expect("create request"),
            )
            .await
            .expect("create response");
        assert_eq!(create.status(), StatusCode::OK);
        let created = json_response(create).await;
        let key = created["key"].as_str().expect("one-time key").to_owned();
        let id = created["item"]["id"].as_str().expect("user id").to_owned();
        assert!(created["item"].get("key_hash").is_none());
        assert!(created["items"][1].get("key_hash").is_none());
        assert!(created["item"]["created_at"].as_str().is_some());
        assert_eq!(created["item"]["last_used_at"], Value::Null);

        let forbidden = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/api/auth/users")
                    .header(header::AUTHORIZATION, format!("Bearer {key}"))
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"name":"nested"}"#))
                    .expect("forbidden request"),
            )
            .await
            .expect("forbidden response");
        assert_eq!(forbidden.status(), StatusCode::FORBIDDEN);
        let malformed_create = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/api/auth/users")
                    .header(header::AUTHORIZATION, "Bearer not-a-key")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from("{"))
                    .expect("malformed create request"),
            )
            .await
            .expect("malformed create response");
        assert_eq!(malformed_create.status(), StatusCode::UNAUTHORIZED);

        let malformed_update = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/api/auth/users/u0")
                    .header(header::AUTHORIZATION, "Bearer not-a-key")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from("{"))
                    .expect("malformed update request"),
            )
            .await
            .expect("malformed update response");
        assert_eq!(malformed_update.status(), StatusCode::UNAUTHORIZED);

        let update = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/api/auth/users/{id}"))
                    .header(header::AUTHORIZATION, "Bearer admin")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"enabled":false}"#))
                    .expect("update request"),
            )
            .await
            .expect("update response");
        assert_eq!(update.status(), StatusCode::OK);
        let updated = json_response(update).await;
        assert_eq!(updated["item"]["enabled"], false);

        let stored = tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                let stored: Value = serde_json::from_slice(
                    &fs::read(&path).expect("stored auth during last-used flush"),
                )
                .expect("stored auth JSON during last-used flush");
                if stored["items"].as_array().is_some_and(|items| {
                    items
                        .iter()
                        .any(|item| item["id"] == id && item["last_used_at"].as_str().is_some())
                }) {
                    break stored;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("last-used timestamp was not persisted");
        let created_stored = stored["items"]
            .as_array()
            .expect("auth items")
            .iter()
            .find(|item| item["id"] == id)
            .expect("created record");
        assert_eq!(created_stored["key_hash"], auth_key_hash(&key));
        assert!(created_stored.get("key").is_none());
        assert!(created_stored["last_used_at"].as_str().is_some());

        let delete = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("DELETE")
                    .uri(format!("/api/auth/users/{id}"))
                    .header(header::AUTHORIZATION, "Bearer admin")
                    .body(Body::empty())
                    .expect("delete request"),
            )
            .await
            .expect("delete response");
        assert_eq!(delete.status(), StatusCode::OK);
        assert!(
            json_response(delete).await["items"]
                .as_array()
                .expect("remaining users")
                .iter()
                .all(|item| item["id"] != id)
        );
        let _ = fs::remove_file(path);
    }

    #[tokio::test]
    async fn user_key_names_and_replacements_match_python_contract() {
        let path = account_snapshot_path("auth-user-name-contract");
        fs::write(&path, br#"{"items":[]}"#).expect("empty auth snapshot");
        let state = auth_state(&path);

        let create_default = management_request(
            &state,
            "POST",
            "/api/auth/users",
            Some(json!({})),
            Some("admin"),
        )
        .await;
        assert_eq!(create_default.status(), StatusCode::OK);
        let create_default = json_response(create_default).await;
        assert_eq!(create_default["item"]["name"], "普通用户");
        let first_key = create_default["key"]
            .as_str()
            .expect("first key")
            .to_owned();
        let first_id = create_default["item"]["id"]
            .as_str()
            .expect("first id")
            .to_owned();

        let create_default_again = management_request(
            &state,
            "POST",
            "/api/auth/users",
            Some(json!({"name":""})),
            Some("admin"),
        )
        .await;
        assert_eq!(create_default_again.status(), StatusCode::OK);
        let create_default_again = json_response(create_default_again).await;
        assert_eq!(create_default_again["item"]["name"], "普通用户 2");
        let second_id = create_default_again["item"]["id"]
            .as_str()
            .expect("second id")
            .to_owned();

        let duplicate_name = management_request(
            &state,
            "POST",
            "/api/auth/users",
            Some(json!({"name":"普通用户"})),
            Some("admin"),
        )
        .await;
        assert_eq!(duplicate_name.status(), StatusCode::BAD_REQUEST);

        let duplicate_key = management_request(
            &state,
            "POST",
            &format!("/api/auth/users/{second_id}"),
            Some(json!({"key":first_key})),
            Some("admin"),
        )
        .await;
        assert_eq!(duplicate_key.status(), StatusCode::BAD_REQUEST);
        let admin_key = management_request(
            &state,
            "POST",
            &format!("/api/auth/users/{second_id}"),
            Some(json!({"key":"admin"})),
            Some("admin"),
        )
        .await;
        assert_eq!(admin_key.status(), StatusCode::BAD_REQUEST);

        let replace_key = management_request(
            &state,
            "POST",
            &format!("/api/auth/users/{second_id}"),
            Some(json!({"key":"replacement-user-key"})),
            Some("admin"),
        )
        .await;
        assert_eq!(replace_key.status(), StatusCode::OK);
        let replace_key = json_response(replace_key).await;
        assert!(replace_key.get("key").is_none());
        assert_eq!(replace_key["item"]["id"], second_id);

        let enabled_string = management_request(
            &state,
            "POST",
            &format!("/api/auth/users/{second_id}"),
            Some(json!({"enabled":"no"})),
            Some("admin"),
        )
        .await;
        assert_eq!(enabled_string.status(), StatusCode::OK);
        assert_eq!(
            json_response(enabled_string).await["item"]["enabled"],
            false
        );

        let rename_to_duplicate = management_request(
            &state,
            "POST",
            &format!("/api/auth/users/{second_id}"),
            Some(json!({"name":"普通用户"})),
            Some("admin"),
        )
        .await;
        assert_eq!(rename_to_duplicate.status(), StatusCode::BAD_REQUEST);

        let rename_default = management_request(
            &state,
            "POST",
            &format!("/api/auth/users/{first_id}"),
            Some(json!({"name":""})),
            Some("admin"),
        )
        .await;
        assert_eq!(rename_default.status(), StatusCode::OK);
        assert_eq!(
            json_response(rename_default).await["item"]["name"],
            "普通用户"
        );

        state.account_type_catalog.shutdown().await;
        drop(state);
        let _ = fs::remove_file(path);
    }

    #[tokio::test]
    async fn auth_mutations_from_independent_states_preserve_all_unrelated_writes() {
        let path = account_snapshot_path("auth-independent-states");
        fs::write(
            &path,
            serde_json::to_vec(&json!({
                "revision": 41,
                "canary": {"owner": "auth-contract"},
                "items": [{
                    "id": "u0",
                    "name": "old",
                    "role": "user",
                    "enabled": true,
                    "key_hash": auth_key_hash("old-key")
                }]
            }))
            .expect("auth snapshot"),
        )
        .expect("write auth snapshot");
        let first = auth_state(&path);
        let second = auth_state(&path);

        let (create_first, create_second) = tokio::join!(
            management_request(
                &first,
                "POST",
                "/api/auth/users",
                Some(json!({"name":"first"})),
                Some("admin"),
            ),
            management_request(
                &second,
                "POST",
                "/api/auth/users",
                Some(json!({"name":"second"})),
                Some("admin"),
            ),
        );
        assert_eq!(create_first.status(), StatusCode::OK);
        assert_eq!(create_second.status(), StatusCode::OK);
        let first_user = json_response(create_first).await["item"]["id"]
            .as_str()
            .expect("first user id")
            .to_owned();
        let first_user_uri = format!("/api/auth/users/{first_user}");

        let (update_first, create_third) = tokio::join!(
            management_request(
                &first,
                "POST",
                &first_user_uri,
                Some(json!({"name":"first-updated"})),
                Some("admin"),
            ),
            management_request(
                &second,
                "POST",
                "/api/auth/users",
                Some(json!({"name":"third"})),
                Some("admin"),
            ),
        );
        assert_eq!(update_first.status(), StatusCode::OK);
        assert_eq!(create_third.status(), StatusCode::OK);
        let third_user = json_response(create_third).await["item"]["id"]
            .as_str()
            .expect("third user id")
            .to_owned();

        let (delete_old, update_first_enabled) = tokio::join!(
            management_request(&first, "DELETE", "/api/auth/users/u0", None, Some("admin"),),
            management_request(
                &second,
                "POST",
                &first_user_uri,
                Some(json!({"enabled":false})),
                Some("admin"),
            ),
        );
        assert_eq!(delete_old.status(), StatusCode::OK);
        assert_eq!(update_first_enabled.status(), StatusCode::OK);

        let stored: Value =
            serde_json::from_slice(&fs::read(&path).expect("stored auth")).expect("stored json");
        assert_eq!(stored["revision"], 41);
        assert_eq!(stored["canary"]["owner"], "auth-contract");
        let items = stored["items"].as_array().expect("auth items");
        assert_eq!(items.len(), 3);
        assert!(items.iter().all(|item| item["id"] != "u0"));
        let first_item = items
            .iter()
            .find(|item| item["id"] == first_user)
            .expect("first user retained");
        assert_eq!(first_item["name"], "first-updated");
        assert_eq!(first_item["enabled"], false);
        assert!(items.iter().any(|item| item["id"] == third_user));
        let _ = fs::remove_file(path);
    }

    #[tokio::test]
    async fn auth_mutation_rejects_external_revision_and_keeps_external_snapshot() {
        let path = account_snapshot_path("auth-external-revision");
        fs::write(
            &path,
            serde_json::to_vec(&json!({
                "revision": 1,
                "canary": "before",
                "items": [{
                    "id": "u0",
                    "name": "old",
                    "role": "user",
                    "enabled": true,
                    "key_hash": auth_key_hash("old-key")
                }]
            }))
            .expect("auth snapshot"),
        )
        .expect("write auth snapshot");
        let state = auth_state(&path);
        let hook = AuthMutationTestHook {
            pause_before_cas: Arc::new(AtomicBool::new(true)),
            cas_ready: Arc::new(Notify::new()),
            release_cas: Arc::new(Notify::new()),
            fail_before_write: Arc::new(AtomicBool::new(false)),
        };
        state.auth_store.set_mutation_test_hook(Some(hook.clone()));
        let worker = state.clone();
        let request = tokio::spawn(async move {
            management_request(
                &worker,
                "POST",
                "/api/auth/users",
                Some(json!({"name":"must-not-win"})),
                Some("admin"),
            )
            .await
        });
        hook.cas_ready.notified().await;
        fs::write(
            &path,
            serde_json::to_vec(&json!({
                "revision": 2,
                "canary": "external",
                "items": [{
                    "id": "external",
                    "name": "external-writer",
                    "role": "user",
                    "enabled": true,
                    "key_hash": auth_key_hash("external-key")
                }]
            }))
            .expect("external auth snapshot"),
        )
        .expect("external write");
        hook.release_cas.notify_one();
        let response = request.await.expect("mutation task");
        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(!state.auth_store.accepts("old-key"));
        let stored: Value =
            serde_json::from_slice(&fs::read(&path).expect("external snapshot remains"))
                .expect("stored json");
        assert_eq!(stored["revision"], 2);
        assert_eq!(stored["canary"], "external");
        assert_eq!(stored["items"][0]["id"], "external");
        state.auth_store.set_mutation_test_hook(None);
        let _ = fs::remove_file(path);
    }

