    #[tokio::test]
    async fn account_refresh_uses_access_token_only_and_refreshes_metadata() {
        let calls = Arc::new(StdMutex::new(Vec::<String>::new()));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("account refresh upstream listener");
        let address = listener
            .local_addr()
            .expect("account refresh upstream address");

        let me_calls = calls.clone();
        let me = get(move |headers: HeaderMap| {
            let calls = me_calls.clone();
            async move {
                assert_eq!(
                    headers
                        .get(header::AUTHORIZATION)
                        .and_then(|value| value.to_str().ok()),
                    Some("Bearer access-token")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Path")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/me")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Route")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/me")
                );
                calls
                    .lock()
                    .expect("account refresh calls lock")
                    .push("GET /backend-api/me".to_owned());
                Json(json!({"email":"pro@example.com","id":"user-pro"}))
            }
        });
        let init_calls = calls.clone();
        let init = post(move |headers: HeaderMap, Json(_body): Json<Value>| {
            let calls = init_calls.clone();
            async move {
                assert_eq!(
                    headers
                        .get(header::AUTHORIZATION)
                        .and_then(|value| value.to_str().ok()),
                    Some("Bearer access-token")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Path")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/conversation/init")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Route")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/conversation/init")
                );
                calls
                    .lock()
                    .expect("account refresh calls lock")
                    .push("POST /backend-api/conversation/init".to_owned());
                Json(json!({
                    "default_model_slug":"gpt-5-5",
                    "limits_progress":[{"feature_name":"image_gen","remaining":17,"reset_after":"2026-09-08T00:00:00Z"}]
                }))
            }
        });
        let check_calls = calls.clone();
        let check = get(move |headers: HeaderMap| {
            let calls = check_calls.clone();
            async move {
                assert_eq!(
                    headers
                        .get(header::AUTHORIZATION)
                        .and_then(|value| value.to_str().ok()),
                    Some("Bearer access-token")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Path")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/accounts/check/v4-2023-04-27")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Route")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/accounts/check/v4-2023-04-27")
                );
                calls
                    .lock()
                    .expect("account refresh calls lock")
                    .push("GET /backend-api/accounts/check/v4-2023-04-27".to_owned());
                Json(
                    json!({"accounts":{"default":{"account":{"account_id":"acct-pro","plan_type":"pro"}}}}),
                )
            }
        });
        let model_calls = calls.clone();
        let models = get(move |headers: HeaderMap| {
            let calls = model_calls.clone();
            async move {
                assert_eq!(
                    headers
                        .get(header::AUTHORIZATION)
                        .and_then(|value| value.to_str().ok()),
                    Some("Bearer access-token")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Path")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/models")
                );
                assert_eq!(
                    headers
                        .get("X-OpenAI-Target-Route")
                        .and_then(|value| value.to_str().ok()),
                    Some("/backend-api/models")
                );
                calls
                    .lock()
                    .expect("account refresh calls lock")
                    .push("GET /backend-api/models".to_owned());
                Json(json!({"models":[
                    {"slug":"gpt-pro"},
                    {"slug":"gpt-5-5"},
                    {"slug":"gpt-image-2"},
                    {"slug":"gpt-image-2.5"}
                ]}))
            }
        });
        let anonymous_model_calls = calls.clone();
        let anonymous_models = get(move |headers: HeaderMap| {
            let calls = anonymous_model_calls.clone();
            async move {
                assert!(headers.get(header::AUTHORIZATION).is_none());
                calls
                    .lock()
                    .expect("account refresh calls lock")
                    .push("GET /backend-anon/models".to_owned());
                Json(json!({"models":[{"slug":"gpt-public"}]}))
            }
        });
        let upstream = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new()
                    .route("/", get(|| async { Html("<html></html>") }))
                    .route("/backend-api/me", me)
                    .route("/backend-api/conversation/init", init)
                    .route("/backend-api/accounts/check/v4-2023-04-27", check)
                    .route("/backend-api/models", models)
                    .route("/backend-anon/models", anonymous_models),
            )
            .await
            .expect("account refresh upstream server");
        });

        let path = account_snapshot_path("refresh-progress");
        fs::write(
            &path,
            serde_json::to_vec(&json!([{
                "access_token": "access-token",
                "refresh_token": "refresh-token",
                "id_token": "id-token",
                "success": 7,
                "fail": 4,
                "status": "正常",
                "type": "free",
                "_model_source_version": 1,
                "_verified_web_model_paths": ["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],
                "models": ["saved-model"],
                "model_sources": {"saved-model":"web"}
            }]))
            .expect("account snapshot"),
        )
        .expect("write account snapshot");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("admin".to_owned()),
            models: Vec::new(),
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let start = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/api/accounts/refresh")
                    .header(header::AUTHORIZATION, "Bearer admin")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"access_tokens":["access-token"]}"#))
                    .expect("refresh request"),
            )
            .await
            .expect("refresh response");
        assert_eq!(start.status(), StatusCode::OK);
        let start_body = json_response(start).await;
        let progress_id = start_body["progress_id"]
            .as_str()
            .expect("progress id")
            .to_owned();
        let mut completed = Value::Null;
        for _ in 0..100 {
            let progress = management_request(
                &state,
                "GET",
                &format!("/api/accounts/refresh/progress/{progress_id}"),
                None,
                Some("admin"),
            )
            .await;
            completed = json_response(progress).await;
            if completed["done"].as_bool() == Some(true) {
                break;
            }
            tokio::task::yield_now().await;
        }
        assert_eq!(completed["done"], true);
        assert_eq!(completed["status"], "completed");
        assert_eq!(completed["result"]["items"][0]["type"], "pro");
        assert_eq!(completed["result"]["items"][0]["quota"], 17);
        assert_eq!(completed["result"]["items"][0]["success"], 7);
        assert_eq!(completed["result"]["items"][0]["fail"], 4);
        assert_eq!(
            completed["result"]["items"][0]["models"],
            json!(["saved-model"])
        );
        let persisted = fs::read_to_string(&path).expect("refreshed snapshot");
        assert!(!persisted.contains("refresh_token"));
        assert!(!persisted.contains("id_token"));
        let refresh_calls = calls.lock().expect("account refresh calls lock").clone();
        assert_eq!(refresh_calls.len(), 3);
        assert!(
            refresh_calls
                .iter()
                .any(|call| call.starts_with("GET /backend-api/me"))
        );
        assert!(
            refresh_calls
                .iter()
                .any(|call| call.starts_with("POST /backend-api/conversation/init"))
        );
        assert!(
            refresh_calls
                .iter()
                .any(|call| call.starts_with("GET /backend-api/accounts/check"))
        );
        assert!(
            !refresh_calls
                .iter()
                .any(|call| call.starts_with("GET /backend-api/models"))
        );
        let models_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("GET")
                    .uri("/v1/models")
                    .header(header::AUTHORIZATION, "Bearer admin")
                    .body(Body::empty())
                    .expect("models request"),
            )
            .await
            .expect("models response");
        assert_eq!(models_response.status(), StatusCode::OK);
        let models_body = models_response
            .into_body()
            .collect()
            .await
            .expect("models body")
            .to_bytes();
        let models_value: Value = serde_json::from_slice(&models_body).expect("models json");
        let public_models = models_value["data"]
            .as_array()
            .expect("public v1.7 model list");
        assert!(public_models.iter().any(|item| item["id"] == "gpt-pro"));
        assert!(public_models.iter().any(|item| item["id"] == "gpt-5-5"));
        assert!(public_models.iter().any(|item| item["id"] == "gpt-image-2"));
        assert!(
            public_models
                .iter()
                .any(|item| item["id"] == "gpt-image-2.5")
        );
        assert!(
            calls
                .lock()
                .expect("account refresh calls lock")
                .iter()
                .any(|call| call.starts_with("GET /backend-api/models"))
        );
        assert!(
            calls
                .lock()
                .expect("account refresh calls lock")
                .iter()
                .any(|call| call == "GET /backend-anon/models")
        );
        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
        let _ = fs::remove_file(path);
    }

    #[tokio::test]
    async fn imported_account_refresh_shares_model_catalog_per_type() {
        let model_calls = Arc::new(AtomicUsize::new(0));
        let started = Arc::new(Notify::new());
        let release = Arc::new(Notify::new());
        let cache = ImportedModelCatalogCache::new();
        let first_cache = cache.clone();
        let first_calls = model_calls.clone();
        let first_started = started.clone();
        let first_release = release.clone();
        let first = tokio::spawn(async move {
            first_cache
                .fetch_or_reuse("pro", || async move {
                    first_calls.fetch_add(1, Ordering::SeqCst);
                    first_started.notify_one();
                    first_release.notified().await;
                    Some(vec![test_public_model("pro-model", ModelProvenance::Web)])
                })
                .await
        });
        started.notified().await;
        let second_cache = cache.clone();
        let second = tokio::spawn(async move {
            second_cache
                .fetch_or_reuse("pro", || async {
                    panic!("same-type concurrent request must reuse in-flight catalog")
                })
                .await
        });
        let isolated_cache = cache.clone();
        let isolated = tokio::spawn(async move {
            isolated_cache
                .fetch_or_reuse("free", || async {
                    Some(vec![test_public_model("free-model", ModelProvenance::Web)])
                })
                .await
                .map(|models| models.into_iter().map(|model| model.id).collect::<Vec<_>>())
        });
        release.notify_waiters();
        assert_eq!(
            first
                .await
                .expect("first cache join")
                .map(|models| models.into_iter().map(|model| model.id).collect::<Vec<_>>()),
            Some(vec!["pro-model".to_owned()])
        );
        assert_eq!(
            second
                .await
                .expect("second cache join")
                .map(|models| models.into_iter().map(|model| model.id).collect::<Vec<_>>()),
            Some(vec!["pro-model".to_owned()])
        );
        assert_eq!(
            isolated.await.expect("isolated cache join"),
            Some(vec!["free-model".to_owned()])
        );
        assert_eq!(model_calls.load(Ordering::SeqCst), 1);
        assert_eq!(cache.stats(), (2, 1));
    }

    #[tokio::test]
    async fn imported_model_catalog_failure_has_short_retry_backoff() {
        let cache = ImportedModelCatalogCache::new();
        let calls = Arc::new(AtomicUsize::new(0));
        assert_eq!(
            cache
                .fetch_or_reuse("pro", {
                    let calls = calls.clone();
                    move || async move {
                        calls.fetch_add(1, Ordering::SeqCst);
                        None
                    }
                })
                .await,
            None
        );
        assert_eq!(
            cache
                .fetch_or_reuse("pro", || async {
                    panic!("failure should be suppressed during retry backoff")
                })
                .await,
            None
        );
        tokio::time::sleep(IMPORTED_MODEL_CATALOG_RETRY_BACKOFF + Duration::from_millis(10)).await;
        assert_eq!(
            cache
                .fetch_or_reuse("pro", {
                    let calls = calls.clone();
                    move || async move {
                        calls.fetch_add(1, Ordering::SeqCst);
                        Some(vec![test_public_model("retry-model", ModelProvenance::Web)])
                    }
                })
                .await
                .map(|models| models.into_iter().map(|model| model.id).collect::<Vec<_>>()),
            Some(vec!["retry-model".to_owned()])
        );
        assert_eq!(calls.load(Ordering::SeqCst), 2);
    }

    #[tokio::test]
    async fn imported_model_catalog_does_not_retry_permanent_bootstrap_forbidden() {
        let calls = Arc::new(AtomicUsize::new(0));
        let route_calls = calls.clone();
        let app = Router::new()
            .route("/__ready", get(|| async { StatusCode::NO_CONTENT }))
            .route(
                "/",
                get(move || {
                    let calls = route_calls.clone();
                    async move {
                        calls.fetch_add(1, Ordering::SeqCst);
                        StatusCode::FORBIDDEN
                    }
                }),
            );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("forbidden catalog listener");
        let address = listener.local_addr().expect("forbidden catalog address");
        let (ready_tx, ready_rx) = tokio::sync::oneshot::channel();
        let mut server = tokio::spawn(async move {
            let _ = ready_tx.send(());
            axum::serve(listener, app)
                .await
                .expect("forbidden catalog server");
        });
        tokio::select! {
            result = ready_rx => result.expect("forbidden catalog server failed before startup"),
            result = &mut server => panic!("forbidden catalog server exited before startup: {result:?}"),
        }
        let batch = Arc::new(ImportedModelCatalogBatchStats::default());
        let result =
            fetch_imported_native_model_catalog_with_retry(NativeModelCatalogRetryRequest {
                cache: ImportedModelCatalogCache::new(),
                key: "pro".to_owned(),
                deadline: Instant::now() + Duration::from_secs(1),
                batch: Some(batch.clone()),
                client: Client::builder()
                    .no_proxy()
                    .build()
                    .expect("direct imported catalog test client"),
                base_url: format!("http://{address}"),
                account_type: "pro".to_owned(),
                token: "access-only".to_owned(),
                account_id: None,
            })
            .await;
        assert!(result.is_none());
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        let stats = batch.snapshot();
        assert_eq!(stats.attempts, 1);
        assert_eq!(stats.retries, 0);
        server.abort();
        let _ = server.await;
    }

    #[tokio::test]
    async fn imported_model_catalog_retries_empty_owner_fetch_before_publishing_cache() {
        let cache = ImportedModelCatalogCache::new();
        let batch = Arc::new(ImportedModelCatalogBatchStats::default());
        let retry_batch = batch.clone();
        let calls = Arc::new(AtomicUsize::new(0));
        let owner_cache = cache.clone();
        let retry_owner_cache = cache.clone();
        let owner_calls = calls.clone();
        let result = owner_cache
            .fetch_or_reuse("pro", move || {
                let retry_cache = retry_owner_cache.clone();
                let retry_calls = owner_calls.clone();
                async move {
                    fetch_imported_model_catalog_with_retry(
                        &retry_cache,
                        "pro",
                        Instant::now() + Duration::from_secs(1),
                        Some(retry_batch.clone()),
                        || async {
                            if retry_calls.fetch_add(1, Ordering::SeqCst) == 0 {
                                None
                            } else {
                                Some(vec![test_public_model(
                                    "retried-model",
                                    ModelProvenance::Web,
                                )])
                            }
                        },
                    )
                    .await
                }
            })
            .await;
        assert_eq!(
            result.map(|models| models.into_iter().map(|model| model.id).collect::<Vec<_>>()),
            Some(vec!["retried-model".to_owned()])
        );
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        assert_eq!(cache.retry_count(), 1);
        assert_eq!(cache.attempt_count(), 2);
        let stats = batch.snapshot();
        assert_eq!(stats.attempts, 2);
        assert_eq!(stats.retries, 1);
        assert_eq!(stats.fetches, 0);
        assert_eq!(
            cache
                .fetch_or_reuse("pro", || async {
                    panic!("successful retry must publish a ready cache")
                })
                .await
                .map(|_| ()),
            Some(())
        );
    }

