    #[tokio::test]
    async fn account_refresh_non_auth_upstream_error_does_not_mark_account_abnormal() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("refresh error upstream listener");
        let address = listener
            .local_addr()
            .expect("refresh error upstream address");
        let upstream = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new().fallback(|| async { StatusCode::SERVICE_UNAVAILABLE }),
            )
            .await
            .expect("refresh error upstream server");
        });
        let path = account_snapshot_path("refresh-error-preserves-account");
        fs::write(
            &path,
            serde_json::to_vec(&json!([{
                "access_token": "access-token",
                "status": "正常",
                "type": "pro"
            }]))
            .expect("account snapshot"),
        )
        .expect("write account snapshot");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("admin".to_owned()),
            models: Vec::new(),
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let start = management_request(
            &state,
            "POST",
            "/api/accounts/refresh",
            Some(json!({"access_tokens":["access-token"]})),
            Some("admin"),
        )
        .await;
        assert_eq!(start.status(), StatusCode::OK);
        let progress_id = json_response(start).await["progress_id"]
            .as_str()
            .expect("progress id")
            .to_owned();
        let completed = tokio::time::timeout(Duration::from_secs(3), async {
            loop {
                let completed = json_response(
                    management_request(
                        &state,
                        "GET",
                        &format!("/api/accounts/refresh/progress/{progress_id}"),
                        None,
                        Some("admin"),
                    )
                    .await,
                )
                .await;
                if completed["done"].as_bool() == Some(true) {
                    break completed;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("account refresh progress completion");
        assert_eq!(completed["result"]["errors"][0]["code"], "upstream_error");
        assert_eq!(
            completed["result"]["errors"][0]["token"],
            "token:3f16bed708"
        );
        assert_eq!(
            completed["result"]["errors"][0]["error"],
            "upstream request failed"
        );
        assert_eq!(
            completed["errors"][0]["error"], "upstream request failed",
            "progress polling should expose the human-readable refresh failure field"
        );
        let accounts = json_response(
            management_request(&state, "GET", "/api/accounts", None, Some("admin")).await,
        )
        .await;
        assert_eq!(accounts["items"][0]["status"], "正常");
        assert_eq!(accounts["items"][0]["last_refresh_error"], Value::Null);
        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
        let _ = fs::remove_file(path);
    }

