    #[tokio::test(flavor = "multi_thread", worker_threads = 8)]
    async fn account_refresh_fetches_metadata_endpoints_concurrently() {
        async fn gated_metadata_response(
            calls: Arc<AtomicUsize>,
            all_started: Arc<Notify>,
            release: Arc<Semaphore>,
            payload: Value,
        ) -> Json<Value> {
            if calls.fetch_add(1, Ordering::SeqCst) + 1 == 3 {
                all_started.notify_one();
            }
            let permit = release.acquire().await.expect("metadata release permit");
            permit.forget();
            Json(payload)
        }

        let account_path = account_snapshot_path("account-refresh-parallel-metadata");
        fs::write(&account_path, "[]").expect("empty accounts");
        let calls = Arc::new(AtomicUsize::new(0));
        let all_started = Arc::new(Notify::new());
        let release = Arc::new(Semaphore::new(0));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("metadata listener");
        let address = listener.local_addr().expect("metadata address");

        let me = get({
            let calls = calls.clone();
            let all_started = all_started.clone();
            let release = release.clone();
            move || {
                gated_metadata_response(
                    calls.clone(),
                    all_started.clone(),
                    release.clone(),
                    json!({"email":"parallel@example.com","id":"parallel-user"}),
                )
            }
        });
        let init = post({
            let calls = calls.clone();
            let all_started = all_started.clone();
            let release = release.clone();
            move || {
                gated_metadata_response(
                    calls.clone(),
                    all_started.clone(),
                    release.clone(),
                    json!({
                        "default_model_slug":"gpt-5-5",
                        "limits_progress":[{"feature_name":"image_gen","remaining":4}]
                    }),
                )
            }
        });
        let account_check = get({
            let calls = calls.clone();
            let all_started = all_started.clone();
            let release = release.clone();
            move || {
                gated_metadata_response(
                    calls.clone(),
                    all_started.clone(),
                    release.clone(),
                    json!({
                        "accounts":{"default":{"account":{"plan_type":"pro","account_id":"parallel-account"}}}
                    }),
                )
            }
        });
        let upstream = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new()
                    .route("/backend-api/me", me)
                    .route("/backend-api/conversation/init", init)
                    .route("/backend-api/accounts/check/v4-2023-04-27", account_check)
                    .route("/", get(|| async { Html("<html></html>") }))
                    .route(
                        "/backend-api/models",
                        get(|| async { Json(json!({"models":[{"slug":"parallel-model"}]})) }),
                    )
                    .route(
                        "/backend-api/tpp/models/",
                        get(|| async { Json(json!({"models":[]})) }),
                    ),
            )
            .await
            .expect("metadata upstream");
        });
        wait_for_test_http_ready(&format!("http://{address}"), "/").await;
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: None,
            models: Vec::new(),
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("refresh state");
        let all_started_wait = all_started.notified();
        tokio::pin!(all_started_wait);
        all_started_wait.as_mut().enable();
        let refresh_state = state.clone();
        let refresh = tokio::spawn(async move {
            refresh_access_token_account(
                &refresh_state,
                &json!({"access_token":"parallel-token","type":"pro"}),
            )
            .await
        });
        let all_metadata_started = tokio::time::timeout(Duration::from_secs(5), all_started_wait)
            .await
            .is_ok();
        release.add_permits(3);
        let refresh_result = tokio::time::timeout(Duration::from_secs(15), refresh)
            .await
            .expect("refresh completion")
            .expect("refresh task");

        assert!(
            all_metadata_started,
            "all three metadata requests should be in flight before any response completes; started={}",
            calls.load(Ordering::SeqCst)
        );
        let refreshed = refresh_result.expect("account metadata refresh");
        assert_eq!(calls.load(Ordering::SeqCst), 3);
        assert_eq!(refreshed["email"], "parallel@example.com");
        assert_eq!(refreshed["type"], "pro");
        assert_eq!(refreshed["quota"], 4);

        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
        fs::remove_file(account_path).expect("accounts cleanup");
    }

