    #[tokio::test]
    async fn image_retention_cleanup_runs_at_startup_listing_and_save() {
        fn write_expired_image(path: &Path) {
            fs::create_dir_all(path.parent().expect("expired image parent"))
                .expect("expired image directory");
            fs::write(path, b"expired image").expect("expired image");
            let old_time = filetime::FileTime::from_system_time(
                SystemTime::now() - Duration::from_secs(2 * 86_400),
            );
            filetime::set_file_mtime(path, old_time).expect("set expired image mtime");
        }

        let account_path = account_snapshot_path("image-retention-triggers");
        let data_dir = account_path
            .parent()
            .expect("image retention data dir")
            .to_owned();
        fs::write(&account_path, b"[]").expect("empty accounts");
        fs::write(
            data_dir.join("config.json"),
            br#"{"image_retention_days":1,"image_storage":{"enabled":false,"mode":"local"}}"#,
        )
        .expect("retention config");
        let expired_path = data_dir.join("images/expired.png");
        write_expired_image(&expired_path);
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("admin".to_owned()),
            models: Vec::new(),
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("retention state");
        assert!(
            !expired_path.exists(),
            "startup applies configured retention"
        );

        write_expired_image(&expired_path);
        let listing = management_request(&state, "GET", "/api/images", None, Some("admin")).await;
        assert_eq!(listing.status(), StatusCode::OK);
        let listed = json_response(listing).await;
        assert!(listed["items"].as_array().expect("image list").is_empty());
        assert!(
            !expired_path.exists(),
            "listing applies configured retention"
        );

        write_expired_image(&expired_path);
        management::store_generated_image(&state, "fresh.png", b"fresh image".to_vec())
            .await
            .expect("save generated image");
        assert!(
            !expired_path.exists(),
            "saving applies configured retention"
        );
        assert!(data_dir.join("images/fresh.png").is_file());

        state.account_type_catalog.shutdown().await;
        drop(state);
        let _ = fs::remove_dir_all(data_dir);
    }

