    #[test]
    fn image_task_resume_input_matches_python_float_and_validation_contract() {
        assert_eq!(
            image_task_resume_timeout(None).expect("default timeout"),
            30.0
        );
        assert_eq!(
            image_task_resume_timeout(Some(&json!("5.5"))).expect("numeric string timeout"),
            5.5
        );
        assert_eq!(
            image_task_resume_timeout(Some(&json!(120))).expect("max timeout"),
            120.0
        );
        assert_eq!(
            image_task_resume_timeout(Some(&json!("4")))
                .expect_err("below-minimum timeout")
                .status,
            StatusCode::UNPROCESSABLE_ENTITY
        );
        assert_eq!(
            image_task_resume_timeout(Some(&json!("not-a-number")))
                .expect_err("invalid timeout string")
                .status,
            StatusCode::UNPROCESSABLE_ENTITY
        );

        let not_error = image_task_resume_context(&json!({"status":"running"}))
            .expect_err("running task is rejected first");
        assert_eq!(not_error.message(), "task is not in error state");
        let not_timeout = image_task_resume_context(&json!({
            "status":"error",
            "error":"generation rejected"
        }))
        .expect_err("non-timeout error is rejected before conversation lookup");
        assert_eq!(not_timeout.message(), "task error is not a timeout error");
        let missing_conversation = image_task_resume_context(&json!({
            "status":"error",
            "error":"generation 超时"
        }))
        .expect_err("timeout task without a conversation is rejected");
        assert_eq!(
            missing_conversation.message(),
            "task has no conversation_id"
        );
        assert_eq!(
            image_task_resume_context(&json!({
                "status":"error",
                "error":"generation 超时",
                "conversation_id":"resume-conversation",
                "model":"gpt-image-2",
                "mode":"edit"
            }))
            .expect("resumable task"),
            (
                "resume-conversation".to_owned(),
                "gpt-image-2".to_owned(),
                "edit".to_owned(),
                String::new()
            )
        );
    }

