    #[tokio::test]
    async fn image_task_resume_persists_updated_timestamp_before_worker_progress() {
        let root = account_snapshot_path("image-task-resume-timestamp").with_extension("dir");
        fs::create_dir_all(&root).expect("resume task root");
        let account_path = root.join("accounts.json");
        let task_path = root.join("image_tasks.json");
        let (recent_task_timestamp, recent_task_ts) = image_task_now();
        let old_task_ts = recent_task_ts - 60.0;
        let old_datetime = time::OffsetDateTime::from_unix_timestamp(old_task_ts as i64)
            .expect("prior task timestamp");
        let old_updated_at = format!(
            "{:04}-{:02}-{:02} {:02}:{:02}:{:02}",
            old_datetime.year(),
            old_datetime.month() as u8,
            old_datetime.day(),
            old_datetime.hour(),
            old_datetime.minute(),
            old_datetime.second()
        );
        fs::write(&account_path, b"[]").expect("empty resume account snapshot");
        let state = AppState::new(AppConfig {
            version: "image-task-resume-timestamp".to_owned(),
            auth_key: Some("admin".to_owned()),
            models: Vec::new(),
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("resume task state");
        fs::write(
            &task_path,
            serde_json::to_vec(&json!({"tasks":[{
                "id":"resume-timeout-task",
                "owner_id":"admin",
                "status":"error",
                "mode":"generate",
                "model":"gpt-image-2",
                "prompt":"draw a cat",
                "conversation_id":"resume-timeout-conversation",
                "error":"generation 超时",
                "created_at":recent_task_timestamp,
                "updated_at":old_updated_at,
                "created_ts":old_task_ts,
                "updated_ts":old_task_ts
            }]}))
            .expect("resume task JSON"),
        )
        .expect("resume task snapshot");
        let response = management_request(
            &state,
            "POST",
            "/api/image-tasks/resume-timeout-task/resume-poll",
            Some(json!({"extra_timeout_secs":5})),
            Some("admin"),
        )
        .await;
        let response_status = response.status();
        let response_body = json_response(response).await;
        assert_eq!(
            response_status,
            StatusCode::OK,
            "resume response: {response_body}"
        );
        let resumed = response_body;
        assert_eq!(resumed["status"], "running");
        assert_ne!(resumed["updated_at"], old_updated_at);
        let persisted: Value =
            serde_json::from_slice(&fs::read(&task_path).expect("resumed task snapshot"))
                .expect("resumed task JSON");
        let persisted = persisted["tasks"][0].clone();
        assert!(persisted["updated_ts"].as_f64().unwrap() > old_task_ts);
        let duplicate_resume = management_request(
            &state,
            "POST",
            "/api/image-tasks/resume-timeout-task/resume-poll",
            Some(json!({"extra_timeout_secs":5})),
            Some("admin"),
        )
        .await;
        assert_eq!(duplicate_resume.status(), StatusCode::BAD_REQUEST);

        state.account_type_catalog.shutdown().await;
        drop(state);
        fs::remove_dir_all(root).expect("resume timestamp cleanup");
    }

