        let stale_bytes = b"preexisting temp canary";
        fs::write(&stale_temp, stale_bytes).expect("stale temp");
        *IMAGE_TAG_TEMP_PATH_OVERRIDE
            .lock()
            .expect("temp path override") = Some(stale_temp.clone());
