    #[tokio::test]
    async fn anthropic_messages_direct_openai_routes_prepend_global_system_prompt() {
        let captured_chat = Arc::new(Mutex::new(None::<Value>));
        let captured_chat_for_upstream = captured_chat.clone();
        let captured_responses = Arc::new(Mutex::new(None::<Value>));
        let captured_responses_for_upstream = captured_responses.clone();
        let chat = post(move |Json(payload): Json<Value>| {
            let captured = captured_chat_for_upstream.clone();
            async move {
                *captured.lock().await = Some(payload);
                Json(json!({
                    "choices":[{"message":{"role":"assistant","content":"chat answer"},"finish_reason":"stop"}],
                    "usage":{"prompt_tokens":1,"completion_tokens":1}
                }))
            }
        });
        let responses = post(move |Json(payload): Json<Value>| {
            let captured = captured_responses_for_upstream.clone();
            async move {
                *captured.lock().await = Some(payload);
                Json(json!({
                    "output":[{"type":"message","content":[{"type":"output_text","text":"responses answer","annotations":[]}]}],
                    "usage":{"input_tokens":1,"output_tokens":1}
                }))
            }
        });
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let upstream_task = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new()
                    .route("/ready", get(|| async { StatusCode::NO_CONTENT }))
                    .route("/v1/chat/completions", post(chat))
                    .route("/v1/responses", post(responses)),
            )
            .await
            .expect("upstream server");
        });
        let account_path = account_snapshot_path("anthropic-global-system-prompt");
        let data_dir = account_path.parent().expect("data directory").to_owned();
        fs::write(&account_path, "[]").expect("account snapshot");
        fs::write(
            data_dir.join("config.json"),
            br#"{"global_system_prompt":"global policy"}"#,
        )
        .expect("runtime config");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        wait_for_test_http_ready(&format!("http://{address}"), "/ready").await;

        let chat_response = state
            .router()
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","max_tokens":8,"system":[{"type":"text","text":"request "},{"type":"input_text","text":"system"},{"type":"thinking","thinking":"ignored"}],"messages":[{"role":"user","content":"hello"}]}"#,
                    ))
                    .expect("Anthropic Chat request"),
            )
            .await
            .expect("Anthropic Chat response");
        assert_eq!(chat_response.status(), StatusCode::OK);
        let chat_payload = captured_chat.lock().await.clone().expect("Chat payload");
        assert_eq!(chat_payload["messages"][0]["role"], "system");
        assert_eq!(chat_payload["messages"][0]["content"], "global policy");
        assert_eq!(chat_payload["messages"][1]["role"], "system");
        assert_eq!(chat_payload["messages"][1]["content"], "request system");
        assert_eq!(chat_payload["messages"][2]["role"], "user");

        let prompt_response = state
            .router()
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[],"prompt":"prompt only"}"#,
                    ))
                    .expect("prompt-only Chat request"),
            )
            .await
            .expect("prompt-only Chat response");
        assert_eq!(prompt_response.status(), StatusCode::OK);
        let prompt_payload = captured_chat.lock().await.clone().expect("prompt payload");
        assert_eq!(prompt_payload["messages"][0]["role"], "system");
        assert_eq!(prompt_payload["messages"][0]["content"], "global policy");
        assert_eq!(prompt_payload["messages"][1]["role"], "user");
        assert_eq!(prompt_payload["messages"][1]["content"], "prompt only");

        let duplicate_system_response = state
            .router()
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","max_tokens":8,"system":"global policy","messages":[{"role":"user","content":"hello"}]}"#,
                    ))
                    .expect("duplicate system request"),
            )
            .await
            .expect("duplicate system response");
        assert_eq!(duplicate_system_response.status(), StatusCode::OK);
        let duplicate_payload = captured_chat
            .lock()
            .await
            .clone()
            .expect("duplicate system payload");
        assert_eq!(duplicate_payload["messages"][0]["content"], "global policy");
        assert_eq!(duplicate_payload["messages"][1]["content"], "global policy");

        let tool_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","max_tokens":8,"system":[{"type":"text","text":"request "},{"type":"output_text","text":"system"}],"tools":[{"type":"web_search_20250305","name":"web_search"}],"messages":[{"role":"user","content":"find this"}]}"#,
                    ))
                    .expect("Anthropic Responses request"),
            )
            .await
            .expect("Anthropic tool response");
        assert_eq!(tool_response.status(), StatusCode::OK);
        let tool_payload = captured_chat
            .lock()
            .await
            .clone()
            .expect("tool Chat payload");
        assert_eq!(tool_payload["messages"][0]["content"], "global policy");
        assert!(
            tool_payload["messages"][1]["content"]
                .as_str()
                .unwrap_or_default()
                .starts_with("request systemAvailable tools:\nTool: web_search")
        );
        assert_eq!(tool_payload["messages"][2]["content"], "find this");
        assert!(tool_payload.get("tools").is_none());
        assert!(captured_responses.lock().await.is_none());

        let image_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","system":"look at this","messages":[{"role":"user","content":[{"type":"text","text":"describe"},{"type":"image","source":{"type":"base64","media_type":"image/png","data":"AQI="}}]}]}"#,
                    ))
                    .expect("Anthropic image request"),
            )
            .await
            .expect("Anthropic image response");
        assert_eq!(image_response.status(), StatusCode::OK);
        let image_payload = captured_chat
            .lock()
            .await
            .clone()
            .expect("image Chat payload");
        let user_message = image_payload["messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|message| message["role"] == "user")
            .expect("user image message");
        assert_eq!(user_message["content"][0]["type"], "text");
        assert_eq!(user_message["content"][0]["text"], "describe");
        assert_eq!(user_message["content"][1]["type"], "image_url");
        assert_eq!(
            user_message["content"][1]["image_url"]["url"],
            "data:image/png;base64,AQI="
        );
        assert!(captured_responses.lock().await.is_none());

        state.account_type_catalog.shutdown().await;
        upstream_task.abort();
        let _ = upstream_task.await;
        let _ = fs::remove_dir_all(data_dir);
    }

