    #[tokio::test]
    async fn anthropic_messages_route_projects_stream_events() {
        let upstream = post(|| async {
            (
                [(header::CONTENT_TYPE, "text/event-stream")],
                Body::from(
                    "data: {\"choices\":[{\"delta\":{\"role\":\"assistant\",\"content\":\"hi\"},\"finish_reason\":null}]}\n\n"
                        .to_owned()
                        + "data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}\n\n",
                ),
            )
                .into_response()
        });
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let upstream_task = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new().route("/v1/chat/completions", post(upstream)),
            )
            .await
            .expect("upstream server");
        });
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        let response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","max_tokens":8,"stream":true,"messages":[{"role":"user","content":"hello"}]}"#,
                    ))
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(response.status(), StatusCode::OK);
        let body = response
            .into_body()
            .collect()
            .await
            .expect("body")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("sse");
        let start = text.find("event: message_start").expect("message start");
        let block_start = text
            .find("event: content_block_start")
            .expect("block start");
        let delta = text.find("event: content_block_delta").expect("text delta");
        let block_stop = text.find("event: content_block_stop").expect("block stop");
        let message_delta = text.find("event: message_delta").expect("message delta");
        let message_stop = text.find("event: message_stop").expect("message stop");
        assert!(start < block_start && block_start < delta && delta < block_stop);
        assert!(block_stop < message_delta && message_delta < message_stop);
        assert!(text.contains("text_delta"));
        upstream_task.abort();
    }

    #[tokio::test]
    async fn anthropic_messages_route_projects_tool_stream_and_rejects_early_done() {
        let upstream = post(|| async {
            (
                [(header::CONTENT_TYPE, "text/event-stream")],
                Body::from(
                    r##"data: {"choices":[{"delta":{"role":"assistant","content":"lead<tool_calls><tool_call><tool_name>lookup</tool_name><parameters>{\"q\":"},"finish_reason":null}]}

data: {"choices":[{"delta":{"content":" \"rust\"}</parameters></tool_call></tool_calls>"},"finish_reason":null}]}

data: {"choices":[{"delta":{},"finish_reason":"stop"}]}

data: [DONE]

"##,
                ),
            )
                .into_response()
        });
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let upstream_task = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new().route("/v1/chat/completions", post(upstream)),
            )
            .await
            .expect("upstream server");
        });
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        let response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","max_tokens":8,"stream":true,"tools":[{"name":"lookup","input_schema":{"type":"object"}}],"tool_choice":{"type":"auto"},"messages":[{"role":"user","content":"lookup"}]}"#,
                    ))
                    .expect("request"),
            )
            .await
            .expect("response");
        let body = response
            .into_body()
            .collect()
            .await
            .expect("tool stream body")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("sse");
        let mut started = HashSet::new();
        let mut stopped = HashSet::new();
        let mut saw_text = false;
        let mut saw_tools = HashSet::new();
        let mut saw_message_delta = false;
        for frame in text.split("\n\n").filter(|frame| !frame.is_empty()) {
            let (event, data) = frame.split_once("\ndata: ").expect("event/data frame");
            let value: Value = serde_json::from_str(data).expect("event json");
            match event.strip_prefix("event: ").expect("event name") {
                "message_start" => assert!(started.is_empty()),
                "content_block_start" => {
                    let index = value["index"].as_u64().expect("block index");
                    assert!(started.insert(index));
                    assert!(!stopped.contains(&index));
                    match value["content_block"]["type"].as_str() {
                        Some("text") => saw_text = true,
                        Some("tool_use") => {
                            saw_tools.insert(index);
                        }
                        other => panic!("unexpected content block: {other:?}"),
                    }
                }
                "content_block_delta" => {
                    let index = value["index"].as_u64().expect("delta index");
                    assert!(started.contains(&index));
                    assert!(!stopped.contains(&index));
                }
                "content_block_stop" => {
                    let index = value["index"].as_u64().expect("stop index");
                    assert!(started.contains(&index));
                    assert!(stopped.insert(index));
                }
                "message_delta" => {
                    assert_eq!(started, stopped);
                    assert_eq!(value["delta"]["stop_reason"], "tool_use");
                    saw_message_delta = true;
                }
                "message_stop" => {
                    assert!(saw_message_delta);
                    assert_eq!(started, stopped);
                }
                other => panic!("unexpected event: {other}"),
            }
        }
        assert!(saw_text);
        assert_eq!(saw_tools.len(), 1);
        assert_eq!(started.len(), 2);
        assert!(text.contains("text_delta"));
        upstream_task.abort();

        let early_done = post(|| async {
            (
                [(header::CONTENT_TYPE, "text/event-stream")],
                Body::from("data: [DONE]\n\n"),
            )
                .into_response()
        });
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let upstream_task = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new().route("/v1/chat/completions", post(early_done)),
            )
            .await
            .expect("upstream server");
        });
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        let response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "secret")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","max_tokens":8,"stream":true,"messages":[{"role":"user","content":"lookup"}]}"#,
                    ))
                    .expect("request"),
            )
            .await
            .expect("response");
        let body = response
            .into_body()
            .collect()
            .await
            .expect("Anthropic early-done stream")
            .to_bytes();
        let body = String::from_utf8(body.to_vec()).expect("Anthropic early-done SSE");
        assert!(!body.contains("event: error\n"));
        assert!(body.contains("event: message_start\n"));
        assert!(body.contains("event: message_stop\n"));
        upstream_task.abort();
    }

    #[tokio::test]
    async fn anthropic_stream_malformed_frames_emit_python_error_envelope_and_partial_xml_as_text()
    {
        let malformed = anthropic_stream_body_response(
            Body::from(
                "data: {\"choices\":[{\"delta\":{\"content\":\"ok\"},\"finish_reason\":null}]}\n\n\
                 data: {not-json}\n\n\
                 data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}\n\n",
            ),
            "gpt-test".to_owned(),
            Instant::now() + Duration::from_secs(1),
        );
        let malformed = malformed
            .into_body()
            .collect()
            .await
            .expect("Anthropic stream errors become an SSE event")
            .to_bytes();
        let malformed = String::from_utf8(malformed.to_vec()).expect("Anthropic SSE");
        assert!(malformed.contains("event: error\n"));
        assert!(malformed.contains(r#""type":"RuntimeError""#));
        assert!(malformed.contains("Anthropic stream contained malformed JSON"));

        let partial_xml = anthropic_stream_body_response_with_options(
            Body::from(
                r#"data: {"choices":[{"delta":{"content":"<tool_calls><tool_call><tool_name>lookup</tool_name><parameters>{\"q\":"},"finish_reason":null}]}

data: {"choices":[{"delta":{},"finish_reason":"stop"}]}

"#,
            ),
            "gpt-test".to_owned(),
            Instant::now() + Duration::from_secs(1),
            true,
            0,
        );
        let partial_xml = partial_xml
            .into_body()
            .collect()
            .await
            .expect("Python does not reject unparsable XML tool output")
            .to_bytes();
        let partial_xml = String::from_utf8(partial_xml.to_vec()).expect("SSE");
        assert!(partial_xml.contains("\"stop_reason\":\"end_turn\""));
        assert!(!partial_xml.contains("\"type\":\"tool_use\""));
    }

    #[tokio::test]
    async fn anthropic_stream_ignores_native_tool_calls_and_upstream_finish_reason() {
        let text_then_tool_finish = anthropic_stream_body_response_with_options(
            Body::from(
                "data: {\"choices\":[{\"delta\":{\"content\":\"text\"},\"finish_reason\":null}]}\n\n\
                 data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"tool_calls\"}]}\n\n",
            ),
            "gpt-test".to_owned(),
            Instant::now() + Duration::from_secs(1),
            true,
            0,
        );
        let text = text_then_tool_finish
            .into_body()
            .collect()
            .await
            .expect("Python determines stop reason from parsed XML, not finish_reason")
            .to_bytes();
        assert!(String::from_utf8_lossy(&text).contains("\"stop_reason\":\"end_turn\""));

        let native_tool_call = anthropic_stream_body_response_with_options(
            Body::from(
                "data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"id\":\"toolu_1\",\"type\":\"function\",\"function\":{\"name\":\"lookup\",\"arguments\":\"{}\"}}]},\"finish_reason\":null}]}\n\n\
                 data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}\n\n",
            ),
            "gpt-test".to_owned(),
            Instant::now() + Duration::from_secs(1),
            true,
            0,
        );
        let text = native_tool_call
            .into_body()
            .collect()
            .await
            .expect("Python ignores native function_call deltas")
            .to_bytes();
        let text = String::from_utf8_lossy(&text);
        assert!(text.contains("\"stop_reason\":\"end_turn\""));
        assert!(!text.contains("\"type\":\"tool_use\""));
    }

    #[test]
    fn anthropic_conversion_uses_xml_tool_prompt_and_ignores_native_tool_calls() {
        let request = validate_message_request(json!({
            "model":"gpt-test",
            "max_tokens":8,
            "tools":[{"name":"lookup","description":"find values","input_schema":{"type":"object","properties":{"q":{"type":"string"}}}}],
            "messages":[
                {"role":"assistant","content":[
                    {"type":"text","text":"before"},
                    {"type":"tool_use","id":"toolu_1","name":"lookup","input":{"q":"rust"}}
                ]}
            ]
        }))
        .expect("request");
        let payload = to_chat_payload(&request).expect("payload");
        assert!(payload["messages"][0]["content"]
            .as_str()
            .unwrap_or_default()
            .contains("Available tools:\nTool: lookup\nDescription: find values\nParameters: {\"type\": \"object\", \"properties\": {\"q\": {\"type\": \"string\"}}}"));
        assert!(payload.get("tools").is_none());
        assert!(payload.get("tool_choice").is_none());
        assert_eq!(
            payload["messages"][1]["content"],
            "before<tool_calls><tool_call><tool_name>lookup</tool_name><parameters>{\"q\": \"rust\"}</parameters></tool_call></tool_calls>"
        );

        let valid = from_chat_response(
            br#"{"choices":[{"message":{"role":"assistant","content":"before<tool_calls><tool_call><tool_name>lookup</tool_name><parameters><![CDATA[{\"q\":\"rust\"}]]></parameters></tool_call></tool_calls>","tool_calls":[{"id":"ignored","type":"function","function":{"name":"lookup","arguments":"{}"}}]},"finish_reason":"length"}]}"#,
            "gpt-test",
            true,
            0,
        )
        .expect("valid mixed response");
        assert_eq!(valid["content"][0]["text"], "before");
        assert_eq!(valid["content"][1]["input"]["q"], "rust");
        assert!(
            valid["content"][1]["id"]
                .as_str()
                .unwrap_or_default()
                .starts_with("toolu_")
        );
        assert_eq!(valid["stop_reason"], "tool_use");

        let native_only = br#"{"choices":[{"message":{"role":"assistant","content":null,"tool_calls":[{"id":"call-1","type":"function","function":{"name":"lookup","arguments":"{}"}}]},"finish_reason":"tool_calls"}]}"#;
        let ignored = from_chat_response(native_only, "gpt-test", true, 0)
            .expect("Python collects text only and ignores native tool-call fields");
        assert_eq!(ignored["content"], json!([{"type":"text","text":""}]));
        assert_eq!(ignored["stop_reason"], "end_turn");
        let unknown_finish = br#"{"choices":[{"message":{"role":"assistant","content":"plain"},"finish_reason":"vendor_new_reason"}]}"#;
        assert_eq!(
            from_chat_response(unknown_finish, "gpt-test", false, 0).expect("finish ignored")["stop_reason"],
            "end_turn"
        );
    }
