    #[test]
    fn anthropic_standard_images_and_web_search_convert_to_chat_conversation() {
        let request = validate_message_request(json!({
            "model":"gpt-test",
            "max_tokens":8,
            "tools":[{"type":"web_search_20250305","name":"web_search"}],
            "messages":[{"role":"user","content":[
                {"type":"text","text":"find this"},
                {"type":"image","source":{"type":"base64","media_type":"image/png","data":"AQI="}}
            ]}]
        }))
        .expect("standard image/search request");
        let payload = to_chat_payload(&request).expect("chat payload");
        assert!(payload.get("max_tokens").is_none());
        assert!(payload.get("tools").is_none());
        assert!(
            payload["messages"][0]["content"]
                .as_str()
                .unwrap_or_default()
                .contains("Tool: web_search")
        );
        assert_eq!(payload["messages"][1]["role"], "user");
        assert_eq!(payload["messages"][1]["content"][0]["type"], "text");
        assert_eq!(payload["messages"][1]["content"][1]["type"], "image_url");
        assert_eq!(
            payload["messages"][1]["content"][1]["image_url"]["url"],
            "data:image/png;base64,AQI="
        );
        assert_eq!(
            native_chat_message_image_values(&payload["messages"][1]).expect("native image values"),
            ["data:image/png;base64,AQI="]
        );

        let extra_search_options = validate_message_request(json!({
            "model":"gpt-test",
            "max_tokens":8,
            "tools":[{"type":"web_search_20250305","name":"web_search","max_uses":1}],
            "messages":[{"role":"user","content":"find this"}]
        }))
        .expect("Anthropic extra tools are not nested-validated by Pydantic");
        assert!(to_chat_payload(&extra_search_options)
            .expect("tool prompt ignores unsupported extension fields")["messages"][0]["content"]
            .as_str()
            .unwrap_or_default()
            .contains("Tool: web_search"));

        for (field, value) in [
            ("temperature", json!(0.2)),
            ("top_p", json!(0.8)),
            ("top_k", json!(20)),
            ("stop_sequences", json!(["END"])),
            ("metadata", json!({"request_id":"test"})),
        ] {
            let mut payload = json!({
                "model":"gpt-test",
                "max_tokens":8,
                "messages":[{"role":"user","content":"hello"}]
            });
            payload[field] = value;
            let request = validate_message_request(payload)
                .expect("Anthropic Pydantic model allows extra fields");
            assert!(
                to_chat_payload(&request)
                    .expect("extra fields are ignored by the message adapter")
                    .get(field)
                    .is_none()
            );
        }
    }

    #[test]
    fn anthropic_image_block_accepts_python_reference_shapes() {
        for (block, expected) in [
            (
                json!({"type":"image","image_url":"","url":"data:image/png;base64,AQI="}),
                "data:image/png;base64,AQI=",
            ),
            (
                json!({"type":"image","image_url":{"url":"data:image/png;base64,AQI="}}),
                "data:image/png;base64,AQI=",
            ),
            (
                json!({"type":"image","base64":"AQI=","mimeType":"IMAGE/JPG"}),
                "data:image/jpeg;base64,AQI=",
            ),
            (
                json!({"type":"image","b64_json":"AQI="}),
                "data:image/png;base64,AQI=",
            ),
        ] {
            let request = validate_message_request(json!({
                "model":"gpt-test",
                "max_tokens":8,
                "messages":[{"role":"user","content":[block]}]
            }))
            .expect("image reference shape");
            let payload = to_chat_payload(&request).expect("chat payload");
            assert_eq!(
                native_chat_message_image_values(&payload["messages"][0])
                    .expect("native image value"),
                [expected.to_owned()]
            );
        }
        let image_url_only = validate_message_request(json!({
            "model":"gpt-test",
            "messages":[{"role":"user","content":[{
                "type":"image_url","b64_json":"AQI="
            }]}]
        }))
        .expect("image_url block");
        let payload = to_chat_payload(&image_url_only).expect("image_url chat payload");
        assert!(
            native_chat_message_image_values(&payload["messages"][0])
                .expect("image_url native values")
                .is_empty()
        );
    }

