    #[tokio::test]
    async fn health_matches_public_shape_without_auth() {
        let _health_test_serial = HEALTH_TEST_SERIAL.lock().await;
        let response = state(Some("secret"))
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/health?format=json")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(response.status(), StatusCode::OK);
        let body = response
            .into_body()
            .collect()
            .await
            .expect("body")
            .to_bytes();
        let value: Value = serde_json::from_slice(&body).expect("json");
        assert_eq!(value["status"], "degraded");
        assert_eq!(value["healthy"], false);
        assert_eq!(value["accounts"]["total"], 0);
        assert!(value["proxy_runtime"]["enabled"].is_boolean());

        let html = state(Some("secret"))
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/health")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(
            html.headers()[header::CONTENT_TYPE],
            "text/html; charset=utf-8"
        );
        let html_body = html
            .into_body()
            .collect()
            .await
            .expect("html body")
            .to_bytes();
        let html_body = String::from_utf8(html_body.to_vec()).expect("utf8 html");
        for marker in [
            "<!DOCTYPE html>",
            "号池健康监控",
            "当前账号",
            "账号类型分布",
            "30s 自动刷新",
            "/health?format=json",
        ] {
            assert!(html_body.contains(marker), "missing HTML marker: {marker}");
        }
    }

    #[test]
    fn public_storage_snapshot_fails_closed_for_malformed_type_and_has_stable_keys() {
        let info = json!({
            "type": {"canary": "secret"},
            "backend": "git",
            "repo_url": "https://secret.example/repo.git",
            "file_path": "accounts.json",
        });
        let healthy = json!({
            "status": "healthy",
            "sync_status": "fresh",
            "last_commit": "deadbeef",
        });
        let (public, is_healthy) = public_storage_snapshot(&info, &healthy);
        assert!(!is_healthy);
        assert_eq!(
            public,
            json!({
                "backend": "unknown",
                "health": {
                    "status": "unhealthy",
                    "error": "存储后端健康检查失败",
                },
            })
        );
        let object = public.as_object().expect("public storage object");
        assert_eq!(object.len(), 2);
        assert!(object.contains_key("backend"));
        assert!(object.contains_key("health"));
        assert!(!public.to_string().contains("secret"));
        assert!(!public.to_string().contains("deadbeef"));
        assert_eq!(
            public_storage_info(&info, &healthy),
            json!({
                "backend": {"type": "unknown"},
                "health": {
                    "status": "unhealthy",
                    "error": "存储后端健康检查失败",
                },
            })
        );
        let health_payload = health_payload_with_storage(
            &state(Some("health-secret")),
            json!({"active":1,"total":1}),
            (public, false),
        );
        assert_eq!(health_payload["status"], "ok");
        assert_eq!(health_payload["healthy"], true);
        assert_eq!(health_payload["storage"]["health"]["status"], "unhealthy");
    }

