    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn health_account_stats_are_bounded_off_event_loop() {
        let _health_test_serial = HEALTH_TEST_SERIAL.lock().await;
        let path = account_snapshot_path("health-account-bounded");
        fs::write(
            &path,
            r#"{"items":[{"access_token":"normal","status":"正常"}]}"#,
        )
        .expect("accounts snapshot");
        let hook = HealthBlockingTestHook {
            version: "health-account-bounded-test".to_owned(),
            started: Arc::new(Notify::new()),
            starts: Arc::new(AtomicUsize::new(0)),
            block: Arc::new(AtomicBool::new(true)),
        };
        *HEALTH_ACCOUNTS_TEST_HOOK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(hook.clone());
        let _cleanup = HealthHookCleanup {
            storage: false,
            accounts: true,
        };
        let state = AppState::new(AppConfig {
            version: hook.version.clone(),
            auth_key: None,
            models: vec!["auto".to_owned()],
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        let app = state.router();
        let mut request = tokio::spawn(async move {
            app.oneshot(
                axum::http::Request::builder()
                    .uri("/health?format=json")
                    .body(Body::empty())
                    .expect("health request"),
            )
            .await
            .expect("health response")
        });
        tokio::time::timeout(Duration::from_secs(2), hook.started.notified())
            .await
            .expect("account health statistics hook did not start within two seconds");
        let bounded = tokio::time::timeout(Duration::from_millis(700), &mut request).await;
        hook.block.store(false, Ordering::SeqCst);
        if bounded.is_err() {
            let _ = tokio::time::timeout(Duration::from_secs(2), request)
                .await
                .expect("blocked health task cleanup")
                .expect("blocked health task");
        }
        let _ = fs::remove_file(path);
        assert!(
            bounded.is_ok(),
            "account statistics and cumulative reads must not block the Tokio worker past the health deadline"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 8)]
    async fn models_and_chat_require_bearer() {
        let upstream_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("upstream listener");
        let upstream_address = upstream_listener.local_addr().expect("upstream address");
        let (ready_tx, ready_rx) = tokio::sync::oneshot::channel();
        let upstream = tokio::spawn(async move {
            let app = Router::new()
                .route("/__ready", get(|| async { StatusCode::NO_CONTENT }))
                .route("/", get(|| async { Html("<html></html>") }))
                .route(
                    "/backend-anon/models",
                    get(|| async { Json(json!({"models":[{"slug":"gpt-test"}]})) }),
                );
            let _ = ready_tx.send(());
            axum::serve(upstream_listener, app)
                .await
                .expect("upstream server");
        });
        ready_rx.await.expect("upstream failed before startup");
        let account_path = account_snapshot_path("models-chat-require-bearer");
        let data_dir = account_path.parent().expect("data directory").to_owned();
        fs::write(&account_path, b"[]").expect("empty account snapshot");
        fs::write(data_dir.join("config.json"), br#"{"proxy":""}"#)
            .expect("disable inherited test proxy");
        wait_for_test_http_ready(&format!("http://{upstream_address}"), "/__ready").await;
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["auto".to_owned(), "gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{upstream_address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let app = state.router();
        let models = app
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/v1/models")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(models.status(), StatusCode::UNAUTHORIZED);

        let authorized_models = app
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/v1/models")
                    .header(header::AUTHORIZATION, "Bearer secret")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(authorized_models.status(), StatusCode::OK);

        let padded_authorization = app
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/v1/models")
                    .header(header::AUTHORIZATION, "Bearer    secret  ")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(padded_authorization.status(), StatusCode::OK);

        let unauthorized = app
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"model":"auto","prompt":"x"}"#))
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(unauthorized.status(), StatusCode::UNAUTHORIZED);
        let body = unauthorized
            .into_body()
            .collect()
            .await
            .expect("body")
            .to_bytes();
        let value: Value = serde_json::from_slice(&body).expect("json");
        assert_eq!(value["error"]["code"], "invalid_api_key");
        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
        drop(state);
        fs::remove_dir_all(data_dir).expect("models/chat auth test cleanup");
    }

