    #[test]
    fn chat_request_accepts_pydantic_coercions_and_extra_fields() {
        let payload = validate_chat_payload(json!({
            "prompt":"x",
            "n":"2",
            "stream":"yes",
            "vendor_extension":{"enabled":true}
        }))
        .expect("Pydantic accepts coercible fields and extra values");
        assert_eq!(payload["n"], 2);
        assert_eq!(payload["stream"], true);
        assert_eq!(payload["vendor_extension"]["enabled"], true);

        let message = validate_chat_payload(json!({
            "messages":[{"role":"strange-role","content":["text",{"type":"unknown","text":"part"}],"extra":1}]
        }))
        .expect("Python messages are dictionaries without an inner schema");
        let conversation = native_conversation_payload(&message).expect("conversation payload");
        assert_eq!(
            conversation["messages"][0]["author"]["role"],
            "strange-role"
        );
        assert_eq!(
            conversation["messages"][0]["content"]["parts"],
            json!(["text"])
        );
    }

