    #[tokio::test]
    async fn auth_reload_singleflight_fences_old_publish_and_old_auth() {
        let path = test_tmp_dir().join(format!(
            "chatgpt2api-rust-auth-race-{}-{}.json",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        ));
        let hash = Sha256::digest(b"file-secret");
        let hash = hash
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let enabled_document = json!({
            "items": [
                {"id": "enabled", "role": "user", "key_hash": hash, "enabled": true}
            ]
        });
        let disabled_document = json!({
            "items": [
                {"id": "enabled", "role": "user", "key_hash": hash, "enabled": false}
            ]
        });
        fs::write(
            &path,
            serde_json::to_vec(&enabled_document).expect("enabled json"),
        )
        .expect("write enabled snapshot");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: None,
            models: vec!["auto".to_owned()],
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: Some(path.clone()),
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        fs::write(
            &path,
            serde_json::to_vec(&disabled_document).expect("disabled json"),
        )
        .expect("disable key");

        let hook = AuthReloadTestHook {
            pause_before_publish: Arc::new(AtomicBool::new(true)),
            read_complete: Arc::new(Notify::new()),
            release_publish: Arc::new(Notify::new()),
        };
        let read_complete = hook.read_complete.notified();
        state.auth_store.set_test_hook(Some(hook.clone()));
        let leader = tokio::spawn(route_chat_request(state.clone(), "file-secret"));
        read_complete.await;

        let mut follower = tokio::spawn(route_chat_request(state.clone(), "file-secret"));
        let follower_before_publish =
            tokio::time::timeout(Duration::from_millis(100), &mut follower).await;
        fs::write(
            &path,
            serde_json::to_vec(&enabled_document).expect("enabled json"),
        )
        .expect("restore newer snapshot");
        hook.release_publish.notify_one();

        let leader = leader.await.expect("leader task");
        let follower_was_pending = follower_before_publish.is_err();
        let follower = match follower_before_publish {
            Ok(result) => result.expect("follower task"),
            Err(_) => follower.await.expect("follower task"),
        };
        assert!(
            follower_was_pending,
            "follower used the old generation before leader publish"
        );
        assert_eq!(leader.status(), StatusCode::UNAUTHORIZED);
        assert_eq!(follower.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(state.auth_store.accepts("file-secret"));
        state.auth_store.set_test_hook(None);
        fs::remove_file(path).expect("cleanup");
    }

    #[tokio::test]
    async fn unknown_v1_routes_and_model_method_use_openai_errors() {
        let account_path = account_snapshot_path("unknown-v1-route-errors");
        fs::write(&account_path, b"[]").expect("empty account snapshot");
        let state = AppState::new(AppConfig {
            version: "unknown-v1-route-errors".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["auto".to_owned()],
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("route error state");
        assert!(!web_path_disables_spa_fallback("v1/unknown"));
        assert!(web_path_disables_spa_fallback("_next/static/missing.js"));
        assert!(!web_path_disables_spa_fallback("_next"));
        assert!(!web_path_disables_spa_fallback("health/missing"));
        assert!(!web_path_disables_spa_fallback("version/missing"));
        let next_missing = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/_next/static/missing.js")
                    .body(Body::empty())
                    .expect("missing Next asset request"),
            )
            .await
            .expect("missing Next asset response");
        assert_eq!(next_missing.status(), StatusCode::NOT_FOUND);
        assert_eq!(
            json_response(next_missing).await,
            json!({"detail": "Not Found"})
        );
        let normal_missing = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/unknown")
                    .body(Body::empty())
                    .expect("missing normal web request"),
            )
            .await
            .expect("missing normal web response");
        assert_eq!(normal_missing.status(), StatusCode::NOT_FOUND);
        assert_eq!(
            json_response(normal_missing).await,
            json!({"detail": "Not Found"})
        );

        let method_error = state
            .router()
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .method("PUT")
                    .uri("/v1/models")
                    .body(Body::empty())
                    .expect("method error request"),
            )
            .await
            .expect("method error response");
        assert_eq!(method_error.status(), StatusCode::METHOD_NOT_ALLOWED);
        let method_body = json_response(method_error).await;
        assert_eq!(method_body["error"]["message"], "Method Not Allowed");
        assert_eq!(method_body["error"]["type"], "invalid_request_error");
        assert_eq!(method_body["error"]["code"], "bad_request");

        let chat_method_error = state
            .router()
            .clone()
            .oneshot(
                axum::http::Request::builder()
                    .method("PUT")
                    .uri("/v1/chat/completions")
                    .body(Body::empty())
                    .expect("chat method error request"),
            )
            .await
            .expect("chat method error response");
        assert_eq!(chat_method_error.status(), StatusCode::METHOD_NOT_ALLOWED);
        let chat_method_body = json_response(chat_method_error).await;
        assert_eq!(chat_method_body["error"]["type"], "invalid_request_error");
        assert_eq!(chat_method_body["error"]["code"], "bad_request");

        let missing = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/unknown")
                    .body(Body::empty())
                    .expect("missing route request"),
            )
            .await
            .expect("missing route response");
        assert_eq!(missing.status(), StatusCode::METHOD_NOT_ALLOWED);
        let missing_body = json_response(missing).await;
        assert_eq!(
            missing_body,
            json!({"error": {
                "message": "Method Not Allowed",
                "type": "invalid_request_error",
                "param": null,
                "code": "bad_request"
            }})
        );
        let non_v1_missing = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/unknown")
                    .body(Body::empty())
                    .expect("non-v1 method request"),
            )
            .await
            .expect("non-v1 method response");
        assert_eq!(non_v1_missing.status(), StatusCode::METHOD_NOT_ALLOWED);
        assert_eq!(
            json_response(non_v1_missing).await,
            json!({"detail": "Method Not Allowed"})
        );
        state.account_type_catalog.shutdown().await;
        drop(state);
        fs::remove_file(account_path).expect("cleanup");
    }

