    #[test]
    fn account_canonicalization_matches_python_legacy_alias_plan_and_quota() {
        let canonical = canonicalize_account_item(&json!({
            "accessToken":"legacy-alias",
            "type":"Pro",
            "status":"",
            "quota":"3_000",
            "success":"1_2",
            "restore_at":"",
            "email":"",
            "proxy":17,
            "last_invalid_at":"",
            "last_refresh_error":"",
            "last_refresh_error_at":"",
            "last_token_refresh_at":"",
            "last_token_refresh_error":"",
            "last_token_refresh_error_at":"",
            "limits_progress":"invalid"
        }))
        .expect("Python-compatible account canonicalization");
        assert_eq!(canonical["access_token"], "legacy-alias");
        assert_eq!(canonical["type"], "Pro");
        assert_eq!(canonical["status"], "正常");
        assert_eq!(canonical["quota"], 3_000);
        assert_eq!(canonical["success"], 12);
        assert_eq!(canonical["proxy"], "17");
        assert!(canonical["restore_at"].is_null());
        assert!(canonical["email"].is_null());
        for key in [
            "last_invalid_at",
            "last_refresh_error",
            "last_refresh_error_at",
            "last_token_refresh_at",
            "last_token_refresh_error",
            "last_token_refresh_error_at",
        ] {
            assert!(
                canonical[key].is_null(),
                "field {key} should normalize to null"
            );
        }
        assert_eq!(canonical["limits_progress"], json!([]));

        let codex = canonicalize_account_item(&json!({
            "access_token":"codex-alias",
            "type":"Codex"
        }))
        .expect("legacy Codex account");
        assert_eq!(codex["type"], "free");
        assert_eq!(codex["export_type"], "codex");
        assert_eq!(codex["source_type"], "codex");

        let source_case = canonicalize_account_item(&json!({
            "access_token":"source-case",
            "source_type":" CoDeX "
        }))
        .expect("Python source type normalization");
        assert_eq!(source_case["source_type"], "codex");

        let unicode_source = canonicalize_account_item(&json!({
            "access_token":"unicode-source",
            "source_type":"ÄBC"
        }))
        .expect("Unicode source type lowercasing");
        assert_eq!(unicode_source["source_type"], "äbc");

        let whitespace_source = canonicalize_account_item(&json!({
            "access_token":"whitespace-source",
            "type":"Codex",
            "source_type":"   "
        }))
        .expect("truthy whitespace source type follows Python normalization");
        assert_eq!(whitespace_source["type"], "free");
        assert_eq!(whitespace_source["source_type"], "web");

        for falsey_type in [
            Value::Null,
            json!(false),
            json!(0),
            json!(""),
            json!([]),
            json!({}),
        ] {
            let account = canonicalize_account_item(&json!({
                "access_token":"falsey-account-type",
                "type":falsey_type
            }))
            .expect("falsey Python account type defaults to free");
            assert_eq!(account["type"], "free");
        }

        let whitespace_type = canonicalize_account_item(&json!({
            "access_token":"whitespace-account-type",
            "type":"   "
        }))
        .expect("truthy whitespace account type is preserved");
        assert_eq!(whitespace_type["type"], "   ");
        let (_, records, _) = parse_account_document_bytes(
            &serde_json::to_vec(&json!([whitespace_type])).expect("whitespace type snapshot"),
        )
        .expect("Python allows an account with an unrecognized whitespace type");
        assert_eq!(records[0].account_type, "");
    }

    #[test]
    fn positive_image_quota_persists_image_model_for_imported_accounts() {
        let mut refreshed = json!({
            "access_token": "account-token",
            "source_type": "codex",
            "type": "pro",
            "quota": "3",
            "_model_source_version": 1,
            "_verified_web_model_paths": [AUTHENTICATED_NATIVE_MODEL_PATHS[0]],
            "_verified_image_capability": true,
            "models": ["gpt-5-5", "gpt-image-2", "gpt-image-2.5"]
            ,"model_sources":{"gpt-5-5":"web","gpt-image-2":"image","gpt-image-2.5":"image"}
        });
        ensure_image_model_snapshot(&mut refreshed);
        let canonical = canonicalize_account_item(&refreshed).expect("canonical account");
        assert_eq!(
            canonical["models"],
            json!([
                "gpt-5-5",
                "gpt-image-2",
                "gpt-image-2.5",
                "gpt-image-2.5-flare",
                "gpt-image-2.5-sunburst"
            ])
        );
        assert_eq!(canonical["model_sources"]["gpt-image-2"], "image");
        assert_eq!(canonical["model_sources"]["gpt-image-2.5"], "image");
        assert_eq!(canonical["model_sources"]["gpt-image-2.5-flare"], "image");
        assert_eq!(
            canonical["model_sources"]["gpt-image-2.5-sunburst"],
            "image"
        );

        let mut capability_only = json!({
            "access_token": "account-token",
            "source_type": "codex",
            "type": "pro",
            "quota": 3
        });
        ensure_image_model_snapshot(&mut capability_only);
        assert_eq!(
            capability_only["models"],
            json!([
                "gpt-image-2",
                "gpt-image-2.5",
                "gpt-image-2.5-flare",
                "gpt-image-2.5-sunburst"
            ])
        );
        assert_eq!(capability_only["model_sources"]["gpt-image-2"], "image");

        let without_quota = canonicalize_account_item(&json!({
            "access_token": "account-token",
            "source_type": "codex",
            "type": "pro",
            "quota": 0,
            "models": ["gpt-5-5"]
        }))
        .expect("canonical account without image quota");
        assert!(
            !without_quota["models"]
                .as_array()
                .is_some_and(|models| models.iter().any(|model| model == "gpt-image-2"))
        );
    }

