    #[test]
    fn refresh_invalid_token_deferral_matches_python_time_windows() {
        let now = time::OffsetDateTime::from_unix_timestamp(1_800_000_000).expect("test time");
        let timestamp = |value: time::OffsetDateTime| {
            Value::String(
                value
                    .format(&time::format_description::well_known::Rfc3339)
                    .expect("RFC3339 timestamp"),
            )
        };
        let old = timestamp(now - time::Duration::hours(1));
        let fresh = timestamp(now - time::Duration::seconds(599));
        let grace_elapsed = timestamp(now - time::Duration::seconds(600));
        let recent = timestamp(now - time::Duration::seconds(29));
        let confirmation_elapsed = timestamp(now - time::Duration::seconds(30));

        assert!(invalid_token_should_defer(
            &json!({"created_at": fresh, "invalid_count": 5}),
            now,
            true,
        ));
        assert!(invalid_token_should_defer(
            &json!({"created_at": old, "invalid_count": 1}),
            now,
            true,
        ));
        assert!(invalid_token_should_defer(
            &json!({"created_at": old, "invalid_count": 2, "last_invalid_at": recent}),
            now,
            true,
        ));
        assert!(!invalid_token_should_defer(
            &json!({"created_at": grace_elapsed, "invalid_count": 2}),
            now,
            true,
        ));
        assert!(!invalid_token_should_defer(
            &json!({"created_at": old, "invalid_count": 2, "last_invalid_at": confirmation_elapsed}),
            now,
            true,
        ));
        assert!(!invalid_token_should_defer(
            &json!({"created_at": fresh, "invalid_count": 0}),
            now,
            false,
        ));
        assert!(!invalid_token_should_defer(
            &json!({"created_at": old, "invalid_count": "2"}),
            now,
            true,
        ));
        assert!(!invalid_token_should_defer(
            &json!({"created_at": old, "invalid_count": "1_2"}),
            now,
            true,
        ));
        assert!(!invalid_token_should_defer(
            &json!({"created_at": old, "invalid_count": "1_0"}),
            now,
            true,
        ));
        assert!(refresh_result_removes_account(
            Some(&json!({
                "created_at": old,
                "invalid_count": 3,
                "last_invalid_at": confirmation_elapsed
            })),
            &Err("invalid_token"),
            true,
            false,
            true,
            now,
        ));
        assert!(!refresh_result_removes_account(
            Some(&json!({"created_at":fresh,"invalid_count":3})),
            &Err("invalid_token"),
            true,
            false,
            true,
            now,
        ));
    }

