    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn public_models_merge_authenticated_web_catalog() {
        let account_path = account_snapshot_path("public-model-list");
        fs::write(
            &account_path,
            r#"[
                {"access_token":"web-free","status":"正常","source_type":"web","type":"free","quota":1,"_verified_image_capability":true},
                {"access_token":"web-plus","status":"正常","source_type":"web","type":"plus","quota":1,"_verified_image_capability":true}
            ]"#
            .as_bytes(),
        )
        .expect("account snapshot");
        let calls = Arc::new(Mutex::new(Vec::<String>::new()));
        let calls_for_upstream = calls.clone();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("model upstream listener");
        let address = listener.local_addr().expect("model upstream address");
        let (ready_tx, ready_rx) = tokio::sync::oneshot::channel();
        let mut upstream = tokio::spawn(async move {
            let root = get(|| async { Html("<html></html>") });
            let anonymous_models = get(move |headers: HeaderMap, uri: axum::http::Uri| {
                let calls = calls_for_upstream.clone();
                async move {
                    assert!(headers.get(header::AUTHORIZATION).is_none());
                    calls.lock().await.push(uri.to_string());
                    Json(json!({
                        "models": [
                            {"slug":"z-model","created":9,"owned_by":"owner-z"},
                            {"slug":"a-model","created":3,"owned_by":"owner-a"},
                            {"slug":"a-model","created":99,"owned_by":"duplicate"}
                        ]
                    }))
                }
            });
            let app = Router::new()
                .route("/__ready", get(|| async { StatusCode::NO_CONTENT }))
                .route("/", root)
                .route("/backend-anon/models", anonymous_models)
                .route(
                    "/backend-api/models",
                    get(|| async {
                        Json(json!({"models":[
                            {"slug":"gpt-5-5"}, {"slug":"gpt-5-6"}, {"slug":"gpt-5-3-mini"},
                            {"slug":"gpt-5-5-mini"}, {"slug":"gpt-5-6-mini"}, {"slug":"gpt-5-6-t-mini"},
                            {"slug":"gpt-5-6-t-mini-mini"}, {"slug":"research"}, {"slug":"gpt-6"},
                            {"slug":"gpt-6-t-mini"}, {"slug":"gpt-6-mini"}, {"slug":"gpt-6-t-mini-mini"},
                            {"slug":"auto"}
                        ]}))
                    }),
                );
            let _ = ready_tx.send(());
            axum::serve(listener, app).await.expect("model upstream");
        });
        ready_rx
            .await
            .expect("model upstream failed before startup");

        let upstream_base = format!("http://{address}");
        tokio::select! {
            () = wait_for_test_http_ready(&upstream_base, "/__ready") => {}
            result = &mut upstream => panic!("anonymous model mock exited before readiness: {result:?}"),
        }
        let state = AppState::new(AppConfig {
            version: "v17-model-list-contract".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["static-model".to_owned()],
            upstream_base_url: Some(upstream_base),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/v1/models")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .body(Body::empty())
                    .expect("models request"),
            )
            .await
            .expect("models response");
        let response_status = response.status();
        let body = response
            .into_body()
            .collect()
            .await
            .expect("models body")
            .to_bytes();
        assert_eq!(
            response_status,
            StatusCode::OK,
            "models body={}; mock calls={:?}; upstream finished={}",
            String::from_utf8_lossy(&body),
            calls.lock().await.as_slice(),
            upstream.is_finished()
        );
        let value: Value = serde_json::from_slice(&body).expect("models JSON");
        let ids = value["data"]
            .as_array()
            .expect("public model data")
            .iter()
            .map(|item| item["id"].as_str().expect("model id"))
            .collect::<Vec<_>>();
        assert_eq!(
            ids,
            vec![
                "auto",
                "gpt-5-3-mini",
                "gpt-5-5",
                "gpt-5-5-mini",
                "gpt-5-6",
                "gpt-5-6-mini",
                "gpt-5-6-t-mini",
                "gpt-5-6-t-mini-mini",
                "gpt-6",
                "gpt-6-mini",
                "gpt-6-t-mini",
                "gpt-6-t-mini-mini",
                "gpt-image-2",
                "gpt-image-2.5",
                "gpt-image-2.5-flare",
                "gpt-image-2.5-sunburst",
                "research",
            ]
        );
        assert!(value["data"].as_array().unwrap().iter().any(|item| {
            item["id"] == "gpt-5-5"
                && item["supported_account_types"]
                    .as_array()
                    .is_some_and(|types| types.iter().any(|value| value == "free"))
        }));
        assert_eq!(
            calls.lock().await.as_slice(),
            ["/backend-anon/models?iim=false&is_gizmo=false"]
        );

        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
        let _ = fs::remove_file(account_path);
    }

