    #[tokio::test]
    async fn chat_forwards_to_configured_upstream_for_both_modes() {
        async fn upstream(headers: HeaderMap, Json(payload): Json<Value>) -> Response {
            assert_eq!(
                headers
                    .get(header::AUTHORIZATION)
                    .and_then(|value| value.to_str().ok()),
                Some("Bearer upstream-secret")
            );
            assert_eq!(payload.get("model").and_then(Value::as_str), Some("auto"));
            if payload.get("reasoning_effort").is_some() {
                assert_eq!(
                    payload.get("reasoning_effort").and_then(Value::as_str),
                    Some("auto")
                );
            }
            if payload.get("stream").and_then(Value::as_bool) == Some(true) {
                (
                    [(header::CONTENT_TYPE, "text/event-stream")],
                    Body::from("data: {\"ok\":true}\n\n"),
                )
                    .into_response()
            } else {
                Json(json!({
                    "id": "chatcmpl-test",
                    "object": "chat.completion",
                    "choices": [],
                }))
                .into_response()
            }
        }

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let upstream_task = tokio::spawn(async move {
            axum::serve(
                listener,
                axum::Router::new().route("/v1/chat/completions", post(upstream)),
            )
            .await
            .expect("upstream server");
        });

        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: vec!["auto".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: Some("Bearer upstream-secret".to_owned()),
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("client");

        for (stream, expected_content_type) in
            [(false, "application/json"), (true, "text/event-stream")]
        {
            let request_body = if stream {
                r#"{"model":null,"prompt":"x","stream":true}"#
            } else {
                r#"{"model":"  ","prompt":"x","reasoning_effort":" NONE "}"#
            };
            let response = state
                .router()
                .oneshot(
                    axum::http::Request::builder()
                        .method("POST")
                        .uri("/v1/chat/completions")
                        .header(header::AUTHORIZATION, "bEaReR secret")
                        .header(header::CONTENT_TYPE, "application/json")
                        .body(Body::from(request_body))
                        .expect("request"),
                )
                .await
                .expect("response");
            assert_eq!(response.status(), StatusCode::OK);
            assert_eq!(
                response.headers()[header::CONTENT_TYPE],
                expected_content_type
            );
            let body = response
                .into_body()
                .collect()
                .await
                .expect("body")
                .to_bytes();
            assert!(!body.is_empty());
        }
        upstream_task.abort();
    }

    #[tokio::test]
    async fn malformed_proxy_profile_never_falls_back_to_direct_egress() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("direct sentinel listener");
        let address = listener.local_addr().expect("direct sentinel address");
        let hits = Arc::new(AtomicUsize::new(0));
        let server_hits = hits.clone();
        let server = tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.expect("unexpected direct request");
            server_hits.fetch_add(1, Ordering::SeqCst);
            let body = b"direct egress reached";
            let headers = format!(
                "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                body.len()
            );
            stream
                .write_all(headers.as_bytes())
                .await
                .expect("sentinel headers");
            stream.write_all(body).await.expect("sentinel body");
        });
        let profile = ProxyProfile {
            proxy_url: "not a proxy URL".to_owned(),
            ..ProxyProfile::default()
        };
        let client = upstream_client_for_profile(&profile).expect("fail-closed client");
        let response = tokio::time::timeout(
            Duration::from_secs(2),
            client.get(format!("http://{address}/probe")).send(),
        )
        .await
        .expect("proxy failure should be prompt");
        assert!(response.is_err());
        assert_eq!(hits.load(Ordering::SeqCst), 0);
        server.abort();
        let _ = server.await;
    }
