    #[tokio::test]
    async fn openai_compatible_upstream_uses_legacy_global_proxy() {
        let account_path = account_snapshot_path("openai-global-proxy");
        let data_dir = account_path.parent().expect("data directory").to_owned();
        fs::write(&account_path, "[]").expect("empty accounts");
        let proxy_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("proxy listener");
        let proxy_address = proxy_listener.local_addr().expect("proxy address");
        fs::write(
            data_dir.join("config.json"),
            serde_json::to_vec(&json!({"proxy":format!("http://{proxy_address}")}))
                .expect("proxy config"),
        )
        .expect("write proxy config");
        let (request_target_tx, request_target_rx) = tokio::sync::oneshot::channel();
        let proxy = tokio::spawn(async move {
            let (mut stream, _) = proxy_listener.accept().await.expect("proxy accept");
            let mut request = Vec::new();
            let mut chunk = [0u8; 4096];
            loop {
                let read = stream.read(&mut chunk).await.expect("proxy request read");
                if read == 0 {
                    break;
                }
                request.extend_from_slice(&chunk[..read]);
                if request.windows(4).any(|window| window == b"\r\n\r\n") {
                    break;
                }
            }
            let request = String::from_utf8_lossy(&request);
            let request_target = request.lines().next().unwrap_or_default().to_owned();
            let _ = request_target_tx.send(request_target);
            let body = br#"{"id":"proxied-chat","object":"chat.completion","choices":[{"index":0,"message":{"role":"assistant","content":"proxied"},"finish_reason":"stop"}]}"#;
            let headers = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                body.len()
            );
            stream
                .write_all(headers.as_bytes())
                .await
                .expect("proxy response headers");
            stream.write_all(body).await.expect("proxy response body");
        });
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some("http://upstream.invalid".to_owned()),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("proxy test state");
        let response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"hello"}]}"#,
                    ))
                    .expect("proxied Chat request"),
            )
            .await
            .expect("proxied Chat response");

        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            request_target_rx.await.expect("proxy request target"),
            "POST http://upstream.invalid/v1/chat/completions HTTP/1.1"
        );
        assert_eq!(
            json_response(response).await["choices"][0]["message"]["content"],
            "proxied"
        );
        proxy.await.expect("proxy task");
        fs::remove_file(data_dir.join("config.json")).expect("config cleanup");
        fs::remove_file(account_path).expect("accounts cleanup");
    }

    #[tokio::test]
    async fn openai_compatible_image_calls_log_model_and_prompt_for_json_and_multipart() {
        let account_path = account_snapshot_path("openai-image-log-context");
        let data_dir = account_path.parent().expect("data directory").to_owned();
        fs::write(&account_path, b"[]").expect("empty accounts");
        fs::write(
            data_dir.join("config.json"),
            br#"{"proxy":"","sensitive_words":["blocked-image-term"]}"#,
        )
        .expect("write isolated image proxy config");

        let forwarded = Arc::new(Mutex::new(Vec::<(String, String, Vec<u8>)>::new()));
        let forwarded_for_upstream = forwarded.clone();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("image upstream listener");
        let address = listener.local_addr().expect("image upstream address");
        let mut upstream = tokio::spawn(async move {
            let image_handler = move |uri: axum::http::Uri, headers: HeaderMap, body: Bytes| {
                let forwarded = forwarded_for_upstream.clone();
                async move {
                    forwarded.lock().await.push((
                        uri.path().to_owned(),
                        headers
                            .get(header::CONTENT_TYPE)
                            .and_then(|value| value.to_str().ok())
                            .unwrap_or_default()
                            .to_owned(),
                        body.to_vec(),
                    ));
                    Json(json!({"data": []}))
                }
            };
            axum::serve(
                listener,
                Router::new()
                    .route("/__ready", get(|| async { StatusCode::NO_CONTENT }))
                    .route("/v1/images/generations", post(image_handler.clone()))
                    .route("/v1/images/edits", post(image_handler)),
            )
            .await
            .expect("image upstream");
        });
        let upstream_url = format!("http://{address}");
        tokio::select! {
            () = wait_for_test_http_ready(&upstream_url, "/__ready") => {}
            result = &mut upstream => panic!("image upstream exited before readiness: {result:?}"),
        }

        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(upstream_url),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("OpenAI-compatible image state");

        let blocked_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/images/generations")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"blocked-model","prompt":"blocked-image-term"}"#,
                    ))
                    .expect("blocked generation request"),
            )
            .await
            .expect("blocked generation response");
        assert_eq!(blocked_response.status(), StatusCode::BAD_REQUEST);

        let generation_body =
            br#"{"model":"custom-image","prompt":"  draw a  red\nfox  "}"#.to_vec();
        let generation_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/images/generations")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(generation_body.clone()))
                    .expect("generation request"),
            )
            .await
            .expect("generation response");
        assert_eq!(generation_response.status(), StatusCode::OK);
        assert_eq!(json_response(generation_response).await["data"], json!([]));

        let boundary = "image-log-boundary";
        let edit_body = format!(
            "--{boundary}\r\nContent-Disposition: form-data; name=\"model\"\r\n\r\nedit-model\r\n--{boundary}\r\nContent-Disposition: form-data; name=\"prompt\"\r\n\r\n  edit a  blue\ncar  \r\n--{boundary}\r\nContent-Disposition: form-data; name=\"image\"; filename=\"source.png\"\r\nContent-Type: image/png\r\n\r\nimage-bytes\r\n--{boundary}--\r\n"
        )
        .into_bytes();
        let edit_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/images/edits")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(
                        header::CONTENT_TYPE,
                        format!("multipart/form-data; boundary={boundary}"),
                    )
                    .body(Body::from(edit_body.clone()))
                    .expect("edit request"),
            )
            .await
            .expect("edit response");
        assert_eq!(edit_response.status(), StatusCode::OK);
        assert_eq!(json_response(edit_response).await["data"], json!([]));

        let unauthorized_response = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/images/generations")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(generation_body.clone()))
                    .expect("unauthorized generation request"),
            )
            .await
            .expect("unauthorized generation response");
        assert_eq!(unauthorized_response.status(), StatusCode::UNAUTHORIZED);

        let forwarded = forwarded.lock().await;
        assert_eq!(forwarded.len(), 2);
        assert_eq!(forwarded[0].0, "/v1/images/generations");
        assert_eq!(forwarded[0].2, generation_body);
        assert_eq!(forwarded[1].0, "/v1/images/edits");
        assert_eq!(forwarded[1].2, edit_body);
        drop(forwarded);

        let logs = fs::read_to_string(data_dir.join("logs.jsonl"))
            .expect("image call logs")
            .lines()
            .filter_map(|line| serde_json::from_str::<Value>(line).ok())
            .collect::<Vec<_>>();
        assert_eq!(logs.iter().filter(|item| item["type"] == "call").count(), 3);
        let blocked_log = logs
            .iter()
            .find(|item| {
                item["detail"]["endpoint"] == "/v1/images/generations"
                    && item["detail"]["status"] == "failed"
            })
            .expect("blocked image call log");
        assert_eq!(blocked_log["detail"]["model"], "blocked-model");
        assert_eq!(blocked_log["detail"]["request_text"], "blocked-image-term");
        let generation_log = logs
            .iter()
            .find(|item| {
                item["detail"]["endpoint"] == "/v1/images/generations"
                    && item["detail"]["status"] == "success"
            })
            .expect("generation call log");
        assert_eq!(generation_log["detail"]["model"], "custom-image");
        assert_eq!(generation_log["detail"]["request_text"], "draw a red fox");
        let edit_log = logs
            .iter()
            .find(|item| item["detail"]["endpoint"] == "/v1/images/edits")
            .expect("edit call log");
        assert_eq!(edit_log["detail"]["model"], "edit-model");
        assert_eq!(edit_log["detail"]["request_text"], "edit a blue car");

        upstream.abort();
        let _ = upstream.await;
        fs::remove_file(data_dir.join("logs.jsonl")).expect("logs cleanup");
        fs::remove_file(data_dir.join("config.json")).expect("config cleanup");
        fs::remove_file(account_path).expect("accounts cleanup");
    }

    #[tokio::test]
    async fn account_snapshot_filters_inactive_status_and_lease_releases() {
        let path = test_tmp_dir().join(format!(
            "chatgpt2api-rust-accounts-{}-{}.json",
            std::process::id(),
            NATIVE_MESSAGE_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::write(
            &path,
            r#"{"items":[
                {"access_token":"disabled-token","status":"禁用","_model_source_version":1,"_verified_web_model_paths":["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],"models":["gpt-test"],"model_sources":{"gpt-test":"web"}},
                {"access_token":"wrong-model-token","status":"正常","_model_source_version":1,"_verified_web_model_paths":["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],"models":["other"],"model_sources":{"other":"web"}},
                {"access_token":"account-token","status":"正常","_model_source_version":1,"_verified_web_model_paths":["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],"models":["gpt-test"],"model_sources":{"gpt-test":"web"}}
            ]}"#
            .as_bytes(),
        )
        .expect("accounts snapshot");
        let store = AccountStore::load(Some(&path)).expect("account store");
        assert_eq!(store.inflight(), 0);
        let lease = store.acquire("gpt-test").await.expect("eligible account");
        assert_eq!(lease.token(), "wrong-model-token");
        assert_eq!(store.inflight(), 1);
        drop(lease);
        assert_eq!(store.inflight(), 0);
        let missing_model_lease = store
            .acquire("missing-model")
            .await
            .expect("v1.7 chooses text accounts without model metadata filtering");
        assert_eq!(missing_model_lease.token(), "account-token");
        drop(missing_model_lease);

        let old_lease = store.acquire("gpt-test").await.expect("old lease");
        assert_eq!(old_lease.token(), "wrong-model-token");
        atomic_replace_checked_with_limit(
            &path,
            r#"{"items":[{"access_token":"rotated-token","status":"正常","_model_source_version":1,"_verified_web_model_paths":["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],"models":["gpt-test"],"model_sources":{"gpt-test":"web"}}]}"#
                .as_bytes(),
            MAX_ACCOUNT_SNAPSHOT_BYTES,
            false,
        )
        .expect("rotated snapshot");
        let rotated_lease = store.acquire("gpt-test").await.expect("rotated lease");
        assert_eq!(rotated_lease.token(), "rotated-token");
        assert_eq!(store.inflight(), 1);
        drop(old_lease);
        assert_eq!(store.inflight(), 1);
        drop(rotated_lease);
        atomic_replace_checked_with_limit(
            &path,
            r#"{"items":[{"access_token":"rotated-token","status":"禁用","_model_source_version":1,"_verified_web_model_paths":["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],"models":["gpt-test"],"model_sources":{"gpt-test":"web"}}]}"#
                .as_bytes(),
            MAX_ACCOUNT_SNAPSHOT_BYTES,
            false,
        )
        .expect("disabled snapshot");
        assert!(store.acquire("gpt-test").await.is_none());
        atomic_replace_checked_with_limit(
            &path,
            br#"{"items":[{"access_token":{"secret":true}}]}"#,
            MAX_ACCOUNT_SNAPSHOT_BYTES,
            false,
        )
        .expect("invalid snapshot");
        assert!(store.acquire("gpt-test").await.is_none());
        atomic_replace_checked_with_limit(
            &path,
            r#"{"items":[{"access_token":"recovered-token","status":"正常","_model_source_version":1,"_verified_web_model_paths":["/backend-api/models?iim=false&is_gizmo=false&supports_model_picker_upgrade_presets=true"],"models":["gpt-test"],"model_sources":{"gpt-test":"web"}}]}"#
                .as_bytes(),
            MAX_ACCOUNT_SNAPSHOT_BYTES,
            false,
        )
        .expect("recovered snapshot");
        let recovered = store.acquire("gpt-test").await.expect("recovered lease");
        assert_eq!(recovered.token(), "recovered-token");
        drop(recovered);
        fs::remove_file(path).expect("cleanup");
    }

    #[tokio::test]
    async fn image_account_leases_follow_concurrency_limit_independent_of_quota() {
        let path = account_snapshot_path("image-lease-quota-boundary");
        fs::write(
            &path,
            r#"[
                {"access_token":"image-token","status":"正常","type":"plus","quota":1,"_model_source_version":1,"_verified_image_capability":true,"models":[],"model_sources":{}},
                {"access_token":"codex-image-token","status":"正常","type":"plus","source_type":"codex","quota":1},
                {"access_token":"zero-token","status":"正常","type":"pro","quota":0},
                {"access_token":"string-token","status":"正常","type":"team","quota":"1","_verified_image_capability":true},
                {"access_token":"limited-token","status":"限流","type":"enterprise","quota":5}
            ]"#
            .as_bytes(),
        )
        .expect("accounts snapshot");
        let store = AccountStore::load(Some(&path)).expect("account store");

        let text_lease = store.acquire("gpt-test").await.expect("text lease");
        let only_quota_one_account = HashSet::from([
            "zero-token".to_owned(),
            "codex-image-token".to_owned(),
            "string-token".to_owned(),
            "limited-token".to_owned(),
        ]);
        let mut image_leases = Vec::new();
        for _ in 0..3 {
            let lease = store
                .acquire_image_lease_with_limit(&only_quota_one_account, 3)
                .await
                .expect("image concurrency is independent of remaining quota count");
            assert_eq!(lease.token(), "image-token");
            image_leases.push(lease);
        }
        assert_eq!(store.inflight(), 4);
        assert!(
            store
                .acquire_image_lease_with_limit(&only_quota_one_account, 3)
                .await
                .is_none(),
            "per-account image concurrency setting caps reservations"
        );
        drop(text_lease);
        assert_eq!(store.inflight(), 3);

        atomic_replace_checked_with_limit(
            &path,
            r#"[
                {"access_token":"image-token","status":"正常","type":"plus","quota":1,"_model_source_version":1,"_verified_image_capability":true,"models":[],"model_sources":{}},
                {"access_token":"codex-image-token","status":"正常","type":"plus","source_type":"codex","quota":1},
                {"access_token":"zero-token","status":"正常","type":"pro","quota":0},
                {"access_token":"string-token","status":"正常","type":"team","quota":"1","_verified_image_capability":true},
                {"access_token":"limited-token","status":"限流","type":"enterprise","quota":5}
            ]"#
            .as_bytes(),
            MAX_ACCOUNT_SNAPSHOT_BYTES,
            false,
        )
        .expect("refreshed account snapshot");
        assert!(
            store
                .acquire_image_lease_with_limit(&only_quota_one_account, 3)
                .await
                .is_none(),
            "a snapshot reload preserves all in-flight image reservations"
        );

        drop(image_leases);
        assert_eq!(store.inflight(), 0);
        let next_image_lease = store
            .acquire_image_lease_with_limit(&only_quota_one_account, 3)
            .await
            .expect("released image concurrency slot");
        assert_eq!(next_image_lease.token(), "image-token");
        drop(next_image_lease);
        assert_eq!(store.inflight(), 0);

        let only_codex_quota_one_account = HashSet::from([
            "image-token".to_owned(),
            "zero-token".to_owned(),
            "string-token".to_owned(),
            "limited-token".to_owned(),
        ]);
        let mut codex_image_leases = Vec::new();
        for _ in 0..3 {
            let lease = store
                .acquire_codex_image_lease_with_limit(&only_codex_quota_one_account, None, 3)
                .await
                .expect("Codex image concurrency is independent of remaining quota count");
            assert_eq!(lease.token(), "codex-image-token");
            codex_image_leases.push(lease);
        }
        assert!(
            store
                .acquire_codex_image_lease_with_limit(&only_codex_quota_one_account, None, 3,)
                .await
                .is_none(),
            "Codex image leases use the same account concurrency limit"
        );
        drop(codex_image_leases);
        assert_eq!(store.inflight(), 0);
        assert_eq!(
            store.image_capable_account_types(),
            HashSet::from(["plus".to_owned(), "team".to_owned()])
        );
        fs::remove_file(path).expect("cleanup");
    }

    #[tokio::test]
    async fn image_result_accounting_consumes_only_successful_image_requests() {
        let path = account_snapshot_path("image-result-accounting");
        fs::write(
            &path,
            r#"[
                {"access_token":"success-token","status":"正常","type":"plus","quota":2,"success":-2,"_verified_image_capability":true},
                {"access_token":"failure-token","status":"正常","type":"pro","quota":2,"fail":-3,"_verified_image_capability":true}
            ]"#
            .as_bytes(),
        )
        .expect("accounts snapshot");
        let store = AccountStore::load(Some(&path)).expect("account store");

        let success_lease = store
            .acquire_image_lease(&HashSet::from(["failure-token".to_owned()]))
            .await
            .expect("success lease");
        assert_eq!(success_lease.token(), "success-token");
        assert_eq!(
            store
                .mark_image_result("success-token", true, false)
                .await
                .expect("mark image success"),
            ImageResultUpdate::Updated
        );
        drop(success_lease);

        let failure_lease = store
            .acquire_image_lease(&HashSet::from(["success-token".to_owned()]))
            .await
            .expect("failure lease");
        assert_eq!(failure_lease.token(), "failure-token");
        assert_eq!(
            store
                .mark_image_result("failure-token", false, false)
                .await
                .expect("mark image failure"),
            ImageResultUpdate::Updated
        );
        drop(failure_lease);

        let records = store.records();
        let success = records
            .iter()
            .find(|record| record.token == "success-token")
            .expect("success record");
        assert_eq!(success.raw["quota"], json!(1));
        assert_eq!(success.raw["success"], json!(-1));
        assert_eq!(success.raw["fail"], json!(0));
        assert_eq!(success.status, "正常");
        let failure = records
            .iter()
            .find(|record| record.token == "failure-token")
            .expect("failure record");
        assert_eq!(failure.raw["quota"], json!(2));
        assert_eq!(failure.raw["fail"], json!(-2));
        assert_eq!(failure.raw["success"], json!(0));
        assert_eq!(failure.status, "正常");
        assert_eq!(store.inflight(), 0);
        fs::remove_file(path).expect("cleanup");
    }

    #[tokio::test]
    async fn image_result_restores_limited_status_and_honors_auto_removal() {
        let path = account_snapshot_path("image-result-limited-transitions");
        fs::write(
            &path,
            r#"[
                {"access_token":"restore-token","status":"限流","quota":"3"},
                {"access_token":"exhaust-token","status":"正常","quota":"1","restore_at":""},
                {"access_token":"preserve-restore-token","status":"正常","quota":1,"restore_at":{"reset":"later"}},
                {"access_token":"remove-token","status":"正常","quota":"1"}
            ]"#,
        )
        .expect("account snapshot");
        let store = AccountStore::load(Some(&path)).expect("account store");

        assert_eq!(
            store
                .mark_image_result("restore-token", true, false)
                .await
                .expect("restore quota account"),
            ImageResultUpdate::Updated
        );
        assert_eq!(
            store
                .mark_image_result("exhaust-token", true, false)
                .await
                .expect("exhaust image quota"),
            ImageResultUpdate::Updated
        );
        assert_eq!(
            store
                .mark_image_result("preserve-restore-token", true, false)
                .await
                .expect("preserve truthy restore time"),
            ImageResultUpdate::Updated
        );
        assert_eq!(
            store
                .mark_image_result("remove-token", true, true)
                .await
                .expect("auto remove exhausted account"),
            ImageResultUpdate::RemovedRateLimited
        );

        let records = store.raw_records();
        let restored = records
            .iter()
            .find(|item| item["access_token"] == "restore-token")
            .expect("restored account");
        assert_eq!(restored["quota"], 2);
        assert_eq!(restored["status"], "正常");
        let exhausted = records
            .iter()
            .find(|item| item["access_token"] == "exhaust-token")
            .expect("exhausted account");
        assert_eq!(exhausted["quota"], 0);
        assert_eq!(exhausted["status"], "限流");
        assert_eq!(exhausted["restore_at"], Value::Null);
        let preserved = records
            .iter()
            .find(|item| item["access_token"] == "preserve-restore-token")
            .expect("truthy restore time");
        assert_eq!(preserved["restore_at"], json!({"reset":"later"}));
        assert!(
            records
                .iter()
                .all(|item| item["access_token"] != "remove-token")
        );
        fs::remove_file(path).expect("cleanup");
    }

    #[test]
    fn account_content_revision_collision_forces_reload_and_same_revision_keeps_cache() {
        let version = FileVersion {
            identity: file_identity::Identity {
                first: 7,
                second: 11,
            },
            size: 84,
            modified: 123,
            changed: 456,
        };
        let old_fingerprint = [0x11; 32];
        let new_fingerprint = [0x22; 32];
        assert_eq!(
            account_revision_decision(
                true,
                Some(version),
                old_fingerprint,
                version,
                new_fingerprint,
            ),
            AccountRevisionDecision::Reload,
            "same FileVersion plus different content revision must reload/fail closed"
        );
        assert_eq!(
            account_revision_decision(
                true,
                Some(version),
                old_fingerprint,
                version,
                old_fingerprint,
            ),
            AccountRevisionDecision::UseCached,
            "same FileVersion plus same fingerprint must keep the bounded fast path"
        );
        assert_eq!(
            account_revision_decision(
                false,
                Some(version),
                old_fingerprint,
                version,
                old_fingerprint,
            ),
            AccountRevisionDecision::Reload,
            "an unvalidated snapshot must reload/fail closed even with an unchanged revision"
        );
    }

    #[tokio::test]
    async fn account_acquire_hot_path_does_not_rescan_snapshot_content() {
        let path = account_snapshot_path("account-acquire-hot-path");
        fs::write(
            &path,
            r#"{"items":[{"access_token":"hot-path-token","status":"正常","models":["gpt-test"]}]}"#,
        )
        .expect("account snapshot");
        let store = account_pool::AccountStore::load(Some(&path)).expect("account store");
        let initial_content_reads = bounded_file_read_count(&path);
        assert_eq!(
            initial_content_reads, 1,
            "store load reads the snapshot once"
        );
        assert_eq!(account_document_parse_count(&path), 1);

        for _ in 0..32 {
            let lease = store.acquire("gpt-test").await.expect("eligible account");
            drop(lease);
        }

        assert_eq!(
            bounded_file_read_count(&path),
            initial_content_reads,
            "repeated acquire must use the bounded FileVersion fast path instead of reading and hashing the snapshot"
        );
        assert_eq!(account_document_parse_count(&path), 1);
        fs::remove_file(path).expect("cleanup");
    }

