    #[tokio::test]
    async fn native_chat_retires_invalid_accounts_and_retries_remaining_pool() {
        let account_path = account_snapshot_path("native-chat-invalid-token-failover");
        let data_dir = account_path.parent().expect("data directory").to_owned();
        fs::write(
            &account_path,
            r#"{"items":[
                {"access_token":"expired-a","status":"正常","models":["gpt-test"],"invalid_count":0},
                {"access_token":"expired-b","status":"正常","models":["gpt-test"],"invalid_count":0}
            ]}"#,
        )
        .expect("accounts snapshot");
        fs::write(
            data_dir.join("config.json"),
            br#"{"auto_remove_invalid_accounts":false}"#,
        )
        .expect("account settings");

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("upstream listener");
        let address = listener.local_addr().expect("upstream address");
        let conversation_requests = Arc::new(AtomicUsize::new(0));
        let conversation_requests_route = conversation_requests.clone();
        let conversation_route = post(move |headers: HeaderMap| {
            let requests = conversation_requests_route.clone();
            async move {
                let token = headers
                    .get(header::AUTHORIZATION)
                    .and_then(|value| value.to_str().ok())
                    .unwrap_or_default();
                assert!(token == "Bearer expired-a" || token == "Bearer expired-b");
                requests.fetch_add(1, Ordering::SeqCst);
                (StatusCode::UNAUTHORIZED, "token_invalidated")
            }
        });
        let server = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new()
                    .route("/", get(|| async { "<html></html>" }))
                    .route(
                        "/backend-api/sentinel/chat-requirements/prepare",
                        post(|| async { Json(json!({"prepare_token":"prepare"})) }),
                    )
                    .route(
                        "/backend-api/sentinel/chat-requirements/finalize",
                        post(|| async { Json(json!({"token":"requirements"})) }),
                    )
                    .route("/backend-api/conversation", conversation_route),
            )
            .await
            .expect("upstream server");
        });

        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        state.account_type_catalog.disable_for_test();
        assert!(!state.account_type_catalog.enabled());
        assert_eq!(state.account_store.raw_records().len(), 2);
        let first_lease = state
            .account_store
            .acquire("gpt-test")
            .await
            .expect("first test account is eligible");
        assert_eq!(first_lease.token(), "expired-a");
        drop(first_lease);
        state.account_store.cursor.store(0, Ordering::Relaxed);
        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer client"),
        );
        let result = chat_completions_with_timeout(
            State(state.clone()),
            headers,
            Body::from(r#"{"model":"gpt-test","messages":[{"role":"user","content":"hello"}]}"#),
            Duration::from_secs(5),
            false,
            None,
        )
        .await;

        let error = result.expect_err("all account tokens are invalid");
        assert_eq!(
            error.status,
            StatusCode::BAD_GATEWAY,
            "unexpected terminal error code {}",
            error.code()
        );
        assert_eq!(error.code(), "upstream_error");
        assert_eq!(conversation_requests.load(Ordering::SeqCst), 2);
        let records = state.account_store.raw_records();
        assert_eq!(records[0]["status"], "异常");
        assert_eq!(records[1]["status"], "异常");
        assert_eq!(records[0]["invalid_count"], 0);
        assert_eq!(records[1]["invalid_count"], 0);

        drop(state);
        server.abort();
        let _ = server.await;
        fs::remove_file(data_dir.join("config.json")).expect("config cleanup");
        fs::remove_file(account_path).expect("accounts cleanup");
    }

    #[tokio::test]
