    #[tokio::test]
    async fn chat_stream_failure_before_first_visible_delta_is_a_gateway_error() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("stream failure listener");
        let address = listener.local_addr().expect("stream failure address");
        async fn broken_stream() -> Response {
            let body = stream::once(async {
                Ok::<Bytes, io::Error>(Bytes::from_static(b"data: {\"type\":\"heartbeat\"}\n\n"))
            })
            .chain(stream::once(async {
                tokio::time::sleep(Duration::from_millis(50)).await;
                Err::<Bytes, io::Error>(io::Error::other("mock stream broke before first delta"))
            }));
            Response::builder()
                .status(StatusCode::OK)
                .header(header::CONTENT_TYPE, "text/event-stream")
                .body(Body::from_stream(body))
                .expect("broken SSE response")
        }
        async fn clean_eof_stream() -> Response {
            Response::builder()
                .status(StatusCode::OK)
                .body(Body::from(
                    "data: {\"message\":{\"author\":{\"role\":\"assistant\"},\"content\":{\"parts\":[\"clean\"]}}}\n\n",
                ))
                .expect("clean EOF SSE response")
        }
        let upstream = tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new()
                    .route("/__ready", get(|| async { StatusCode::NO_CONTENT }))
                    .route("/stream", get(broken_stream))
                    .route("/clean", get(clean_eof_stream)),
            )
            .await
            .expect("broken SSE mock");
        });
        wait_for_test_http_ready(&format!("http://{address}"), "/__ready").await;
        let upstream_response = reqwest::Client::new()
            .get(format!("http://{address}/stream"))
            .send()
            .await
            .expect("headers arrive before body failure");
        assert_eq!(upstream_response.status(), StatusCode::OK);
        let state = AppState::new(AppConfig {
            version: "chat-stream-prime".to_owned(),
            auth_key: Some("secret".to_owned()),
            models: Vec::new(),
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("stream prime state");
        let error = native_stream_response(
            state.clone(),
            upstream_response,
            None,
            "gpt-test".to_owned(),
            false,
            0,
            None,
            String::new(),
            Vec::new(),
        )
        .await
        .expect_err("pre-first-delta failure remains a JSON gateway error");
        assert_eq!(error.status, StatusCode::BAD_GATEWAY);
        let clean_response = reqwest::Client::new()
            .get(format!("http://{address}/clean"))
            .send()
            .await
            .expect("clean EOF response headers");
        let completed = native_stream_response(
            state.clone(),
            clean_response,
            None,
            "gpt-test".to_owned(),
            false,
            0,
            None,
            String::new(),
            Vec::new(),
        )
        .await
        .expect("clean HTTP EOF without [DONE] is normal stream completion");
        let body = completed
            .into_body()
            .collect()
            .await
            .expect("clean EOF stream completion")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("clean EOF stream UTF-8");
        assert!(text.contains("clean"));
        assert!(text.contains("\"finish_reason\":\"stop\""));
        assert!(text.ends_with("data: [DONE]\n\n"));
        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
    }

