    #[tokio::test]
    async fn native_responses_stream_completed_event_includes_usage() {
        let chat_sse = concat!(
            "data: {\"choices\":[{\"delta\":{\"content\":\"answer\"}}]}\n\n",
            "data: [DONE]\n\n"
        );
        let response = response_stream_from_chat(
            Response::new(Body::from(chat_sse)),
            "gpt-test".to_owned(),
            Instant::now() + Duration::from_secs(5),
            7,
            15,
        );
        let body = response
            .into_body()
            .collect()
            .await
            .expect("Responses stream body")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("Responses stream UTF-8");
        let completed = text
            .lines()
            .filter_map(|line| line.strip_prefix("data: "))
            .filter_map(|data| serde_json::from_str::<Value>(data).ok())
            .find(|event| event["type"] == "response.completed")
            .expect("completed event");
        let output_item_done = text
            .lines()
            .filter_map(|line| line.strip_prefix("data: "))
            .filter_map(|data| serde_json::from_str::<Value>(data).ok())
            .find(|event| event["type"] == "response.output_item.done")
            .expect("output item done event");
        assert_eq!(output_item_done["output_index"], 0);
        assert!(
            completed["response"]["usage"]["input_tokens"]
                .as_u64()
                .unwrap()
                >= 22
        );
        assert_eq!(
            completed["response"]["usage"]["input_tokens_details"]["text_tokens"],
            7
        );
        assert_eq!(
            completed["response"]["usage"]["input_tokens_details"]["image_tokens"],
            15
        );
        assert!(
            completed["response"]["usage"]["output_tokens"]
                .as_u64()
                .unwrap()
                > 0
        );
    }
    #[test]
    fn native_chat_usage_counts_image_patches_and_all_python_text_fields() {
        let encoded = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
        let image_url = format!("data:image/png;base64,{encoded}");
        let payload = json!({
            "model":"gpt-4o",
            "messages":[{
                "role":"user",
                "name":"caller",
                "content":[
                    {"type":"text","text":"hello"},
                    {"type":"image_url","image_url":image_url,"detail":"low"}
                ]
            }]
        });
        let usage = native_usage(payload.as_object().unwrap(), "").expect("multimodal usage");
        let bpe = tiktoken_rs::bpe_for_model("gpt-4o").expect("model tokenizer");
        let text_tokens = 6
            + bpe.count("user", &HashSet::new()).unwrap()
            + bpe.count("hello", &HashSet::new()).unwrap()
            + bpe.count("caller", &HashSet::new()).unwrap()
            + 1;
        assert_eq!(usage["prompt_tokens_details"]["text_tokens"], text_tokens);
        assert_eq!(usage["prompt_tokens_details"]["image_tokens"], 2);
        assert_eq!(usage["prompt_tokens"], text_tokens + 2);
        assert_eq!(usage["total_tokens"], text_tokens + 2);
    }

