    #[tokio::test]
    async fn native_chat_image_stream_projects_progress_and_results_as_completion_chunks() {
        let source = concat!(
            r#"data: {"object":"image.generation.chunk","progress_text":"working"}"#,
            "\n\n",
            r#"data: {"object":"image.generation.message","message":"working and more"}"#,
            "\n\n",
            r#"data: {"object":"image.generation.result","data":[{"b64_json":"aW1hZ2U="}]}"#,
            "\n\n",
            "data: [DONE]\n\n"
        );
        let response = native_chat_image_stream_completion("gpt-image-2", source.as_bytes())
            .expect("chat image stream");
        assert_eq!(
            response.headers()[header::CONTENT_TYPE],
            "text/event-stream"
        );
        let body = response
            .into_body()
            .collect()
            .await
            .expect("stream body")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("stream UTF-8");
        assert!(text.contains("working"));
        assert!(text.contains("and more"));
        assert!(text.contains("![image_1](data:image/png;base64,aW1hZ2U=)"));
        assert!(text.contains("data: [DONE]"));
    }

    #[tokio::test]
    async fn native_responses_image_request_uses_first_image_in_last_message_like_python() {
        let account_path = account_snapshot_path("responses-image-first-input");
        fs::write(&account_path, b"[]").expect("empty account snapshot");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: Vec::new(),
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let encoded = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
        let first = format!("data:image/png;base64,{encoded}");
        let last = format!("data:image/png;name=last;base64,{encoded}");
        let object = json!({
            "model":"gpt-image-2",
            "tools":[{"type":"image_generation","model":"codex-gpt-image-2","output_format":"jpeg","output_compression":72,"size":1024,"quality":7}],
            "input":[
                {"role":"assistant","content":[{"type":"input_image","image_url":first,"detail":"low"}]},
                {"role":"user","content":[
                    {"type":"text","text":"edit"},
                    {"type":"image_url","image_url":{"url":first},"width":64,"height":32},
                    {"type":"image","source":{"type":"base64","media_type":"image/png","data":encoded}},
                    {"type":"input_image","image_url":last}
                ]}
            ]
        });
        let request = native_responses_image_request_from_object(
            &state,
            object.as_object().expect("Responses image request"),
        )
        .await
        .expect("first Responses image input");
        assert_eq!(request.images.len(), 1);
        assert_eq!(request.model, "gpt-image-2");
        assert!(!request.codex);
        assert_eq!(request.usage_images.as_ref().map(Vec::len), Some(4));
        assert_eq!(request.usage_image_details.as_ref().map(Vec::len), Some(4));
        assert_eq!(request.usage_image_details.as_ref().unwrap()[0], "low");
        assert_eq!(request.output_format, "png");
        assert_eq!(request.output_compression, None);
        assert_eq!(request.quality, "7");
        assert_eq!(request.size.as_deref(), Some("1024"));
        assert!(matches!(
            &request.images[0],
            NativeImageSource::Text(value) if value == &first
        ));
        let usage = native_image_usage_for_request(&request, &[]);
        assert_eq!(
            usage["input_tokens_details"]["image_tokens"],
            native_image_patch_tokens(1, 1, "low")
                + native_image_patch_tokens(64, 32, "auto")
                + native_image_patch_tokens(1, 1, "auto") * 2
        );
        state.account_type_catalog.shutdown().await;
        fs::remove_file(account_path).expect("cleanup");
    }

