        assert_eq!(value["choices"][0]["message"]["content"], "unexpected");
        assert_eq!(conversation_calls.load(Ordering::SeqCst), 1);

        state.account_type_catalog.shutdown().await;
        upstream_task.abort();
        let _ = upstream_task.await;
