    #[tokio::test]
    async fn openai_catalog_uses_account_proxy_from_account_snapshot() {
        let account_path = account_snapshot_path("openai-catalog-account-proxy");
        let data_dir = account_path.parent().expect("data directory").to_owned();
        let proxy_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("proxy listener");
        let proxy_address = proxy_listener.local_addr().expect("proxy address");
        let proxy_url = format!("http://{proxy_address}");
        fs::write(
            &account_path,
            serde_json::to_vec(&json!([{
                "access_token": "catalog-account",
                "status": "\u{6b63}\u{5e38}",
                "type": "Pro",
                "proxy": proxy_url
            }]))
            .expect("account JSON"),
        )
        .expect("account snapshot");
        let (request_target_tx, request_target_rx) = tokio::sync::oneshot::channel();
        let proxy_task = tokio::spawn(async move {
            let (mut stream, _) = proxy_listener.accept().await.expect("proxy accept");
            let mut request = Vec::new();
            let mut chunk = [0u8; 4096];
            loop {
                let read = stream.read(&mut chunk).await.expect("proxy request read");
                if read == 0 {
                    break;
                }
                request.extend_from_slice(&chunk[..read]);
                if request.windows(4).any(|window| window == b"\r\n\r\n") {
                    break;
                }
            }
            let request = String::from_utf8_lossy(&request);
            let request_target = request.lines().next().unwrap_or_default().to_owned();
            let _ = request_target_tx.send(request_target);
            let body = br#"{"data":[{"id":"proxied-catalog-model"}]}"#;
            let headers = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                body.len()
            );
            stream
                .write_all(headers.as_bytes())
                .await
                .expect("proxy response headers");
            stream.write_all(body).await.expect("proxy response body");
        });
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: None,
            models: Vec::new(),
            upstream_base_url: Some("http://catalog-upstream.invalid".to_owned()),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("account-proxy catalog state");
        let (_, groups) = state
            .account_store
            .active_type_candidates()
            .await
            .expect("account candidates");
        let candidates = groups.values().next().expect("account type candidates");
        assert_eq!(candidates[0].proxy_url.as_deref(), Some(proxy_url.as_str()));
        let result = state
            .account_type_catalog
            .fetch_account_type_models(
                &"pro".to_owned(),
                candidates,
                Instant::now() + Duration::from_secs(5),
            )
            .await
            .expect("account-proxy model catalog");
        assert_eq!(result.0[0].id, "proxied-catalog-model");
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(5), request_target_rx)
                .await
                .expect("proxy receives model request")
                .expect("proxy request target"),
            "GET http://catalog-upstream.invalid/v1/models HTTP/1.1"
        );
        state.account_type_catalog.shutdown().await;
        proxy_task.await.expect("proxy task");
        let _ = fs::remove_file(account_path);
        let _ = fs::remove_file(data_dir.join("config.json"));
    }

