    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn failed_type_refresh_keeps_last_good_and_respects_backoff() {
        let account_path = test_tmp_dir().join(format!(
            "chatgpt2api-rust-account-type-backoff-{}-{}.json",
            std::process::id(),
            NATIVE_MESSAGE_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::write(
            &account_path,
            r#"[
                {"access_token":"free-a","status":"正常","type":"free"}
            ]"#,
        )
        .expect("account snapshot");
        let calls = Arc::new(AtomicUsize::new(0));
        let fail = Arc::new(AtomicBool::new(false));
        let failed = Arc::new(Notify::new());
        let calls_for_upstream = calls.clone();
        let fail_for_upstream = fail.clone();
        let failed_for_upstream = failed.clone();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let upstream_task = tokio::spawn(async move {
            async fn upstream(
                headers: HeaderMap,
                calls: Arc<AtomicUsize>,
                fail: Arc<AtomicBool>,
                failed: Arc<Notify>,
            ) -> Response {
                calls.fetch_add(1, Ordering::SeqCst);
                let token = headers
                    .get(header::AUTHORIZATION)
                    .and_then(|value| value.to_str().ok())
                    .unwrap_or_default();
                if token.is_empty() {
                    return Json(json!({
                        "object": "list",
                        "data": [{"id": "anonymous-model"}]
                    }))
                    .into_response();
                }
                if fail.load(Ordering::SeqCst) {
                    failed.notify_one();
                    return Json(json!({
                        "object": "list",
                        "data": []
                    }))
                    .into_response();
                }
                Json(json!({
                    "object": "list",
                    "data": [{"id": "free-model"}]
                }))
                .into_response()
            }
            axum::serve(
                listener,
                Router::new()
                    .route("/__ready", get(|| async { StatusCode::NO_CONTENT }))
                    .route(
                        "/v1/models",
                        get(move |headers: HeaderMap| {
                            upstream(
                                headers,
                                calls_for_upstream.clone(),
                                fail_for_upstream.clone(),
                                failed_for_upstream.clone(),
                            )
                        }),
                    ),
            )
            .await
            .expect("upstream server");
        });
        wait_for_test_http_ready(&format!("http://{address}"), "/__ready").await;
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["anon-model".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        state
            .account_type_catalog
            .refresh_inner_with_budget(Duration::from_secs(5))
            .await;
        let request = || {
            axum::http::Request::builder()
                .uri("/v1/models")
                .header(header::AUTHORIZATION, "Bearer client")
                .body(Body::empty())
                .expect("request")
        };
        let first = state.router().oneshot(request()).await.expect("response");
        assert_eq!(first.status(), StatusCode::OK);
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        fail.store(true, Ordering::SeqCst);
        {
            let mut snapshot = state
                .account_type_catalog
                .snapshot
                .write()
                .expect("catalog lock");
            for entry in snapshot.entries.values_mut() {
                entry.expires_at = Instant::now() - Duration::from_secs(1);
                entry.retry_at = Instant::now() - Duration::from_secs(1);
            }
        }
        let second =
            tokio::time::timeout(Duration::from_secs(2), state.router().oneshot(request()))
                .await
                .expect("empty catalog refresh must finish within the bounded request budget")
                .expect("response");
        assert_eq!(second.status(), StatusCode::OK);
        let body = second.into_body().collect().await.expect("body").to_bytes();
        let value: Value = serde_json::from_slice(&body).expect("models json");
        assert!(
            value["data"]
                .as_array()
                .is_some_and(|items| { items.iter().any(|item| item["id"] == "free-model") })
        );
        tokio::time::timeout(Duration::from_secs(2), failed.notified())
            .await
            .unwrap_or_else(|_| {
                panic!(
                    "empty catalog candidate sequence must reach the refresh failure hook; calls={} ",
                    calls.load(Ordering::SeqCst)
                )
            });
        assert_eq!(calls.load(Ordering::SeqCst), 3);
        let third = state.router().oneshot(request()).await.expect("response");
        assert_eq!(third.status(), StatusCode::OK);
        assert_eq!(calls.load(Ordering::SeqCst), 3);
        state.account_type_catalog.shutdown().await;
        drop(state);
        upstream_task.abort();
        let _ = upstream_task.await;
        fs::remove_file(account_path).expect("cleanup");
    }

