    #[test]
    fn native_image_poll_matches_python_policy_and_task_error_shapes() {
        let conversation = json!({
            "mapping": {
                "empty-node": {},
                "assistant": {
                    "message": {
                        "author":{"role":"assistant"},
                        "content":{"content_type":"text","parts":["This image request was blocked by policy."]}
                    }
                }
            }
        });
        assert_eq!(
            native_image_content_policy_message(&conversation).as_deref(),
            Some("This image request was blocked by policy.")
        );
        let tasks = json!({"tasks":[
            {
                "conversation_id":"other",
                "image_gen_message":{"metadata":{"is_error":true},"content":{"content_type":"text","parts":["wrong conversation"]}}
            },
            {
                "original_conversation_id":"image-conversation",
                "image_gen_message":{"metadata":{"is_error":true},"content":{"content_type":"text","parts":["moderation rejected"]}}
            },
            {
                "conversation_id":"image-conversation",
                "image_gen_message":{"metadata":{"is_error":true},"content":{"content_type":"text","parts":["latest task error"]}}
            }
        ]});
        assert_eq!(
            native_image_task_error_message(&tasks, "image-conversation").as_deref(),
            Some("moderation rejected")
        );
        assert_eq!(
            native_image_last_task_error_message(&tasks, "image-conversation").as_deref(),
            Some("latest task error")
        );
        assert_eq!(
            native_image_task_error_message(&tasks, "").as_deref(),
            Some("wrong conversation")
        );
        assert_eq!(
            native_image_poll_timeout_result(&[], "moderation rejected")
                .expect_err("task error without image ids becomes policy error")
                .code(),
            "content_policy_violation"
        );
        assert_eq!(
            native_image_poll_timeout_result(&["file-image".to_owned()], "task error")
                .expect("partial image IDs survive poll timeout"),
            ["file-image"]
        );
        assert_eq!(
            native_image_poll_timeout_result(&[], "")
                .expect_err("timeout without task error remains timeout")
                .code(),
            "image_poll_timeout"
        );
        assert!(native_image_poll_status_retryable(
            StatusCode::TOO_MANY_REQUESTS
        ));
        assert!(native_image_poll_status_retryable(StatusCode::BAD_GATEWAY));
        assert!(!native_image_poll_status_retryable(StatusCode::NOT_FOUND));
        assert!(!native_image_poll_status_retryable(StatusCode::CONFLICT));
        assert!(!native_image_poll_status_retryable(StatusCode::LOCKED));
    }

