    #[test]
    fn native_image_sse_state_matches_python_visible_text_and_turn_flags() {
        let mut state = NativeImageSseState::default();
        let metadata = json!({
            "type":"server_ste_metadata",
            "metadata":{"tool_invoked":true,"turn_use_case":"image gen"}
        });
        native_update_image_sse_state(&mut state, &metadata, &metadata.to_string());
        assert_eq!(state.tool_invoked, Some(true));
        assert_eq!(state.turn_use_case, "image gen");

        let upload = json!({
            "message": {
                "author":{"role":"user"},
                "content":{"content_type":"multimodal_text","parts":["file-service://input"]}
            }
        });
        native_update_image_sse_state(&mut state, &upload, &upload.to_string());
        assert!(state.file_ids.is_empty());

        let hidden = json!({
            "message": {
                "author":{"role":"assistant"},
                "channel":"analysis",
                "content":{"content_type":"text","parts":["internal reasoning"]}
            }
        });
        native_update_image_sse_state(&mut state, &hidden, &hidden.to_string());
        assert!(state.raw_message.is_empty());

        let final_message = json!({
            "message": {
                "author":{"role":"assistant"},
                "channel":"final",
                "content":{"content_type":"text","parts":["Here is the request: {\"size\":\"1024x1024\",\"n\":1}"]}
            }
        });
        native_update_image_sse_state(&mut state, &final_message, &final_message.to_string());
        assert!(native_image_is_text_reply(&state.message()));

        let blocked = json!({
            "type":"moderation",
            "moderation_response":{"blocked":true}
        });
        native_update_image_sse_state(&mut state, &blocked, &blocked.to_string());
        assert!(state.blocked);
    }

