    #[test]
    fn native_image_edit_matches_python_falsey_repr_and_default_data_mime() {
        let mut object = Map::new();
        object.insert("n".to_owned(), json!([]));
        assert_eq!(native_image_contract_count(&object, true).unwrap(), 1);
        object.insert("n".to_owned(), json!({}));
        assert_eq!(native_image_contract_count(&object, true).unwrap(), 1);
        object.insert("quality".to_owned(), json!({"a": 1}));
        assert_eq!(
            native_image_contract_string(&object, "quality", "auto", true).unwrap(),
            "{'a': 1}"
        );
        let (bytes, mime_type) = native_image_input_bytes("data:;base64,aW1hZ2U=")
            .expect("empty data URL MIME defaults to PNG");
        assert_eq!(bytes, b"image");
        assert_eq!(mime_type, "image/png");
    }

