    #[test]
    fn native_image_edit_mask_resizes_and_converts_python_supported_modes() {
        let encode = |image: image::DynamicImage, format: image::ImageFormat, mime: &str| {
            let mut encoded = Cursor::new(Vec::new());
            image.write_to(&mut encoded, format).expect("image fixture");
            format!(
                "data:{mime};base64,{}",
                base64::engine::general_purpose::STANDARD.encode(encoded.get_ref())
            )
        };
        let source = encode(
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                2,
                2,
                image::Rgba([255, 0, 0, 255]),
            )),
            image::ImageFormat::Png,
            "image/png",
        );
        let mask_wrong_size = encode(
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                1,
                1,
                image::Rgba([0, 0, 0, 0]),
            )),
            image::ImageFormat::Png,
            "image/png",
        );
        let mask_wrong_format = encode(
            image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(
                2,
                2,
                image::Rgb([0, 0, 0]),
            )),
            image::ImageFormat::Jpeg,
            "image/jpeg",
        );
        let mask_without_alpha = encode(
            image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(
                2,
                2,
                image::Rgb([0, 0, 0]),
            )),
            image::ImageFormat::Png,
            "image/png",
        );
        let mask_luma_alpha = encode(
            image::DynamicImage::ImageLumaA8(image::ImageBuffer::from_pixel(
                2,
                2,
                image::LumaA([32, 255]),
            )),
            image::ImageFormat::Png,
            "image/png",
        );
        for (name, mask) in [
            ("wrong-size", mask_wrong_size),
            ("wrong-format", mask_wrong_format),
            ("without-alpha", mask_without_alpha),
            ("luma-alpha", mask_luma_alpha),
        ] {
            let mut request = parse_native_image_request(
                json!({
                    "model": "gpt-image-2",
                    "prompt": "edit",
                    "image": source.clone(),
                })
                .to_string()
                .as_bytes(),
                "images/edits",
            )
            .expect("base edit request");
            request.mask = vec![NativeImageSource::Text(mask)];
            let request = native_apply_image_edit_mask(request).unwrap_or_else(|error| {
                panic!(
                    "Python-compatible mask conversion: {name}: {}",
                    error.code()
                )
            });
            let (composite, _, width, height) =
                native_image_source_input(&request.images[0]).expect("composite source");
            let decoded = image::load_from_memory(&composite).expect("composite PNG");
            assert_eq!((width, height), (2, 2), "case={name}");
            let expected_alpha = if name == "luma-alpha" { 32 } else { 0 };
            assert!(
                decoded
                    .to_rgba8()
                    .pixels()
                    .all(|pixel| pixel[3] == expected_alpha),
                "case={name}"
            );
        }
        let oversized_pixels = image::ImageBuffer::from_pixel(5_001, 5_000, image::Luma([0u8]));
        let mut oversized = Cursor::new(Vec::new());
        image::DynamicImage::ImageLuma8(oversized_pixels)
            .write_to(&mut oversized, image::ImageFormat::Png)
            .expect("oversized pixel fixture");
        let mut request = parse_native_image_request(
            json!({
                "model": "gpt-image-2",
                "prompt": "edit",
                "image": source,
            })
            .to_string()
            .as_bytes(),
            "images/edits",
        )
        .expect("base edit request");
        request.mask = vec![NativeImageSource::Text(format!(
            "data:image/png;base64,{}",
            base64::engine::general_purpose::STANDARD.encode(oversized.get_ref())
        ))];
        let error = match native_apply_image_edit_mask(request) {
            Ok(_) => panic!("oversized mask pixels must fail before upstream"),
            Err(error) => error,
        };
        assert_eq!(error.code(), "invalid_image_mask");
    }

    #[test]
    fn native_image_edit_pairs_multiple_masks_and_resizes_each_one() {
        let data_url = |picture: image::DynamicImage, format: image::ImageFormat| {
            let mut encoded = Cursor::new(Vec::new());
            picture
                .write_to(&mut encoded, format)
                .expect("image fixture");
            let mime = match format {
                image::ImageFormat::Jpeg => "image/jpeg",
                image::ImageFormat::Png => "image/png",
                _ => panic!("unexpected fixture format"),
            };
            format!(
                "data:{mime};base64,{}",
                base64::engine::general_purpose::STANDARD.encode(encoded.get_ref())
            )
        };
        let source_one = data_url(
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                2,
                2,
                image::Rgba([255, 0, 0, 255]),
            )),
            image::ImageFormat::Png,
        );
        let source_two = data_url(
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                3,
                1,
                image::Rgba([0, 255, 0, 255]),
            )),
            image::ImageFormat::Png,
        );
        let mask_one = data_url(
            image::DynamicImage::ImageLuma8(image::GrayImage::from_pixel(1, 1, image::Luma([64]))),
            image::ImageFormat::Png,
        );
        let mask_two = data_url(
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                1,
                2,
                image::Rgba([0, 0, 0, 128]),
            )),
            image::ImageFormat::Png,
        );
        let request = parse_native_image_request(
            json!({
                "model": "gpt-image-2",
                "prompt": "edit",
                "images": [source_one, source_two],
                "mask": [mask_one, mask_two],
            })
            .to_string()
            .as_bytes(),
            "images/edits",
        )
        .expect("multiple image and mask references");
        assert_eq!(request.images.len(), 2);
        assert_eq!(request.mask.len(), 2);

        let request = native_apply_image_edit_mask(request).expect("mask pairing and resize");
        for (index, (expected_size, expected_alpha, expected_rgb)) in
            [((2, 2), 64, [255, 0, 0]), ((3, 1), 128, [0, 255, 0])]
                .into_iter()
                .enumerate()
        {
            let (bytes, _, width, height) =
                native_image_source_input(&request.images[index]).expect("composited image");
            let decoded = image::load_from_memory(&bytes).expect("composited PNG");
            assert_eq!((width, height), expected_size);
            assert!(decoded.to_rgba8().pixels().all(|pixel| {
                [pixel[0], pixel[1], pixel[2]] == expected_rgb && pixel[3] == expected_alpha
            }));
        }
    }

    #[test]
    fn native_image_edit_file_mask_uses_retained_readers_and_preserves_pixels() {
        let data_dir = project_local_test_tmp_dir().join(format!(
            "native-image-file-mask-reader-{}",
            LOCAL_WRITE_SEQUENCE.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&data_dir).expect("test data directory");
        let temp = NativeImageTempGuard::create(&data_dir).expect("temp guard");

        let write_png = |temp: &NativeImageTempGuard,
                         name: &str,
                         image: image::DynamicImage|
         -> NativeImageFileHandle {
            let mut encoded = Cursor::new(Vec::new());
            image
                .write_to(&mut encoded, image::ImageFormat::Png)
                .expect("PNG fixture");
            let bytes = encoded.into_inner();
            let mut writer = temp.create_file(name).expect("file writer");
            let mut file = writer.take_file().expect("writer handle");
            file.write_all(&bytes).expect("write fixture");
            file.sync_all().expect("sync fixture");
            drop(file);
            writer.finalize(bytes.len()).expect("retained file handle")
        };

        let source_reads = Arc::new(AtomicUsize::new(0));
        let mask_reads = Arc::new(AtomicUsize::new(0));
        let mut source_handle = write_png(
            &temp,
            "source.png",
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                2,
                2,
                image::Rgba([255, 0, 0, 255]),
            )),
        );
        source_handle.read_observer = Some(source_reads.clone());
        let mut mask_handle = write_png(
            &temp,
            "mask.png",
            image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
                2,
                2,
                image::Rgba([0, 0, 0, 64]),
            )),
        );
        mask_handle.read_observer = Some(mask_reads.clone());

        let request = NativeImageRequest {
            model: "gpt-image-2".to_owned(),
            client_task_id: None,
            codex: false,
            plan_type: None,
            prompt: "edit".to_owned(),
            n: 1,
            size: None,
            quality: "auto".to_owned(),
            response_format: "b64_json".to_owned(),
            output_format: "png".to_owned(),
            output_compression: None,
            background: "auto".to_owned(),
            stream: false,
            message_as_error: false,
            images: vec![NativeImageSource::File {
                handle: source_handle,
                mime_type: "image/png".to_owned(),
                width: 2,
                height: 2,
            }],
            usage_images: None,
            usage_image_details: None,
            usage_image_dimensions: None,
            base_url: None,
            mask: vec![NativeImageSource::File {
                handle: mask_handle,
                mime_type: "image/png".to_owned(),
                width: 2,
                height: 2,
            }],
            temp_guard: Some(temp),
            progress_callback: None,
        };

        let request = native_apply_image_edit_mask(request).expect("file mask composition");
        assert_eq!(source_reads.load(Ordering::SeqCst), 0);
        assert_eq!(mask_reads.load(Ordering::SeqCst), 0);
        let NativeImageSource::File { handle, .. } = &request.images[0] else {
            panic!("file-backed composite expected");
        };
        let composite =
            native_decode_image(&handle.read().expect("composite bytes")).expect("composite PNG");
        for pixel in composite.to_rgba8().pixels() {
            assert_eq!(pixel.0, [255, 0, 0, 64]);
        }
        drop(request);
        let upload_root = data_dir.join(".native-image-uploads");
        assert!(
            fs::read_dir(&upload_root)
                .expect("upload parent")
                .next()
                .is_none()
        );
        fs::remove_dir_all(&data_dir).expect("cleanup test data directory");
    }

