    #[tokio::test]
    #[ignore = "v1.7 calls Codex Responses only for Codex image requests"]
    async fn native_responses_codex_text_supports_nonstream_and_stream() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let response_calls = Arc::new(AtomicUsize::new(0));
        let response_calls_for_upstream = response_calls.clone();
        let captured_payloads = Arc::new(Mutex::new(Vec::<Value>::new()));
        let captured_payloads_for_upstream = captured_payloads.clone();
        let hang_next = Arc::new(AtomicBool::new(false));
        let hang_next_for_upstream = hang_next.clone();
        let error_next = Arc::new(AtomicBool::new(false));
        let error_next_for_upstream = error_next.clone();
        let upstream = tokio::spawn(async move {
            let bootstrap = get(|| async {
                Html(
                    r#"<html data-build="c/test/_build"><script src="https://chatgpt.com/c/test/_sdk.js"></script></html>"#,
                )
            });
            let prepare = post(|| async { Json(json!({"prepare_token":"prepare-token"})) });
            let finalize = post(|| async { Json(json!({"token":"requirements-token"})) });
            let responses = post(move |headers: HeaderMap, Json(payload): Json<Value>| {
                let response_calls = response_calls_for_upstream.clone();
                let captured_payloads = captured_payloads_for_upstream.clone();
                let hang_next = hang_next_for_upstream.clone();
                let error_next = error_next_for_upstream.clone();
                async move {
                    assert_eq!(
                        headers
                            .get(header::AUTHORIZATION)
                            .and_then(|value| value.to_str().ok()),
                        Some("Bearer codex-token")
                    );
                    response_calls.fetch_add(1, Ordering::SeqCst);
                    captured_payloads.lock().await.push(payload);
                    if error_next.swap(false, Ordering::SeqCst) {
                        let chunks = stream::iter(vec![
                            Ok::<Bytes, std::io::Error>(Bytes::from(
                                "data: {\"type\":\"response.created\",\"response\":{\"id\":\"resp-error\"},\"sequence_number\":0}\n\n",
                            )),
                            Err(std::io::Error::other("upstream body error")),
                        ]);
                        return (
                            [(header::CONTENT_TYPE, "text/event-stream")],
                            Body::from_stream(chunks),
                        )
                            .into_response();
                    }
                    if hang_next.swap(false, Ordering::SeqCst) {
                        let first = stream::once(async {
                            Ok::<Bytes, std::convert::Infallible>(Bytes::from(
                                "data: {\"type\":\"response.created\",\"response\":{\"id\":\"resp-pending\"},\"sequence_number\":0}\n\n",
                            ))
                        });
                        let rest = stream::pending::<Result<Bytes, std::convert::Infallible>>();
                        return (
                            [(header::CONTENT_TYPE, "text/event-stream")],
                            Body::from_stream(first.chain(rest)),
                        )
                            .into_response();
                    }
                    (
                        [(header::CONTENT_TYPE, "text/event-stream")],
                        Body::from(
                            "data: {\"type\":\"response.created\",\"response\":{\"id\":\"resp-test\",\"model\":\"gpt-test\",\"status\":\"in_progress\"},\"sequence_number\":0}\n\n\
                             data: {\"type\":\"response.output_text.delta\",\"content_index\":0,\"item_id\":\"msg-1\",\"delta\":\"hello\",\"logprobs\":[],\"output_index\":0,\"sequence_number\":1}\n\n\
                             data: [DONE]\n\n\
                             data: {\"type\":\"response.completed\",\"sequence_number\":2,\"response\":{\"id\":\"resp-test\",\"model\":\"gpt-test\",\"status\":\"completed\",\"output\":[{\"type\":\"message\",\"id\":\"msg-1\",\"role\":\"assistant\",\"status\":\"completed\",\"content\":[{\"type\":\"output_text\",\"text\":\"hello\",\"annotations\":[]}]}]}}\n\n",
                        ),
                    )
                        .into_response()
                }
            });
            axum::serve(
                listener,
                Router::new()
                    .route("/", bootstrap)
                    .route("/backend-api/sentinel/chat-requirements/prepare", prepare)
                    .route("/backend-api/sentinel/chat-requirements/finalize", finalize)
                    .route(
                        "/backend-api/models",
                        get(|| async {
                            Json(json!({
                                "models": [{"slug":"gpt-test","supported_in_api":true}]
                            }))
                        }),
                    )
                    .route("/backend-api/codex/responses", responses),
            )
            .await
            .expect("upstream server");
        });

        let account_path = test_tmp_dir().join(format!(
            "chatgpt2api-rust-native-responses-{}-{}.json",
            std::process::id(),
            NATIVE_MESSAGE_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::write(
            &account_path,
            r#"[{"access_token":"codex-token","status":"正常","source_type":"codex","type":"free","models":["gpt-test"]}]"#,
        )
        .expect("account snapshot");
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        state
            .account_type_catalog
            .set_codex_client_version_for_test(Some("0.147.0".to_owned()));

        let nonstream = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/responses")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"model":"gpt-test","input":"hello"}"#))
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(nonstream.status(), StatusCode::OK);
        let body = nonstream
            .into_body()
            .collect()
            .await
            .expect("body")
            .to_bytes();
        let value: Value = serde_json::from_slice(&body).expect("response json");
        assert_eq!(value["id"], "resp-test");
        assert_eq!(value["output"][0]["content"][0]["text"], "hello");
        assert_eq!(state.account_store.inflight(), 0);

        error_next.store(true, Ordering::SeqCst);
        let response_error = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/responses")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","input":"error","stream":true}"#,
                    ))
                    .expect("error request"),
            )
            .await
            .expect("error response");
        assert_eq!(response_error.status(), StatusCode::BAD_GATEWAY);
        let response_error_body = response_error
            .into_body()
            .collect()
            .await
            .expect("Responses error envelope")
            .to_bytes();
        assert_eq!(
            serde_json::from_slice::<Value>(&response_error_body).expect("Responses error JSON")["error"]
                ["type"],
            "server_error"
        );
        assert_eq!(state.account_store.inflight(), 0);

        hang_next.store(true, Ordering::SeqCst);
        let pending = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/responses")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","input":"cancel","stream":true}"#,
                    ))
                    .expect("pending request"),
            )
            .await
            .expect("pending response");
        assert_eq!(pending.status(), StatusCode::OK);
        drop(pending);
        assert_eq!(state.account_store.inflight(), 0);

        let stream = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/responses")
                    .header(header::AUTHORIZATION, "Bearer client")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","input":"hello","stream":true}"#,
                    ))
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(stream.status(), StatusCode::OK);
        let body = stream
            .into_body()
            .collect()
            .await
            .expect("stream body")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("utf8 stream");
        assert!(text.contains("response.created"));
        assert!(text.contains("response.output_text.delta"));
        assert!(text.contains("response.completed"));
        assert_eq!(state.account_store.inflight(), 0);
        assert_eq!(response_calls.load(Ordering::SeqCst), 4);
        let payloads = captured_payloads.lock().await;
        assert_eq!(payloads.len(), 4);
        assert_eq!(payloads[0]["model"], "gpt-test");
        assert_eq!(payloads[0]["input"][0]["type"], "message");
        assert_eq!(payloads[0]["input"][0]["content"][0]["type"], "input_text");
        assert_eq!(payloads[0]["input"][0]["content"][0]["text"], "hello");
        assert_eq!(payloads[1]["input"][0]["content"][0]["text"], "error");
        assert_eq!(payloads[2]["input"][0]["content"][0]["text"], "cancel");
        assert_eq!(payloads[3]["input"][0]["content"][0]["text"], "hello");
        for payload in payloads.iter().skip(1) {
            assert_eq!(payload["stream"], true);
        }
        drop(payloads);

        error_next.store(true, Ordering::SeqCst);
        let anthropic_error = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "client")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r##"{"model":"gpt-test","max_tokens":8,"stream":true,"messages":[{"role":"user","content":"error"}]}"##,
                    ))
                    .expect("Anthropic error request"),
        )
            .await
            .expect("Anthropic error response");
        assert_eq!(anthropic_error.status(), StatusCode::BAD_GATEWAY);
        let anthropic_error_body = anthropic_error
            .into_body()
            .collect()
            .await
            .expect("Anthropic error envelope")
            .to_bytes();
        assert_eq!(
            serde_json::from_slice::<Value>(&anthropic_error_body).expect("Anthropic error JSON")["error"]
                ["type"],
            "server_error"
        );
        assert_eq!(state.account_store.inflight(), 0);

        hang_next.store(true, Ordering::SeqCst);
        let anthropic_pending = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "client")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r##"{"model":"gpt-test","max_tokens":8,"stream":true,"messages":[{"role":"user","content":"cancel"}]}"##,
                    ))
                    .expect("pending Anthropic request"),
            )
            .await
            .expect("pending Anthropic response");
        assert_eq!(anthropic_pending.status(), StatusCode::OK);
        drop(anthropic_pending);
        assert_eq!(state.account_store.inflight(), 0);

        let anthropic = state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/messages")
                    .header("x-api-key", "client")
                    .header("anthropic-version", "2023-06-01")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r##"{"model":"gpt-test","max_tokens":8,"stream":true,"messages":[{"role":"user","content":"hello"}]}"##,
                    ))
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(anthropic.status(), StatusCode::OK);
        let body = anthropic
            .into_body()
            .collect()
            .await
            .expect("Anthropic body")
            .to_bytes();
        let text = String::from_utf8(body.to_vec()).expect("Anthropic SSE");
        assert!(text.contains("content_block_start"));
        assert!(text.contains("text_delta"));
        assert!(text.contains("message_stop"));
        assert_eq!(state.account_store.inflight(), 0);
        assert_eq!(response_calls.load(Ordering::SeqCst), 7);
        let payloads = captured_payloads.lock().await;
        assert_eq!(payloads.len(), 7);
        assert_eq!(payloads[4]["input"][0]["content"][0]["text"], "error");
        assert_eq!(payloads[5]["input"][0]["content"][0]["text"], "cancel");
        assert_eq!(payloads[6]["input"][0]["content"][0]["text"], "hello");

        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
        fs::remove_file(account_path).expect("cleanup");
    }

    #[test]
    fn public_search_projection_skips_non_messages_and_unknown_urls() {
        let secret_url = "https://secret.example/private";
        let conversation = json!({
            "mapping": {
                "root": {"message": null},
                "metadata-only": {"private": {"url": secret_url}},
                "non-object": "ignored",
                "assistant": {"message": {
                    "id": "assistant-message-1",
                    "author": {"role": "assistant"},
                    "create_time": 1.0,
                    "content": {"parts": ["answer"]},
                    "metadata": {
                        "finish_details": {"type": "finished_successfully"},
                        "sources": [{"title": "Known", "url": "https://known.example/path#frag", "snippet": "known", "source_type": "web"}],
                        "private": {"url": secret_url, "token": "credential-canary"}
                    }
                }}
            }
        });
        let internal = extract_search_result("conversation-1", &conversation);
        assert_eq!(internal["assistant_message_id"], "assistant-message-1");
        assert_eq!(internal["create_time"], 1.0);
        assert_eq!(internal["sources"][0]["source_type"], "web");
        let projected = project_public_search_result(&internal);
        assert_eq!(projected["answer"], "answer");
        assert_eq!(
            projected["sources"],
            json!([{"title":"Known", "url":"https://known.example/path", "snippet":"known", "source_type":"web"}])
        );
        assert_eq!(projected["assistant_message_id"], "assistant-message-1");
        assert_eq!(projected["create_time"], 1.0);
        assert!(!projected.to_string().contains(secret_url));
        assert!(!projected.to_string().contains("credential-canary"));
    }

    #[test]
    fn public_search_projection_is_bounded_and_drops_internal_fields() {
        let secret = "search-public-secret";
        let long = "x".repeat(NATIVE_SEARCH_MAX_FIELD_CHARS + 500);
        let internal = json!({
            "conversation_id": "not valid id",
            "status": "custom-upstream-status",
            "answer": "answer",
            "assistant_message_id": "assistant-id",
            "create_time": 123.0,
            "access_token": secret,
            "private": {"url": "https://secret.example/hidden"},
            "sources": [
                {"title": long, "url": "https://example.test/a#one", "snippet": long, "source_type": "web"},
                {"title": "duplicate", "url": "https://example.test/a#two", "snippet": "drop", "source_type": "private"},
                {"title": "bad", "url": "https://example.test/%GG", "snippet": "drop"}
            ]
        });
        let projected = project_public_search_result(&internal);
        assert_eq!(projected["answer"], "answer");
        assert!(projected.get("conversation_id").is_none());
        assert_eq!(projected["status"], "custom-upstream-status");
        assert_eq!(projected["assistant_message_id"], "assistant-id");
        assert_eq!(projected["create_time"], 123.0);
        assert_eq!(projected["sources"].as_array().expect("sources").len(), 1);
        assert_eq!(
            projected["sources"][0]["title"]
                .as_str()
                .expect("title")
                .chars()
                .count(),
            NATIVE_SEARCH_MAX_FIELD_CHARS
        );
        assert_eq!(
            projected["sources"][0]["snippet"]
                .as_str()
                .expect("snippet")
                .chars()
                .count(),
            NATIVE_SEARCH_MAX_FIELD_CHARS
        );
        let text = projected.to_string();
        for canary in [secret, "private"] {
            assert!(!text.contains(canary), "leaked {canary}");
        }
        let capped = project_public_search_result(&json!({
            "answer": "answer",
            "sources": (0..(NATIVE_SEARCH_MAX_SOURCES + 1))
                .map(|index| json!({"url": format!("https://example.test/{index}")}))
                .collect::<Vec<_>>()
        }));
        assert_eq!(
            capped["sources"].as_array().expect("capped sources").len(),
            NATIVE_SEARCH_MAX_SOURCES
        );
    }

    #[test]
    fn native_search_status_uses_bounded_known_container_fallback() {
        let conversation = json!({
            "mapping": {
                "root": {"message": null},
                "assistant": {"message": {
                    "author": {"role": "assistant"},
                    "content": {"parts": [{"status": "finished_partial_completion"}, "answer"]},
                    "private": {"status": "must-not-use"}
                }}
            }
        });
        let internal = extract_search_result("conversation-1", &conversation);
        assert_eq!(internal["status"], "finished_partial_completion");

        let unsafe_only = json!({
            "mapping": {"assistant": {"message": {
                "author": {"role": "assistant"},
                "content": {"parts": ["answer"]},
                "private": {"status": "finished_successfully"}
            }}}
        });
        assert_eq!(
            extract_search_result("conversation-1", &unsafe_only)["status"],
            ""
        );
    }

    #[test]
    fn native_search_sources_recurse_and_extract_urls_from_prose() {
        let conversation = json!({
            "mapping": {"assistant": {"message": {
                "author": {"role":"assistant"},
                "content": {"parts": [
                    "Read (https://example.test/prose).",
                    {"citation": {"url":"https://example.test/nested","title":"Nested","snippet":"Nested citation"}}
                ]}
            }}}
        });
        let result = extract_search_result("conversation-1", &conversation);
        assert_eq!(result["sources"].as_array().unwrap().len(), 2);
        assert_eq!(result["sources"][0]["url"], "https://example.test/nested");
        assert_eq!(result["sources"][0]["title"], "Nested");
        assert_eq!(result["sources"][1]["url"], "https://example.test/prose");
    }
