    #[test]
    fn native_image_decoder_accepts_python_common_pillow_formats() {
        let source = image::RgbImage::from_pixel(3, 2, image::Rgb([12, 34, 56]));
        for (format, expected_mime) in [
            (image::ImageFormat::Bmp, "image/bmp"),
            (image::ImageFormat::Gif, "image/gif"),
            (image::ImageFormat::Jpeg, "image/jpeg"),
            (image::ImageFormat::Png, "image/png"),
            (image::ImageFormat::Pnm, "image/x-portable-anymap"),
            (image::ImageFormat::Tga, "image/x-tga"),
            (image::ImageFormat::Tiff, "image/tiff"),
            (image::ImageFormat::WebP, "image/webp"),
        ] {
            let mut encoded = Cursor::new(Vec::new());
            image::DynamicImage::ImageRgb8(source.clone())
                .write_to(&mut encoded, format)
                .unwrap_or_else(|error| panic!("encode {format:?}: {error}"));
            let mime = native_image_mime_type(format).expect("supported input MIME");
            assert_eq!(mime, expected_mime, "format={format:?}");
            let data_url = format!(
                "data:{mime};base64,{}",
                base64::engine::general_purpose::STANDARD.encode(encoded.get_ref())
            );
            let (_, actual_mime, width, height) = native_image_input(&data_url)
                .unwrap_or_else(|error| panic!("decode {format:?}: {}", error.code()));
            assert_eq!(actual_mime, expected_mime, "format={format:?}");
            assert_eq!((width, height), (3, 2), "format={format:?}");
        }
        assert!(
            native_image_input("data:image/x-tga;base64,AAAAAAAAAAAAAAAAAAAAAAAAAAA=").is_err()
        );
        assert_eq!(
            native_image_mime_from_path("/source/image.TIFF"),
            Some("image/tiff")
        );
        assert_eq!(
            native_image_mime_from_path("/source/image.tga"),
            Some("image/x-tga")
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn native_image_reference_download_matches_python_mime_and_size_rules() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("image reference listener");
        let address = listener.local_addr().expect("image reference address");
        let mut png = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
            2,
            3,
            image::Rgba([1, 2, 3, 255]),
        ))
        .write_to(&mut png, image::ImageFormat::Png)
        .expect("PNG fixture");
        let png_bytes = png.into_inner();
        let mut jpeg = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(2, 3, image::Rgb([7, 8, 9])))
            .write_to(&mut jpeg, image::ImageFormat::Jpeg)
            .expect("JPEG fixture");
        let jpeg_bytes = jpeg.into_inner();
        let image_for_server = png_bytes.clone();
        let jpeg_for_server = jpeg_bytes.clone();
        let upstream = tokio::spawn(async move {
            let ready_route = get(|| async { StatusCode::NO_CONTENT });
            let png_route = get(move || {
                let bytes = image_for_server.clone();
                async move { ([(header::CONTENT_TYPE, "application/octet-stream")], bytes) }
            });
            let invalid_route =
                get(|| async { ([(header::CONTENT_TYPE, "text/plain")], "not an image") });
            let oversized_route = get(|| async {
                let mut response = Response::new(Body::empty());
                *response.status_mut() = StatusCode::OK;
                response
                    .headers_mut()
                    .insert(header::CONTENT_TYPE, HeaderValue::from_static("image/png"));
                response
                    .headers_mut()
                    .insert(header::CONTENT_LENGTH, HeaderValue::from_static("10485761"));
                response
            });
            let mislabelled_route = get(move || {
                let bytes = jpeg_for_server.clone();
                async move { ([(header::CONTENT_TYPE, "image/svg+xml")], bytes) }
            });
            axum::serve(
                listener,
                Router::new()
                    .route("/ready", ready_route)
                    .route("/source.png", png_route)
                    .route("/not-image.png", invalid_route)
                    .route("/oversized.png", oversized_route)
                    .route("/mislabelled.png", mislabelled_route),
            )
            .await
            .expect("image reference server");
        });
        wait_for_test_http_ready(&format!("http://{address}"), "/ready").await;
        let state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["gpt-image-2".to_owned()],
            upstream_base_url: None,
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let mut anthropic_request = json!({
            "messages":[{"role":"user","content":[{
                "type":"image_url",
                "image_url":{"url":format!("http://{address}/source.png")}
            }]}]
        })
        .as_object()
        .cloned()
        .expect("Anthropic request object");
        resolve_anthropic_remote_image_urls(&state, &mut anthropic_request)
            .await
            .expect("Python downloads remote Anthropic image URLs before chat conversion");
        assert!(
            anthropic_request["messages"][0]["content"][0]["image_url"]["url"]
                .as_str()
                .unwrap_or_default()
                .starts_with("data:image/png;base64,")
        );
        let mut anthropic_legacy_image_request = json!({
            "messages":[{"role":"user","content":[{
                "type":"image",
                "url":format!("http://{address}/source.png")
            }]}]
        })
        .as_object()
        .cloned()
        .expect("legacy Anthropic image request object");
        resolve_anthropic_remote_image_urls(&state, &mut anthropic_legacy_image_request)
            .await
            .expect("type=image remote URL is downloaded");
        assert!(
            anthropic_legacy_image_request["messages"][0]["content"][0]["url"]
                .as_str()
                .unwrap_or_default()
                .starts_with("data:image/png;base64,")
        );

        let mut oversized_request = json!({
            "messages":[{"role":"user","content":[{
                "type":"image_url",
                "image_url":{"url":format!("http://{address}/oversized.png")}
            }]}]
        })
        .as_object()
        .cloned()
        .expect("oversized Anthropic request object");
        assert!(
            resolve_anthropic_remote_image_urls(&state, &mut oversized_request)
                .await
                .is_err()
        );
        let remote =
            native_image_reference_source(&state, &format!("http://{address}/source.png"), false)
                .await
                .expect("octet-stream image inferred from URL suffix");
        let NativeImageSource::Text(remote) = remote else {
            panic!("downloaded image should be inline data");
        };
        let (downloaded, mime, width, height) =
            native_image_input(&remote).expect("downloaded data URL");
        assert_eq!(mime, "image/png");
        assert_eq!((width, height), (2, 3));
        assert_eq!(downloaded, png_bytes);
        assert!(
            native_image_reference_source(
                &state,
                &format!("http://{address}/not-image.png"),
                false,
            )
            .await
            .is_err()
        );
        let mislabelled = native_image_reference_source(
            &state,
            &format!("http://{address}/mislabelled.png"),
            false,
        )
        .await
        .expect("Pillow uses the decoded image format for upload MIME");
        let NativeImageSource::Text(mislabelled) = mislabelled else {
            panic!("remote image should be inline data");
        };
        let (decoded_jpeg, actual_jpeg_mime, width, height) =
            native_image_input(&mislabelled).expect("mislabelled JPEG bytes still decode");
        assert_eq!(actual_jpeg_mime, "image/jpeg");
        assert_eq!((width, height), (2, 3));
        assert_eq!(decoded_jpeg, jpeg_bytes);

        let encoded =
            percent_encoding::percent_encode(&downloaded, percent_encoding::NON_ALPHANUMERIC)
                .to_string();
        let (decoded, data_mime, decoded_width, decoded_height) =
            native_image_input(&format!("data:image/png,{encoded}"))
                .expect("Python-compatible percent-encoded data URL");
        assert_eq!(data_mime, "image/png");
        assert_eq!((decoded_width, decoded_height), (2, 3));
        assert_eq!(decoded, downloaded);

        state.account_type_catalog.shutdown().await;
        upstream.abort();
        let _ = upstream.await;
    }

